// Package lint holds the core linting engine.
package lint

import (
	"go/ast"
	"go/token"
)

// Failure categories.
const (
	FailureCategoryArgOrder        = "arg-order"
	FailureCategoryBadPractice     = "bad practice"
	FailureCategoryCodeStyle       = "code-style"
	FailureCategoryComments        = "comments"
	FailureCategoryComplexity      = "complexity"
	FailureCategoryContent         = "content"
	FailureCategoryErrors          = "errors"
	FailureCategoryImports         = "imports"
	FailureCategoryLogic           = "logic"
	FailureCategoryMaintenance     = "maintenance"
	FailureCategoryNaming          = "naming"
	FailureCategoryOptimization    = "optimization"
	FailureCategoryStyle           = "style"
	FailureCategoryTime            = "time"
	FailureCategoryTypeInference   = "type-inference"
	FailureCategoryUnaryOp         = "unary-op"
	FailureCategoryUnexportedType  = "unexported-type-in-api"
	FailureCategoryZeroValue       = "zero-value"
	failureCategoryInternal        = "REVIVE_INTERNAL"
	failureCategoryValidity        = "validity"
)

// FailurePosition holds the start and end positions of a failure.
type FailurePosition struct {
	Start token.Position
	End   token.Position
}

// Failure is a lint failure.
type Failure struct {
	Failure         string
	RuleName        string
	Category        string
	Position        FailurePosition
	Node            ast.Node `json:"-"`
	Confidence      float64
	ReplacementLine string
}

// GetFilename returns the filename of the failure.
func (f *Failure) GetFilename() string {
	return f.Position.Start.Filename
}

// IsInternal reports whether the failure is an internal one.
func (f *Failure) IsInternal() bool {
	return f.Category == failureCategoryInternal
}

// NewInternalFailure creates an internal failure.
func NewInternalFailure(msg string) Failure {
	return Failure{Category: failureCategoryInternal, Failure: msg}
}

// ToFailurePosition converts AST positions into a failure position.
func ToFailurePosition(start, end token.Pos, file *File) FailurePosition {
	return FailurePosition{
		Start: file.ToPosition(start),
		End:   file.ToPosition(end),
	}
}
EOF
