package lint

import (
	"github.com/revivelint/revive/internal/version"
)

// Severity is the level of a failure.
type Severity string

// Severity values.
const (
	SeverityWarning = "warning"
	SeverityError   = "error"
)

// RuleConfig is the configuration of a rule.
type RuleConfig struct {
	Arguments Arguments
	Severity  Severity
	Disabled  bool
	Exclude   []string

	excludeFilters []*FileFilter
}

// Initialize prepares the rule config.
func (rc *RuleConfig) Initialize() error {
	for _, f := range rc.Exclude {
		ff, err := ParseFileFilter(f)
		if err != nil {
			return err
		}
		rc.excludeFilters = append(rc.excludeFilters, ff)
	}
	return nil
}

// MustExclude reports whether the rule must be skipped for the file.
func (rc *RuleConfig) MustExclude(name string) bool {
	for _, ff := range rc.excludeFilters {
		if ff.MatchFileName(name) {
			return true
		}
	}
	return false
}

// RulesConfig is the configuration of all rules.
type RulesConfig = map[string]RuleConfig

// DirectiveConfig is the configuration of a directive.
type DirectiveConfig struct {
	Severity Severity
