// Package version implements semantic-ish version parsing and comparison.
package version

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

const versionRegexpRaw = `v?([0-9]+(\.[0-9]+)*?)` +
	`(-([0-9]+[0-9A-Za-z\-~]*(\.[0-9A-Za-z\-~]+)*)|(-?([A-Za-z\-~]+[0-9A-Za-z\-~]*(\.[0-9A-Za-z\-~]+)*)))?` +
	`(\+([0-9A-Za-z\-~]+(\.[0-9A-Za-z\-~]+)*))?` +
	`?`

var versionRegexp = regexp.MustCompile("^" + versionRegexpRaw + "$")

// Version is a parsed version.
type Version struct {
	segments []int64
	pre      string
	metadata string
	original string
}

// NewVersion parses a version string.
func NewVersion(v string) (*Version, error) {
	matches := versionRegexp.FindStringSubmatch(v)
	if matches == nil {
		return nil, fmt.Errorf("malformed version: %s", v)
	}
	segmentsStr := strings.Split(matches[1], ".")
	segments := make([]int64, len(segmentsStr))
	for i, str := range segmentsStr {
		val, err := strconv.ParseInt(str, 10, 64)
		if err != nil {
