package lint

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"go/token"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"

	"golang.org/x/mod/modfile"

	"github.com/revivelint/revive/internal/version"
)

// ReadFile defines an abstraction for reading files.
type ReadFile func(path string) (result []byte, err error)

// Linter is used for linting set of files.
type Linter struct {
	reader ReadFile
}

// New creates a new Linter.
func New(reader ReadFile) Linter {
	return Linter{reader: reader}
}

var (
	genHdr = []byte("// Code generated ")
	genFtr = []byte(" DO NOT EDIT.")
)

var defaultGoVersion = version.Must(version.NewVersion("1.0"))

// Lint lints a set of files with the specified rule.
func (l *Linter) Lint(packages [][]string, ruleSet []Rule, config Config) ([]Failure, error) {
	var failures []Failure
	perModVersions := map[string]*version.Version{}
	var modDirs []string
	perPkgVersions := make([]*version.Version, len(packages))
	for n, files := range packages {
		if len(files) == 0 {
			continue
		}
		if config.GoVersion != nil {
			perPkgVersions[n] = config.GoVersion
			continue
		}
		dir, err := filepath.Abs(filepath.Dir(files[0]))
		if err != nil {
			return nil, err
		}
		alreadyKnown := false
		for _, d := range modDirs {
			if strings.HasPrefix(dir, d) {
				perPkgVersions[n] = perModVersions[d]
				alreadyKnown = true
				break
			}
		}
		if alreadyKnown {
			continue
		}
		d, v, err := detectGoMod(dir)
		if err != nil {
			perPkgVersions[n] = defaultGoVersion
			continue
		}
		perModVersions[d] = v
		modDirs = append(modDirs, d)
		perPkgVersions[n] = v
	}

	for n := range packages {
		if err := l.lintPackage(packages[n], perPkgVersions[n], ruleSet, config, &failures); err != nil {
			return nil, err
		}
	}
	return failures, nil
}

func (l *Linter) lintPackage(filenames []string, gover *version.Version, ruleSet []Rule, config Config, failures *[]Failure) error {
	if len(filenames) == 0 {
		return nil
	}
	pkg := &Package{
		fset:      token.NewFileSet(),
		files:     map[string]*File{},
		goVersion: gover,
	}
	for _, filename := range filenames {
		content, err := l.reader(filename)
		if err != nil {
			return err
		}
		if !config.IgnoreGeneratedHeader && isGenerated(content) {
			continue
		}
		file, err := NewFile(filename, content, pkg)
		if err != nil {
			addInvalidFileFailure(filename, err.Error(), failures)
			continue
		}
		if _, ok := pkg.files[filename]; !ok {
			pkg.fileOrder = append(pkg.fileOrder, filename)
		}
		pkg.files[filename] = file
	}
	if len(pkg.files) == 0 {
		return nil
	}
	return pkg.lint(ruleSet, config, failures)
}

func detectGoMod(dir string) (rootDir string, ver *version.Version, err error) {
	modFileName, err := retrieveModFile(dir)
	if err != nil {
		return "", nil, fmt.Errorf("%q doesn't seem to be part of a Go module", dir)
	}
	mod, err := os.ReadFile(modFileName)
	if err != nil {
		return "", nil, fmt.Errorf("failed to read %q, got %w", modFileName, err)
	}
	modAst, err := modfile.ParseLax(modFileName, mod, nil)
	if err != nil {
		return "", nil, fmt.Errorf("failed to parse %q, got %w", modFileName, err)
	}
	if modAst.Go == nil {
		return "", nil, fmt.Errorf("%q does not specify a Go version", modFileName)
	}
	ver, err = version.NewVersion(modAst.Go.Version)
	return filepath.Dir(modFileName), ver, err
}

func retrieveModFile(dir string) (string, error) {
	const lookingForFile = "go.mod"
	for {
		if dir == "." || dir == "/" {
			return "", fmt.Errorf("did not found %q file", lookingForFile)
		}
		lookingForFilePath := filepath.Join(dir, lookingForFile)
		info, err := os.Stat(lookingForFilePath)
		if err != nil || info.IsDir() {
			dir = filepath.Dir(dir)
			continue
		}
		return lookingForFilePath, nil
	}
}

// isGenerated reports whether the source file is generated code.
func isGenerated(src []byte) bool {
	sc := bufio.NewScanner(bytes.NewReader(src))
	for sc.Scan() {
		b := sc.Bytes()
		if bytes.HasPrefix(b, genHdr) && bytes.HasSuffix(b, genFtr) && len(b) >= len(genHdr)+len(genFtr) {
			return true
		}
	}
	return false
}

func addInvalidFileFailure(filename, errStr string, failures *[]Failure) {
	position := getPositionInvalidFile(filename, errStr)
	*failures = append(*failures, Failure{
		Confidence: 1,
		Failure:    fmt.Sprintf("invalid file %s: %v", filename, errStr),
		Category:   failureCategoryValidity,
		Position:   position,
	})
}

var errPosRegexp = regexp.MustCompile(`.*:(\d*):(\d*):.*$`)

func getPositionInvalidFile(filename, s string) FailurePosition {
	pos := errPosRegexp.FindStringSubmatch(s)
	if len(pos) < 3 {
		return FailurePosition{}
	}
	line, err := strconv.Atoi(pos[1])
	if err != nil {
		return FailurePosition{}
	}
	column, err := strconv.Atoi(pos[2])
	if err != nil {
		return FailurePosition{}
	}
	return FailurePosition{
		Start: token.Position{
			Filename: filename,
			Line:     line,
			Column:   column,
		},
	}
}

var _ = errors.New
EOF
"}

