package formatter

import (
	"bytes"
	"fmt"
	"io"
	"sort"

	"github.com/fatih/color"

	"github.com/revivelint/revive/internal/lint"
)

func getErrorEmoji() string   { return color.RedString("✘") }
func getWarningEmoji() string { return color.YellowString("⚠") }

// Friendly is the friendly formatter.
type Friendly struct{}

// Name returns the name of the formatter.
func (*Friendly) Name() string { return "friendly" }

// Format formats the failures.
func (f *Friendly) Format(failures []lint.Failure, config lint.Config) (string, error) {
	var buf bytes.Buffer
	errorMap := map[string]int{}
	warningMap := map[string]int{}
	totalErrors := 0
	totalWarnings := 0
	for _, failure := range failures {
		sev := severity(config, failure)
		f.printFriendlyFailure(&buf, failure, sev)
		switch sev {
		case lint.SeverityWarning:
			warningMap[failure.RuleName]++
			totalWarnings++
		case lint.SeverityError:
			errorMap[failure.RuleName]++
			totalErrors++
		}
	}
	f.printSummary(&buf, totalErrors, totalWarnings)
	f.printStatistics(&buf, color.RedString("Errors:"), errorMap)
	f.printStatistics(&buf, color.YellowString("Warnings:"), warningMap)
	return buf.String(), nil
}

func (f *Friendly) printFriendlyFailure(w io.Writer, failure lint.Failure, sev lint.Severity) {
	f.printHeaderRow(w, failure, sev)
	f.printFilePosition(w, failure)
	fmt.Fprintln(w)
	fmt.Fprintln(w)
}

func (f *Friendly) printHeaderRow(w io.Writer, failure lint.Failure, sev lint.Severity) {
	emoji := getWarningEmoji()
	if sev == lint.SeverityError {
		emoji = getErrorEmoji()
	}
	fmt.Fprint(w, f.table([][]string{{emoji, ruleDescriptionURL(failure.RuleName), color.GreenString(failure.Failure)}}))
}

func (*Friendly) printFilePosition(w io.Writer, failure lint.Failure) {
	fmt.Fprintf(w, "  %s:%d:%d", failure.GetFilename(), failure.Position.Start.Line, failure.Position.Start.Column)
}

type statEntry struct {
	name     string
	failures int
}

func (*Friendly) printSummary(w io.Writer, errors, warnings int) {
	emoji := getWarningEmoji()
	if errors > 0 {
		emoji = getErrorEmoji()
	}
	problemsLabel := "problems"
	if errors+warnings == 1 {
		problemsLabel = "problem"
	}
	warningsLabel := "warnings"
	if warnings == 1 {
		warningsLabel = "warning"
	}
	errorsLabel := "errors"
	if errors == 1 {
		errorsLabel = "error"
	}
	str := fmt.Sprintf("%d %s (%d %s, %d %s)", errors+warnings, problemsLabel, errors, errorsLabel, warnings, warningsLabel)
	if errors > 0 {
		fmt.Fprintf(w, "%s %s\n", emoji, color.New(color.Bold).SprintFunc()(color.RedString(str)))
		fmt.Fprintln(w)
		return
	}
	if warnings > 0 {
		fmt.Fprintf(w, "%s %s\n", emoji, color.New(color.Bold).SprintFunc()(color.YellowString(str)))
		fmt.Fprintln(w)
		return
	}
}

func (f *Friendly) printStatistics(w io.Writer, header string, stats map[string]int) {
	if len(stats) == 0 {
		return
	}
	var data []statEntry
	for name, total := range stats {
		data = append(data, statEntry{name, total})
	}
	sort.Slice(data, func(i, j int) bool {
		if data[i].failures != data[j].failures {
			return data[i].failures > data[j].failures
		}
		return data[i].name < data[j].name
	})
	formatted := [][]string{}
	for _, entry := range data {
		formatted = append(formatted, []string{color.GreenString(fmt.Sprintf("%d", entry.failures)), entry.name})
	}
	fmt.Fprintln(w, header)
	fmt.Fprintln(w, f.table(formatted))
}

func (*Friendly) table(rows [][]string) string {
	return textTable(rows, visibleWidth)
}
