package formatter

import (
	"fmt"
	"sort"

	"github.com/fatih/color"

	"github.com/revivelint/revive/internal/lint"
)

// Stylish is the stylish formatter.
type Stylish struct{}

// Name returns the name of the formatter.
func (*Stylish) Name() string { return "stylish" }

func formatFailure(failure lint.Failure, sev lint.Severity) []string {
	fString := color.CyanString(failure.Failure)
	fURL := ruleDescriptionURL(failure.RuleName)
	fName := color.RedString(fURL)
	lineColumn := failure.Position
	pos := color.MagentaString(fmt.Sprintf("(%d, %d)", lineColumn.Start.Line, lineColumn.Start.Column))
	if sev == lint.SeverityWarning {
		fName = color.YellowString(fURL)
	}
	return []string{failure.GetFilename(), pos, fName, fString}
}

// Format formats the failures.
func (*Stylish) Format(failures []lint.Failure, config lint.Config) (string, error) {
	var result [][]string
	totalErrors := 0
	total := 0
	for _, f := range failures {
		total++
		currentType := severity(config, f)
		if currentType == lint.SeverityError {
			totalErrors++
		}
		result = append(result, formatFailure(f, currentType))
	}
	ps := "problems"
	if total == 1 {
		ps = "problem"
	}

	fileReport := map[string][][]string{}
	var fileOrder []string
	for _, row := range result {
		if _, ok := fileReport[row[0]]; !ok {
			fileReport[row[0]] = [][]string{}
			fileOrder = append(fileOrder, row[0])
		}
		fileReport[row[0]] = append(fileReport[row[0]], []string{row[1], row[2], row[3]})
	}
	sort.Strings(fileOrder)

	output := ""
	for _, filename := range fileOrder {
		val := fileReport[filename]
		c := color.New(color.Underline)
		output += c.SprintfFunc()(filename + "\n")
		output += textTable(val, visibleWidth) + "\n"
	}

	errs := "errors"
	if totalErrors == 1 {
		errs = "error"
	}
	warns := "warnings"
	if total-totalErrors == 1 {
		warns = "warning"
	}
	suffix := fmt.Sprintf(" %d %s (%d %s) (%d %s)", total, ps, totalErrors, errs, total-totalErrors, warns)

	switch {
	case total > 0 && totalErrors > 0:
		suffix = color.RedString("\n ✖" + suffix)
	case total > 0 && totalErrors == 0:
		suffix = color.YellowString("\n ✖" + suffix)
	default:
		suffix, output = "", ""
	}
	return output + suffix, nil
}
EOF
cat > checkstyle.go <<'EOF'
package formatter

import (
	"bytes"
	"text/template"

	"github.com/revivelint/revive/internal/lint"
)

// Checkstyle is the checkstyle formatter.
type Checkstyle struct{}

// Name returns the name of the formatter.
func (*Checkstyle) Name() string { return "checkstyle" }

type issue struct {
	Line       int
	Col        int
	What       string
	Confidence float64
	Severity   lint.Severity
	RuleName   string
}

const checkstyleTemplate = `<?xml version='1.0' encoding='UTF-8'?>
<checkstyle version="5.0">
{{- range $k, $v := . }}
    <file name="{{ $k }}">
      {{- range $i, $issue := $v }}
      <error line="{{ $issue.Line }}" column="{{ $issue.Col }}" message="{{ $issue.What | html }} (confidence {{ $issue.Confidence}})" severity="{{ $issue.Severity }}" source="revive/{{ $issue.RuleName }}"/>
      {{- end }}
    </file>
{{- end }}
</checkstyle>`

// Format formats the failures.
func (*Checkstyle) Format(failures []lint.Failure, config lint.Config) (string, error) {
	issues := map[string][]issue{}
	for _, failure := range failures {
		buf := new(bytes.Buffer)
		template.HTMLEscape(buf, []byte(failure.Failure))
		fn := failure.GetFilename()
		iss := issue{
			Line:       failure.Position.Start.Line,
			Col:        failure.Position.Start.Column,
			What:       failure.Failure,
			Confidence: failure.Confidence,
			Severity:   severity(config, failure),
			RuleName:   failure.RuleName,
		}
		issues[fn] = append(issues[fn], iss)
	}
	t, err := template.New("revive").Parse(checkstyleTemplate)
	if err != nil {
		return "", err
	}
	buf := new(bytes.Buffer)
	if err := t.Execute(buf, issues); err != nil {
		return "", err
	}
	return buf.String(), nil
}
EOF
"}

