package formatter

import (
	"bytes"
	"text/template"

	"github.com/revivelint/revive/internal/lint"
)

// Checkstyle is the checkstyle formatter.
type Checkstyle struct{}

// Name returns the name of the formatter.
func (*Checkstyle) Name() string { return "checkstyle" }

type issue struct {
	Line       int
	Col        int
	What       string
	Confidence float64
	Severity   lint.Severity
	RuleName   string
}

const checkstyleTemplate = `<?xml version='1.0' encoding='UTF-8'?>
<checkstyle version="5.0">
{{- range $k, $v := . }}
    <file name="{{ $k }}">
      {{- range $i, $issue := $v }}
      <error line="{{ $issue.Line }}" column="{{ $issue.Col }}" message="{{ $issue.What | html }} (confidence {{ $issue.Confidence}})" severity="{{ $issue.Severity }}" source="revive/{{ $issue.RuleName }}"/>
      {{- end }}
    </file>
{{- end }}
</checkstyle>`

// Format formats the failures.
func (*Checkstyle) Format(failures []lint.Failure, config lint.Config) (string, error) {
	issues := map[string][]issue{}
	for _, failure := range failures {
		buf := new(bytes.Buffer)
		template.HTMLEscape(buf, []byte(failure.Failure))
		fn := failure.GetFilename()
		iss := issue{
			Line:       failure.Position.Start.Line,
			Col:        failure.Position.Start.Column,
			What:       failure.Failure,
			Confidence: failure.Confidence,
			Severity:   severity(config, failure),
			RuleName:   failure.RuleName,
		}
		issues[fn] = append(issues[fn], iss)
	}
	t, err := template.New("revive").Parse(checkstyleTemplate)
	if err != nil {
		return "", err
	}
	buf := new(bytes.Buffer)
	if err := t.Execute(buf, issues); err != nil {
		return "", err
	}
	return buf.String(), nil
}
EOF

