// Package config handles revive configuration.
package config

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"

	"github.com/BurntSushi/toml"

	"github.com/revivelint/revive/internal/formatter"
	"github.com/revivelint/revive/internal/lint"
	"github.com/revivelint/revive/internal/rule"
)

const defaultConfidence = 0.8

func getRulesMap() map[string]lint.Rule {
	m := map[string]lint.Rule{}
	for _, r := range rule.AllRules() {
		m[r.Name()] = r
	}
	if r, ok := m["imports-blocklist"]; ok {
		m["imports-blacklist"] = r
	}
	return m
}

// GetLintingRules yields the linting rules that must be applied by the linter.
func GetLintingRules(config *lint.Config) ([]lint.Rule, error) {
	rulesMap := getRulesMap()
	names := make([]string, 0, len(config.Rules))
	for name := range config.Rules {
		names = append(names, name)
	}
	// unknown rules are reported first, deterministically
	sort.Strings(names)
	for _, name := range names {
		if _, ok := rulesMap[name]; !ok {
			return nil, fmt.Errorf("cannot find rule: %s", name)
		}
	}
	// "imports-blacklist" is an alias; configure it before the canonical one
	// so that the canonical configuration wins.
	configureOrder := make([]string, 0, len(names))
	for _, n := range names {
		if n == "imports-blacklist" {
			configureOrder = append([]string{n}, configureOrder...)
			continue
		}
		configureOrder = append(configureOrder, n)
	}
	configured := map[string]lint.Rule{}
	var lintingRules []lint.Rule
	for _, name := range configureOrder {
		ruleConfig := config.Rules[name]
		r := rulesMap[name]
		if ruleConfig.Disabled {
			continue
		}
		if cr, ok := r.(lint.ConfigurableRule); ok {
			if err := cr.Configure(ruleConfig.Arguments); err != nil {
				return nil, fmt.Errorf("cannot configure rule: %q: %w", name, err)
			}
		}
		configured[name] = r
	}
	for _, name := range names {
		if r, ok := configured[name]; ok {
			lintingRules = append(lintingRules, r)
		}
	}
	return lintingRules, nil
}

func parseConfig(path string, config *lint.Config) error {
	file, err := os.ReadFile(path)
	if err != nil {
		return errors.New("cannot read the config file")
	}
	_, err = toml.Decode(string(file), config)
	if err != nil {
		return fmt.Errorf("cannot parse the config file: %w", err)
	}
	for k, r := range config.Rules {
		if err := r.Initialize(); err != nil {
			return fmt.Errorf("error in config of rule [%s] : [%w]", k, err)
		}
		config.Rules[k] = r
	}
	return nil
}

func normalizeConfig(config *lint.Config) {
	if len(config.Rules) == 0 {
		config.Rules = map[string]lint.RuleConfig{}
	}
	if config.EnableAllRules {
		for _, r := range rule.AllRules() {
			ruleName := r.Name()
			if _, alreadyInConf := config.Rules[ruleName]; alreadyInConf {
				continue
			}
			config.Rules[ruleName] = lint.RuleConfig{}
		}
	}
	if config.EnableDefaultRules {
		for _, r := range rule.DefaultRules() {
			ruleName := r.Name()
			if _, alreadyInConf := config.Rules[ruleName]; alreadyInConf {
				continue
			}
			config.Rules[ruleName] = lint.RuleConfig{}
		}
	}
	severity := config.Severity
	if severity != "" {
		for k, v := range config.Rules {
			if v.Severity == "" {
				v.Severity = severity
			}
			config.Rules[k] = v
		}
		for k, v := range config.Directives {
			if v.Severity == "" {
				v.Severity = severity
			}
			config.Directives[k] = v
		}
	}
}

// GetConfig yields the configuration.
func GetConfig(configPath string) (*lint.Config, error) {
	config := &lint.Config{}
	switch {
	case configPath != "":
		config.Confidence = defaultConfidence
		if err := parseConfig(configPath, config); err != nil {
			return nil, err
		}
	default:
		config = defaultConfig()
	}
	normalizeConfig(config)
	return config, nil
}

// GetFormatter yields the formatter for lint failures.
func GetFormatter(formatterName string) (formatter.Formatter, error) {
	formatters := formatter.All()
	if formatterName == "" {
		return formatters["default"], nil
	}
	f, ok := formatters[formatterName]
	if !ok {
		return nil, fmt.Errorf("unknown formatter %v", formatterName)
	}
	return f, nil
}

func defaultConfig() *lint.Config {
	defaultConfig := lint.Config{
		Confidence: defaultConfidence,
		Severity:   lint.SeverityWarning,
		Rules:      map[string]lint.RuleConfig{},
	}
	for _, r := range rule.DefaultRules() {
		defaultConfig.Rules[r.Name()] = lint.RuleConfig{}
	}
	return &defaultConfig
}

// DefaultConfigPath returns the path of the default config file if it exists.
func DefaultConfigPath() string {
	var dirs []string
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		dirs = append(dirs, xdg)
	} else if home, err := os.UserHomeDir(); err == nil {
		_ = home
	}
	if home, err := os.UserHomeDir(); err == nil && home != "" {
		dirs = append(dirs, home)
	}
	for _, d := range dirs {
		p := filepath.Join(d, "revive.toml")
		if fi, err := os.Stat(p); err == nil && !fi.IsDir() {
			return p
		}
	}
	return ""
}
EOF
"}

