package rule

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"

	"github.com/revivelint/revive/internal/lint"
)

// VarDeclarationsRule reduces redundancies around variable declaration.
type VarDeclarationsRule struct{}

func init() { register(&VarDeclarationsRule{}, true) }

// Name returns the rule name.
func (*VarDeclarationsRule) Name() string { return "var-declaration" }

var zeroLiteral = map[string]bool{
	"false":  true,
	`'\x00'`: true,
	`'\000'`: true,
	`""`:     true,
	"``":     true,
	"0":      true,
	"0.":     true,
	"0.0":    true,
	"0i":     true,
}

// Apply applies the rule to given file.
func (*VarDeclarationsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	_ = file.Pkg.TypeCheck()
	var lastGen *ast.GenDecl
	ast.Walk(walker(func(node ast.Node) bool {
		switch v := node.(type) {
		case *ast.GenDecl:
			if v.Tok != token.CONST && v.Tok != token.VAR {
				return false
			}
			lastGen = v
			return true
		case *ast.ValueSpec:
			if lastGen != nil && lastGen.Tok == token.CONST {
				return false
			}
			if len(v.Names) > 1 || v.Type == nil || len(v.Values) == 0 {
				return false
			}
			rhs := v.Values[0]
			if isIdent(v.Names[0], "_") {
				return false
			}
			zero := false
			if lit, ok := rhs.(*ast.BasicLit); ok {
				zero = zeroLiteral[lit.Value]
			} else if isIdent(rhs, "nil") {
				zero = true
			}
			if zero {
				failures = append(failures, lint.Failure{
					Confidence: 0.9,
					Node:       rhs,
					Category:   lint.FailureCategoryZeroValue,
					Failure:    fmt.Sprintf("should drop = %s from declaration of var %s; it is the zero value", file.Render(rhs), v.Names[0]),
				})
				return false
			}
			lhsTyp := file.Pkg.TypeOf(v.Type)
			rhsTyp := file.Pkg.TypeOf(rhs)
			if !validType(lhsTyp) || !validType(rhsTyp) {
				return false
			}
			if !types.Identical(lhsTyp, rhsTyp) {
				return false
			}
			if _, ok := v.Type.(*ast.InterfaceType); ok {
				return false
			}
			if defType, ok := file.IsUntypedConst(rhs); ok && !isIdent(v.Type, defType) {
				return false
			}
			failures = append(failures, lint.Failure{
				Category:   lint.FailureCategoryTypeInference,
				Confidence: 0.8,
				Node:       v.Type,
				Failure:    fmt.Sprintf("should omit type %s from declaration of var %s; it will be inferred from the right-hand side", file.Render(v.Type), v.Names[0]),
			})
			return false
		}
		return true
	}), file.AST)
	return failures
}
EOF
