package rule

import (
	"fmt"
	"go/ast"
	"strings"

	"github.com/revivelint/revive/internal/lint"
)

// DotImportsRule forbids . imports.
type DotImportsRule struct {
	allowedPackages map[string]bool
}

func init() { register(&DotImportsRule{}, true) }

// Name returns the rule name.
func (*DotImportsRule) Name() string { return "dot-imports" }

// Configure validates the rule configuration.
func (r *DotImportsRule) Configure(arguments lint.Arguments) error {
	r.allowedPackages = map[string]bool{}
	if len(arguments) == 0 {
		return nil
	}
	args, ok := arguments[0].(map[string]any)
	if !ok {
		return fmt.Errorf("invalid argument to the dot-imports rule. Expecting a k,v map, got %T", arguments[0])
	}
	for k, v := range args {
		switch {
		case isRuleOption(k, "allowedPackages"):
			pkgs, ok := v.([]any)
			if !ok {
				return fmt.Errorf("invalid argument to the dot-imports rule, []string expected. Got '%v' (%T)", v, v)
			}
			for _, p := range pkgs {
				pkg, ok := p.(string)
				if !ok {
					return fmt.Errorf("invalid argument to the dot-imports rule, string expected. Got '%v' (%T)", p, p)
				}
				r.allowedPackages[fmt.Sprintf(`"%s"`, pkg)] = true
			}
		}
	}
	return nil
}

// Apply applies the rule to given file.
func (r *DotImportsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	for _, is := range file.AST.Imports {
		if is.Name != nil && is.Name.Name == "." && !r.allowedPackages[is.Path.Value] {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Failure:    "should not use dot imports",
				Node:       is,
				Category:   lint.FailureCategoryImports,
			})
		}
	}
	return failures
}

// BlankImportsRule lints blank imports.
type BlankImportsRule struct{}

func init() { register(&BlankImportsRule{}, true) }

// Name returns the rule name.
func (*BlankImportsRule) Name() string { return "blank-imports" }

// Apply applies the rule to given file.
func (r *BlankImportsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if file.Pkg.IsMain() || file.IsTest() {
		return nil
	}
	const (
		message         = "a blank import should be only in a main or test package, or have a comment justifying it"
		embedImportPath = `"embed"`
	)
	var failures []lint.Failure
	for i, imp := range file.AST.Imports {
		pos := file.ToPosition(imp.Pos())
		if !isBlank(imp.Name) {
			continue
		}
		if i > 0 {
			prev := file.AST.Imports[i-1]
			prevPos := file.ToPosition(prev.Pos())
			isSubsequentBlankInAGroup := prevPos.Line+1 == pos.Line && prev.Path.Value != embedImportPath && isBlank(prev.Name)
			if isSubsequentBlankInAGroup {
				continue
			}
		}
		if imp.Path.Value == embedImportPath && fileHasValidEmbedComment(file.AST) {
			continue
		}
		if imp.Doc == nil && imp.Comment == nil {
			failures = append(failures, lint.Failure{Failure: message, Category: lint.FailureCategoryImports, Node: imp, Confidence: 1})
		}
	}
	return failures
}

func fileHasValidEmbedComment(fileAst *ast.File) bool {
	for _, commentGroup := range fileAst.Comments {
		for _, comment := range commentGroup.List {
			if strings.HasPrefix(comment.Text, "//go:embed ") {
				return true
			}
		}
	}
	return false
}
EOF
