package rule

import "strings"

// isRuleOption reports whether the given key matches the option name in any
// of the accepted spellings (exact, lowercase, kebab-case).
func isRuleOption(arg, name string) bool {
	return strings.EqualFold(arg, name) || strings.EqualFold(arg, kebab(name))
}

func kebab(s string) string {
	var sb strings.Builder
	for i, r := range s {
		if r >= 'A' && r <= 'Z' {
			if i > 0 {
				sb.WriteByte('-')
			}
			sb.WriteRune(r + ('a' - 'A'))
			continue
		}
		sb.WriteRune(r)
	}
	return sb.String()
}
EOF
"}

