// ErrorfRule suggests using fmt.Errorf instead of errors.New(fmt.Sprintf()).
type ErrorfRule struct{}

func init() { register(&ErrorfRule{}, true) }

// Name returns the rule name.
func (*ErrorfRule) Name() string { return "errorf" }

// Apply applies the rule to given file.
func (*ErrorfRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	_ = file.Pkg.TypeCheck()
	ast.Walk(walker(func(n ast.Node) bool {
		ce, ok := n.(*ast.CallExpr)
		if !ok || len(ce.Args) != 1 {
			return true
		}
		isErrorsNew := isPkgDot(ce.Fun, "errors", "New")
		var isTestingError bool
		se, ok := ce.Fun.(*ast.SelectorExpr)
		if ok && se.Sel.Name == "Error" {
			if typ := file.Pkg.TypeOf(se.X); typ != nil {
				isTestingError = typ.String() == "*testing.T"
			}
		}
		if !isErrorsNew && !isTestingError {
			return true
