// IncrementDecrementRule lints `i += 1` and `i -= 1` constructs.
type IncrementDecrementRule struct{}

func init() { register(&IncrementDecrementRule{}, true) }

// Name returns the rule name.
func (*IncrementDecrementRule) Name() string { return "increment-decrement" }

// Apply applies the rule to given file.
func (*IncrementDecrementRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Walk(walker(func(n ast.Node) bool {
		as, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		if len(as.Lhs) != 1 {
			return true
		}
		if !isOne(as.Rhs[0]) {
			return true
		}
		var suffix string
		switch as.Tok {
		case token.ADD_ASSIGN:
			suffix = "++"
		case token.SUB_ASSIGN:
			suffix = "--"
		default:
			return true
		}
		failures = append(failures, lint.Failure{
			Confidence: 0.8,
			Node:       as,
			Category:   lint.FailureCategoryUnaryOp,
			Failure:    fmt.Sprintf("should replace %s with %s%s", file.Render(as), file.Render(as.Lhs[0]), suffix),
		})
		return true
	}), file.AST)
	return failures
}

func isOne(expr ast.Expr) bool {
	lit, ok := expr.(*ast.BasicLit)
	return ok && lit.Kind == token.INT && lit.Value == "1"
}

// RangeRule lints range clauses.
type RangeRule struct{}

func init() { register(&RangeRule{}, true) }

// Name returns the rule name.
func (*RangeRule) Name() string { return "range" }

// Apply applies the rule to given file.
func (*RangeRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Walk(walker(func(node ast.Node) bool {
		rs, ok := node.(*ast.RangeStmt)
		if !ok {
			return true
		}
		if rs.Value == nil {
			return true
		}
		if !isIdent(rs.Value, "_") {
			return true
		}
		newRS := *rs
		newRS.Value = nil
		failures = append(failures, lint.Failure{
			Failure:         fmt.Sprintf("should omit 2nd value from range; this loop is equivalent to `for %s %s range ...`", file.Render(rs.Key), rs.Tok),
			Confidence:      1,
			Node:            rs.Value,
			ReplacementLine: firstLineOf(file, &newRS, rs),
		})
		return true
	}), file.AST)
	return failures
}

func firstLineOf(file *lint.File, node, match ast.Node) string {
	line := file.Render(node)
	if i := strings.Index(line, "\n"); i >= 0 {
		line = line[:i]
	}
	return indentOf(file, match) + line
}

func indentOf(file *lint.File, node ast.Node) string {
	line := srcLine(file.Content(), file.ToPosition(node.Pos()))
	for i, r := range line {
		switch r {
		case ' ', '\t':
		default:
			return line[:i]
		}
	}
	return line
}

// ReceiverNamingRule lints a receiver name.
type ReceiverNamingRule struct {
	receiverNameMaxLength int
}

func init() { register(&ReceiverNamingRule{}, true) }

// Name returns the rule name.
func (*ReceiverNamingRule) Name() string { return "receiver-naming" }

// Configure validates the rule configuration.
func (r *ReceiverNamingRule) Configure(arguments lint.Arguments) error {
	r.receiverNameMaxLength = -1
	if len(arguments) < 1 {
		return nil
	}
	args, ok := arguments[0].(map[string]any)
	if !ok {
		return fmt.Errorf("unable to get arguments for rule %s. Expected object of key-value-pairs", r.Name())
	}
	for k, v := range args {
		if isRuleOption(k, "maxLength") {
			value, ok := v.(int64)
			if !ok {
				return fmt.Errorf("invalid value %v for argument %s of rule %s, expected integer value got %T", v, k, r.Name(), v)
			}
			r.receiverNameMaxLength = int(value)
		} else {
			return fmt.Errorf("unknown argument %s for %s rule", k, r.Name())
		}
	}
	return nil
}

// Apply applies the rule to given file.
func (r *ReceiverNamingRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	typeReceiver := map[string]string{}
	add := func(n ast.Node, msg string) {
		failures = append(failures, lint.Failure{
			Node:       n,
			Confidence: 1,
			Category:   lint.FailureCategoryNaming,
			Failure:    msg,
		})
	}
	ast.Walk(walker(func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok || fn.Recv == nil || len(fn.Recv.List) == 0 {
			return true
		}
		names := fn.Recv.List[0].Names
		if len(names) < 1 {
			return true
		}
		name := names[0].Name
		if name == "_" {
			add(n, "receiver name should not be an underscore, omit the name if it is unused")
			return true
		}
		if name == "this" || name == "self" {
			add(n, `receiver name should be a reflection of its identity; don't use generic names such as "this" or "self"`)
			return true
		}
		if r.receiverNameMaxLength > 0 && len([]rune(name)) > r.receiverNameMaxLength {
			add(n, fmt.Sprintf("receiver name %s is longer than %d characters", name, r.receiverNameMaxLength))
			return true
		}
		recv := receiverType(fn)
		if prev, ok := typeReceiver[recv]; ok && prev != name {
			add(n, fmt.Sprintf("receiver name %s should be consistent with previous receiver name %s for %s", name, prev, recv))
			return true
		}
		typeReceiver[recv] = name
		return true
	}), file.AST)
	return failures
}

