func exportedType(typ types.Type) bool {
	switch t := typ.(type) {
	case *types.Named:
		obj := t.Obj()
		switch {
		case obj.Pkg() == nil:
		case obj.Exported():
		default:
			_, ok := t.Underlying().(*types.Interface)
			return ok
		}
		return true
	case *types.Alias:
		return exportedType(types.Unalias(t))
	case *types.Map:
		return exportedType(t.Key()) && exportedType(t.Elem())
	case interface {
		Elem() types.Type
	}:
		return exportedType(t.Elem())
	}
	return true
}

// UnreachableCodeRule lints unreachable code.
type UnreachableCodeRule struct{}

func init() { register(&UnreachableCodeRule{}, true) }

// Name returns the rule name.
func (*UnreachableCodeRule) Name() string { return "unreachable-code" }

var branchingFunctions = map[string]map[string]bool{
	"os": {"Exit": true},
	"log": {
		"Fatal":   true,
		"Fatalf":  true,
		"Fatalln": true,
		"Panic":   true,
		"Panicf":  true,
		"Panicln": true,
	},
}

// Apply applies the rule to given file.
func (*UnreachableCodeRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	newFailure := func(node ast.Node) lint.Failure {
		return lint.Failure{
			Confidence: 1,
			Node:       node,
			Category:   lint.FailureCategoryLogic,
			Failure:    "unreachable code after this statement",
		}
	}
	ast.Walk(walker(func(node ast.Node) bool {
		blk, ok := node.(*ast.BlockStmt)
		if !ok {
			return true
		}
		if len(blk.List) < 2 {
			return true
		}
	loop:
		for i, stmt := range blk.List[:len(blk.List)-1] {
			next := blk.List[i+1]
			if _, ok := next.(*ast.LabeledStmt); ok {
				continue
			}
			switch s := stmt.(type) {
			case *ast.ReturnStmt:
				failures = append(failures, newFailure(s))
				break loop
			case *ast.BranchStmt:
				if s.Tok != token.FALLTHROUGH {
					failures = append(failures, newFailure(s))
					break loop
				}
			case *ast.ExprStmt:
				ce, ok := s.X.(*ast.CallExpr)
				if !ok {
					continue
				}
				fe, ok := ce.Fun.(*ast.SelectorExpr)
				if !ok {
					continue
				}
				id, ok := fe.X.(*ast.Ident)
				if !ok {
					continue
				}
				fn := fe.Sel.Name
				pkg := id.Name
				if !branchingFunctions[pkg][fn] {
					continue
				}
				failures = append(failures, newFailure(stmt))
				break loop
			}
		}
		return true
	}), file.AST)
	return failures
}
