// Package ifelse provides helpers for analyzing the control flow in if-else chains.
package ifelse

import (
	"fmt"
	"go/ast"
	"go/token"

	"github.com/revivelint/revive/internal/lint"
)

// BranchKind is a classifier for if-else branches.
type BranchKind int

// Branch kinds.
const (
	Empty BranchKind = iota
	Return
	Continue
	Break
	Goto
	Panic
	Exit
	Regular
)

// IsEmpty tests if the branch is empty.
func (k BranchKind) IsEmpty() bool { return k == Empty }

// Returns tests if the branch returns from the current function.
func (k BranchKind) Returns() bool { return k == Return }

// Deviates tests if the control does not flow to the first statement following the if-else chain.
func (k BranchKind) Deviates() bool {
	switch k {
	case Empty, Regular:
		return false
	case Return, Continue, Break, Goto, Panic, Exit:
		return true
	}
	panic("invalid kind")
}

// Branch returns a Branch with the given kind.
func (k BranchKind) Branch() Branch { return Branch{BranchKind: k} }

func (k BranchKind) String() string {
	switch k {
	case Empty:
		return ""
	case Regular:
		return "..."
	case Return:
		return "return"
	case Continue:
		return "continue"
	case Break:
		return "break"
	case Goto:
		return "goto"
	case Panic:
		return "panic()"
	case Exit:
		return "os.Exit()"
	}
	panic("invalid kind")
}

// LongString returns a longer form string representation.
func (k BranchKind) LongString() string {
	switch k {
	case Empty:
		return "an empty block"
	case Regular:
		return "a regular statement"
	case Return:
		return "a return statement"
	case Continue:
		return "a continue statement"
	case Break:
		return "a break statement"
	case Goto:
		return "a goto statement"
	case Panic:
		return "a function call that panics"
	case Exit:
		return "a function call that exits the program"
	}
	panic("invalid kind")
}

// Branch contains information about a branch within an if-else chain.
type Branch struct {
	BranchKind
	Call
	HasDecls bool
}

// BlockBranch gets the Branch of an ast.BlockStmt.
func BlockBranch(block *ast.BlockStmt) Branch {
	blockLen := len(block.List)
	if blockLen == 0 {
		return Empty.Branch()
	}
	branch := StmtBranch(block.List[blockLen-1])
	branch.HasDecls = hasDecls(block)
	return branch
}

// StmtBranch gets the Branch of an ast.Stmt.
func StmtBranch(stmt ast.Stmt) Branch {
	switch stmt := stmt.(type) {
	case *ast.ReturnStmt:
		return Return.Branch()
	case *ast.BlockStmt:
		return BlockBranch(stmt)
	case *ast.BranchStmt:
		switch stmt.Tok {
		case token.BREAK:
			return Break.Branch()
		case token.CONTINUE:
			return Continue.Branch()
		case token.GOTO:
			return Goto.Branch()
		}
	case *ast.ExprStmt:
		fn, ok := ExprCall(stmt)
		if !ok {
			break
		}
		kind, ok := DeviatingFuncs[fn]
		if ok {
			return Branch{BranchKind: kind, Call: fn}
		}
	case *ast.EmptyStmt:
		return Empty.Branch()
	case *ast.LabeledStmt:
		return StmtBranch(stmt.Stmt)
	}
	return Regular.Branch()
}

func (b Branch) String() string {
	switch b.BranchKind {
	case Panic, Exit:
		return fmt.Sprintf("... %v()", b.Call)
	default:
		return b.BranchKind.String()
	}
}

// LongString returns a longer form string representation.
func (b Branch) LongString() string {
	switch b.BranchKind {
	case Panic:
		return fmt.Sprintf("call to %v function", b.Call)
	case Exit:
		return fmt.Sprintf("call to %v function", b.Call)
	default:
		return b.BranchKind.LongString()
	}
}

func hasDecls(block *ast.BlockStmt) bool {
	for _, stmt := range block.List {
		switch stmt := stmt.(type) {
		case *ast.DeclStmt:
			return true
		case *ast.AssignStmt:
			if stmt.Tok == token.DEFINE {
				return true
			}
		}
	}
	return false
}

// Call contains the name of a function that deviates control flow.
type Call struct {
	Pkg  string
	Name string
}

// DeviatingFuncs lists known control flow deviating function calls.
var DeviatingFuncs = map[Call]BranchKind{
	{"os", "Exit"}:     Exit,
	{"log", "Fatal"}:   Exit,
	{"log", "Fatalf"}:  Exit,
	{"log", "Fatalln"}: Exit,
	{"", "panic"}:      Panic,
	{"log", "Panic"}:   Panic,
	{"log", "Panicf"}:  Panic,
	{"log", "Panicln"}: Panic,
}

// ExprCall gets the Call of an ExprStmt, if any.
func ExprCall(expr *ast.ExprStmt) (Call, bool) {
	call, ok := expr.X.(*ast.CallExpr)
	if !ok {
		return Call{}, false
	}
	switch v := call.Fun.(type) {
	case *ast.Ident:
		return Call{Name: v.Name}, true
	case *ast.SelectorExpr:
		if ident, ok := v.X.(*ast.Ident); ok {
			return Call{Name: v.Sel.Name, Pkg: ident.Name}, true
		}
	}
	return Call{}, false
}

func (f Call) String() string {
	if f.Pkg != "" {
		return fmt.Sprintf("%s.%s", f.Pkg, f.Name)
	}
	return f.Name
}

// Chain contains information about an if-else chain.
type Chain struct {
	If                   Branch
	HasElse              bool
	Else                 Branch
	HasInitializer       bool
	HasPriorNonDeviating bool
	AtBlockEnd           bool
	BlockEndKind         BranchKind
}

// Args contains arguments common to the early-return, indent-error-flow and superfluous-else rules.
type Args struct {
	PreserveScope bool
	AllowJump     bool
}

// Rule is an interface for linters operating on if-else chains.
type Rule interface {
	CheckIfElse(chain Chain, args Args) (failMsg string)
}

// Target decides what line/column should be indicated by the rule in question.
type Target int

// Targets.
const (
	TargetIf Target = iota
	TargetElse
)

func (t Target) node(ifStmt *ast.IfStmt) ast.Node {
	switch t {
	case TargetIf:
		return ifStmt
	case TargetElse:
		return ifStmt.Else
	}
	panic("bad target")
}

// Argument values.
const (
	PreserveScope = "preserveScope"
	AllowJump     = "allowJump"
)

// Apply evaluates the given Rule on if-else chains found within the given AST.
func Apply(rule Rule, node ast.Node, target Target, args Args) []lint.Failure {
	v := &visitor{rule: rule, target: target, args: args}
	ast.Walk(v, node)
	return v.failures
}

type visitor struct {
	failures []lint.Failure
	target   Target
	rule     Rule
	args     Args
}

func (v *visitor) Visit(node ast.Node) ast.Visitor {
	switch stmt := node.(type) {
	case *ast.FuncDecl:
		v.visitBody(stmt.Body, Return)
	case *ast.FuncLit:
		v.visitBody(stmt.Body, Return)
	case *ast.ForStmt:
		v.visitBody(stmt.Body, Continue)
	case *ast.RangeStmt:
		v.visitBody(stmt.Body, Continue)
	case *ast.CaseClause:
		v.visitBlock(stmt.Body, Empty)
	case *ast.CommClause:
		v.visitBlock(stmt.Body, Empty)
	case *ast.BlockStmt:
		v.visitBlock(stmt.List, Regular)
	default:
		return v
	}
	return nil
}

func (v *visitor) visitBody(body *ast.BlockStmt, endKind BranchKind) {
	if body == nil {
		return
	}
	v.visitBlock(body.List, endKind)
}

func (v *visitor) visitBlock(stmts []ast.Stmt, endKind BranchKind) {
	for i, stmt := range stmts {
		ifStmt, ok := stmt.(*ast.IfStmt)
		if !ok {
			ast.Walk(v, stmt)
			continue
		}
		var chain Chain
		if i == len(stmts)-1 {
			chain.AtBlockEnd = true
			chain.BlockEndKind = endKind
		}
		v.visitIf(ifStmt, chain)
	}
}

func (v *visitor) visitIf(ifStmt *ast.IfStmt, chain Chain) {
	// look for other if-else chains nested inside this if { } block
	v.visitBlock(ifStmt.Body.List, chain.BlockEndKind)

	if as, ok := ifStmt.Init.(*ast.AssignStmt); ok && as.Tok == token.DEFINE {
		chain.HasInitializer = true
	}
	chain.If = BlockBranch(ifStmt.Body)

	switch elseBlock := ifStmt.Else.(type) {
	case *ast.IfStmt:
		if !chain.If.Deviates() {
			chain.HasPriorNonDeviating = true
		}
		v.visitIf(elseBlock, chain)
	case *ast.BlockStmt:
		// look for other if-else chains nested inside this else { } block
		v.visitBlock(elseBlock.List, chain.BlockEndKind)

		chain.Else = BlockBranch(elseBlock)
		chain.HasElse = true
		v.check(ifStmt, chain)
	case nil:
		v.check(ifStmt, chain)
	default:
		panic("invalid node type for else")
	}
}

func (v *visitor) check(ifStmt *ast.IfStmt, chain Chain) {
	failMsg := v.rule.CheckIfElse(chain, v.args)
	if failMsg == "" {
		return
	}
	if chain.HasInitializer {
		failMsg += " (move short variable declaration to its own line if necessary)"
	}
	v.failures = append(v.failures, lint.Failure{
		Confidence: 1,
		Node:       v.target.node(ifStmt),
		Failure:    failMsg,
	})
}
EOF
