	if chain.HasElse {
		if !chain.Else.BranchKind.Deviates() {
			return ""
		}
	} else if !args.AllowJump || !chain.AtBlockEnd || !chain.BlockEndKind.Deviates() {
		return ""
	}
	if chain.HasPriorNonDeviating && !chain.If.IsEmpty() {
		return ""
	}
	if chain.If.Deviates() {
		return ""
	}
	if args.PreserveScope && !chain.AtBlockEnd && (chain.HasInitializer || chain.If.HasDecls) {
		return ""
	}
	if !chain.HasElse {
		return fmt.Sprintf("if c { ... } can be rewritten to if !c { %v } ... to reduce nesting", chain.BlockEndKind)
	}
	if chain.If.IsEmpty() {
		return fmt.Sprintf("if c { } else { %[1]v } can be simplified to if !c { %[1]v }", chain.Else)
