type RedefinesBuiltinIDRule struct{}

func init() { register(&RedefinesBuiltinIDRule{}, true) }

// Name returns the rule name.
func (*RedefinesBuiltinIDRule) Name() string { return "redefines-builtin-id" }

// Apply applies the rule to given file.
func (*RedefinesBuiltinIDRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	builtFuncs := map[string]bool{}
	for k, v := range builtFunctions {
		builtFuncs[k] = v
	}
	for k, v := range builtFunctionsAfterGo121 {
		builtFuncs[k] = v
	}
	isBuiltIn := func(id string) (bool, string) {
		if builtFuncs[id] {
			return true, "function"
		}
		if builtInConstAndVars[id] {
