		}
		if builtInTypes[id] {
			return true, "type"
		}
		return false, ""
	}
	addFailure := func(node ast.Node, msg string) {
		failures = append(failures, lint.Failure{
			Confidence: 1,
			Node:       node,
			Category:   lint.FailureCategoryLogic,
			Failure:    msg,
		})
	}
