		switch n := node.(type) {
		case *ast.GenDecl:
			switch n.Tok {
			case token.TYPE:
				if len(n.Specs) < 1 {
					return false
				}
				typeSpec, ok := n.Specs[0].(*ast.TypeSpec)
				if !ok {
					return false
				}
				id := typeSpec.Name.Name
				if ok, bt := isBuiltIn(id); ok {
					addFailure(n, fmt.Sprintf("redefinition of the built-in %s %s", bt, id))
				}
			case token.VAR, token.CONST:
				for _, vs := range n.Specs {
					valSpec, ok := vs.(*ast.ValueSpec)
					if !ok {
						continue
					}
					for _, name := range valSpec.Names {
						if ok, bt := isBuiltIn(name.Name); ok {
							addFailure(n, fmt.Sprintf("redefinition of the built-in %s %s", bt, name))
						}
					}
				}
			default:
				return false
			}
		case *ast.FuncDecl:
			if n.Recv != nil {
				return true
			}
			id := n.Name.Name
			if ok, bt := isBuiltIn(id); ok {
				addFailure(n, fmt.Sprintf("redefinition of the built-in %s %s", bt, id))
			}
		case *ast.FuncType:
			var fields []*ast.Field
			if n.TypeParams != nil {
				fields = append(fields, n.TypeParams.List...)
			}
			if n.Params != nil {
				fields = append(fields, n.Params.List...)
			}
			if n.Results != nil {
				fields = append(fields, n.Results.List...)
			}
			for _, field := range fields {
				for _, name := range field.Names {
					obj := name.Obj
					isTypeOrName := obj != nil && (obj.Kind == ast.Var || obj.Kind == ast.Typ)
					if !isTypeOrName {
						continue
					}
					id := obj.Name
					if ok, bt := isBuiltIn(id); ok {
						addFailure(name, fmt.Sprintf("redefinition of the built-in %s %s", bt, id))
					}
				}
			}
		case *ast.AssignStmt:
			for _, e := range n.Lhs {
				id, ok := e.(*ast.Ident)
				if !ok {
					continue
				}
				if ok, bt := isBuiltIn(id.Name); ok {
					var msg string
					switch bt {
					case "constant or variable":
						if n.Tok == token.DEFINE {
							msg = fmt.Sprintf("assignment creates a shadow of built-in identifier %s", id.Name)
						} else {
							msg = fmt.Sprintf("assignment modifies built-in identifier %s", id.Name)
						}
					default:
						msg = fmt.Sprintf("redefinition of the built-in %s %s", bt, id)
					}
					addFailure(n, msg)
				}
			}
		}
		return true
	}), file.AST)
	return failures
}
