var allowBlankIdentifierRegex = regexp.MustCompile("^_$")

// UnusedParamRule lints unused params in functions.
type UnusedParamRule struct {
	allowRegex *regexp.Regexp
	failureMsg string
}

func init() { register(&UnusedParamRule{}, true) }

// Name returns the rule name.
func (*UnusedParamRule) Name() string { return "unused-parameter" }

// Configure validates the rule configuration.
func (r *UnusedParamRule) Configure(args lint.Arguments) error {
	r.failureMsg = "parameter '%s' seems to be unused, consider removing or renaming it as _"
	r.allowRegex = allowBlankIdentifierRegex
	if len(args) == 0 {
		return nil
	}
	options, ok := args[0].(map[string]any)
	if !ok {
		return nil
	}
	var allowRegexParam any
	found := false
	for k, v := range options {
		if isRuleOption(k, "allowRegex") {
			allowRegexParam = v
			found = true
		}
	}
	if !found {
		return nil
	}
	allowRegexStr, ok := allowRegexParam.(string)
	if !ok {
		return fmt.Errorf("error configuring %s rule: allowRegex is not string but [%T]", r.Name(), allowRegexParam)
	}
	var err error
	r.allowRegex, err = regexp.Compile(allowRegexStr)
	if err != nil {
		return fmt.Errorf("error configuring %s rule: allowRegex is not valid regex [%s]: %w", r.Name(), allowRegexStr, err)
	}
	r.failureMsg = "parameter '%s' seems to be unused, consider removing or renaming it to match " + r.allowRegex.String()
	return nil
}

// Apply applies the rule to given file.
func (r *UnusedParamRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Walk(walker(func(node ast.Node) bool {
		var funcType *ast.FuncType
		var funcBody *ast.BlockStmt
		switch n := node.(type) {
		case *ast.FuncLit:
			funcType = n.Type
			funcBody = n.Body
		case *ast.FuncDecl:
			if n.Body == nil {
				return false
			}
			funcType = n.Type
			funcBody = n.Body
		default:
			return true
		}
		params := retrieveNamedParams(funcType.Params)
		if len(params) < 1 {
			return true
		}
		ast.Inspect(funcBody, func(n ast.Node) bool {
			ident, ok := n.(*ast.Ident)
			if !ok {
				return true
			}
			if _, isAParam := params[ident.Obj]; isAParam {
				params[ident.Obj] = false
			}
			return true
		})
		for _, p := range funcType.Params.List {
			for _, n := range p.Names {
				if r.allowRegex.FindStringIndex(n.Name) != nil {
					continue
				}
				if params[n.Obj] {
					failures = append(failures, lint.Failure{
						Confidence: 1,
						Node:       n,
						Category:   lint.FailureCategoryBadPractice,
						Failure:    fmt.Sprintf(r.failureMsg, n.Name),
					})
				}
			}
		}
		return true
	}), file.AST)
	return failures
}

func retrieveNamedParams(params *ast.FieldList) map[*ast.Object]bool {
	result := map[*ast.Object]bool{}
	if params.List == nil {
		return result
	}
	for _, p := range params.List {
		for _, n := range p.Names {
			if n.Name == "_" {
				continue
			}
			result[n.Obj] = true
		}
	}
	return result
}
