// lintName returns a different name if it should be different.
func lintName(name string, allowlist, blocklist []string, skipInitialisms bool) (should string) {
	if name == "_" {
		return name
	}
	allLower := true
	for _, r := range name {
		if !unicode.IsLower(r) {
			allLower = false
			break
		}
	}
	if allLower {
		return name
	}
	ignoreInitWarnings := map[string]bool{}
	for _, i := range allowlist {
		ignoreInitWarnings[i] = true
	}
	extraInits := map[string]bool{}
	for _, i := range blocklist {
		extraInits[i] = true
	}

	runes := []rune(name)
	w, i := 0, 0
	for i+1 <= len(runes) {
		eow := false
		switch {
		case i+1 == len(runes):
			eow = true
		case runes[i+1] == '_':
			eow = true
			n := 1
			for i+n+1 < len(runes) && runes[i+n+1] == '_' {
				n++
			}
			if i+n+1 < len(runes) && unicode.IsDigit(runes[i]) && unicode.IsDigit(runes[i+n+1]) {
				n--
			}
			copy(runes[i+1:], runes[i+n+1:])
			runes = runes[:len(runes)-n]
		case unicode.IsLower(runes[i]) && !unicode.IsLower(runes[i+1]):
			eow = true
		}
		i++
		if !eow {
			continue
		}
		word := string(runes[w:i])
		if u := strings.ToUpper(word); !skipInitialisms && (commonInitialisms[u] || extraInits[u]) && !ignoreInitWarnings[u] {
			if w == 0 && unicode.IsLower(runes[w]) {
				u = strings.ToLower(u)
			}
			if u == "IDS" {
				u = "IDs"
			}
			copy(runes[w:], []rune(u))
		} else if w > 0 && strings.ToLower(word) == word {
			runes[w] = unicode.ToUpper(runes[w])
		}
		w = i
	}
	return string(runes)
}
