func (r *VarNamingRule) applyPackageCheckRules(file *lint.File, onFailure func(lint.Failure)) {
	fileDir := filepath.Dir(file.Name)
	r.mu.Lock()
	if r.pkgNameAlreadyChecked == nil {
		r.pkgNameAlreadyChecked = map[string]bool{}
	}
	if r.pkgNameAlreadyChecked[fileDir] {
		r.mu.Unlock()
		return
	}
	r.pkgNameAlreadyChecked[fileDir] = true
	r.mu.Unlock()

	pkgNameNode := file.AST.Name
	pkgName := pkgNameNode.Name
	pkgNameLower := strings.ToLower(pkgName)
	if _, ok := r.extraBadPackageNames[pkgNameLower]; ok {
		onFailure(lint.Failure{
			Failure:    "avoid bad package names",
			Confidence: 1,
			Node:       pkgNameNode,
			Category:   lint.FailureCategoryNaming,
		})
		return
	}
	if _, ok := defaultBadPackageNames[pkgNameLower]; ok {
		onFailure(lint.Failure{
			Failure:    "avoid meaningless package names",
			Confidence: 1,
			Node:       pkgNameNode,
			Category:   lint.FailureCategoryNaming,
		})
		return
	}
	if !r.skipPackageNameCollisionWithGoStd {
		if _, ok := r.stdPackageNames[pkgNameLower]; ok {
			onFailure(lint.Failure{
				Failure:    "avoid package names that conflict with Go standard library package names",
				Confidence: 1,
				Node:       pkgNameNode,
				Category:   lint.FailureCategoryNaming,
			})
		}
	}
	if strings.Contains(pkgName, "_") && !strings.HasSuffix(pkgName, "_test") {
		onFailure(lint.Failure{
			Failure:    "don't use an underscore in package name",
			Confidence: 1,
			Node:       pkgNameNode,
			Category:   lint.FailureCategoryNaming,
		})
	}
	if anyCapsRE.MatchString(pkgName) {
		onFailure(lint.Failure{
			Failure:    fmt.Sprintf("don't use MixedCaps in package names; %s should be %s", pkgName, pkgNameLower),
			Confidence: 1,
			Node:       pkgNameNode,
			Category:   lint.FailureCategoryNaming,
		})
	}
}

// Apply applies the rule to given file.
func (r *VarNamingRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	w := &lintNames{
		file:                     file,
		fileAst:                  file.AST,
		allowList:                r.allowList,
		blockList:                r.blockList,
		onFailure:                func(f lint.Failure) { failures = append(failures, f) },
		upperCaseConst:           r.allowUpperCaseConst,
		skipInitialismNameChecks: r.skipInitialismNameChecks,
	}
	if !r.skipPackageNameChecks {
		r.applyPackageCheckRules(file, w.onFailure)
	}
	ast.Walk(w, file.AST)
	return failures
}

type lintNames struct {
	file                     *lint.File
	fileAst                  *ast.File
	onFailure                func(lint.Failure)
	allowList                []string
	blockList                []string
	upperCaseConst           bool
	skipInitialismNameChecks bool
}

func (w *lintNames) check(id *ast.Ident, thing string) {
	if id.Name == "_" {
		return
	}
	if knownNameExceptions[id.Name] {
		return
	}
	if thing == token.CONST.String() && w.upperCaseConst && upperCaseConstRE.MatchString(id.Name) {
		return
	}
	if len(id.Name) >= 5 && allCapsRE.MatchString(id.Name) && strings.Contains(id.Name, "_") {
		w.onFailure(lint.Failure{
			Failure:    "don't use ALL_CAPS in Go names; use CamelCase",
			Confidence: 0.8,
			Node:       id,
			Category:   lint.FailureCategoryNaming,
		})
		return
	}
	should := lintName(id.Name, w.allowList, w.blockList, w.skipInitialismNameChecks)
	if id.Name == should {
		return
	}
	if len(id.Name) > 2 && strings.Contains(id.Name[1:], "_") {
		w.onFailure(lint.Failure{
			Failure:    fmt.Sprintf("don't use underscores in Go names; %s %s should be %s", thing, id.Name, should),
			Confidence: 0.9,
			Node:       id,
			Category:   lint.FailureCategoryNaming,
		})
		return
	}
	w.onFailure(lint.Failure{
		Failure:    fmt.Sprintf("%s %s should be %s", thing, id.Name, should),
		Confidence: 0.8,
		Node:       id,
		Category:   lint.FailureCategoryNaming,
	})
}

func (w *lintNames) Visit(n ast.Node) ast.Visitor {
	switch v := n.(type) {
	case *ast.AssignStmt:
		if v.Tok == token.ASSIGN {
			return w
		}
		for _, exp := range v.Lhs {
			if id, ok := exp.(*ast.Ident); ok {
				w.check(id, "var")
			}
		}
	case *ast.FuncDecl:
		funcName := v.Name.Name
		if w.file.IsTest() &&
			(strings.HasPrefix(funcName, "Example") ||
				strings.HasPrefix(funcName, "Test") ||
				strings.HasPrefix(funcName, "Benchmark") ||
				strings.HasPrefix(funcName, "Fuzz")) {
			return w
		}
		thing := "func"
		if v.Recv != nil {
			thing = "method"
		}
		if ast.IsExported(v.Name.Name) || !isCgoExported(v) {
			w.check(v.Name, thing)
		}
		checkNameList(v.Type.Params, thing+" parameter", w)
		checkNameList(v.Type.Results, thing+" result", w)
	case *ast.GenDecl:
		if v.Tok == token.IMPORT {
			return w
		}
		thing := v.Tok.String()
		for _, spec := range v.Specs {
			switch s := spec.(type) {
			case *ast.TypeSpec:
				w.check(s.Name, thing)
			case *ast.ValueSpec:
				for _, id := range s.Names {
					w.check(id, thing)
				}
			}
		}
	case *ast.InterfaceType:
		for _, x := range v.Methods.List {
			ft, ok := x.Type.(*ast.FuncType)
			if !ok {
				continue
			}
			checkNameList(ft.Params, "interface method parameter", w)
			checkNameList(ft.Results, "interface method result", w)
		}
	case *ast.RangeStmt:
		if v.Tok == token.ASSIGN {
			return w
		}
		if id, ok := v.Key.(*ast.Ident); ok {
			w.check(id, "range var")
		}
		if id, ok := v.Value.(*ast.Ident); ok {
			w.check(id, "range var")
		}
	case *ast.StructType:
		for _, f := range v.Fields.List {
			for _, id := range f.Names {
				w.check(id, "struct field")
			}
		}
	}
	return w
}

func checkNameList(fl *ast.FieldList, thing string, w *lintNames) {
	if fl == nil {
		return
	}
	for _, f := range fl.List {
		for _, id := range f.Names {
			w.check(id, thing)
		}
	}
}

func isCgoExported(f *ast.FuncDecl) bool {
	if f.Recv != nil || f.Doc == nil {
		return false
	}
	cgoExport := regexp.MustCompile(fmt.Sprintf("(?m)^//export %s$", regexp.QuoteMeta(f.Name.Name)))
	for _, c := range f.Doc.List {
		if cgoExport.MatchString(c.Text) {
			return true
		}
	}
	return false
}

