	"github.com/revivelint/revive/internal/lint"
)

// pick yields the nodes of the subtree that satisfy fselect.
func pick(n ast.Node, fselect func(n ast.Node) bool) []ast.Node {
	var result []ast.Node
	if n == nil {
		return result
	}
	ast.Inspect(n, func(node ast.Node) bool {
		if node == nil {
			return false
		}
		if fselect(node) {
			result = append(result, node)
		}
		return true
	})
	return result
}

// BareReturnRule lints given else constructs.
type BareReturnRule struct{}

func init() { register(&BareReturnRule{}, false) }

// Name returns the rule name.
func (*BareReturnRule) Name() string { return "bare-return" }

// Apply applies the rule to given file.
func (*BareReturnRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	var visit func(node ast.Node) bool
	checkFunc := func(results *ast.FieldList, body *ast.BlockStmt) {
		hasNamedResults := results != nil && len(results.List) > 0 && results.List[0].Names != nil
		if !hasNamedResults || body == nil {
			return
		}
		ast.Walk(walker(func(node ast.Node) bool {
			if _, ok := node.(*ast.FuncLit); ok {
				return false
			}
			rs, ok := node.(*ast.ReturnStmt)
			if !ok {
				return true
			}
			if len(rs.Results) > 0 {
				return true
			}
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Node:       rs,
				Failure:    "avoid using bare returns, please add return expressions",
			})
			return true
		}), body)
	}
	visit = func(node ast.Node) bool {
		switch n := node.(type) {
		case *ast.FuncDecl:
			checkFunc(n.Type.Results, n.Body)
		case *ast.FuncLit:
			checkFunc(n.Type.Results, n.Body)
		}
		return true
	}
	ast.Walk(walker(visit), file.AST)
	return failures
}

// BoolLiteralRule warns when logic expressions contains Boolean literals.
type BoolLiteralRule struct{}

func init() { register(&BoolLiteralRule{}, false) }

// Name returns the rule name.
func (*BoolLiteralRule) Name() string { return "bool-literal-in-expr" }

// Apply applies the rule to given file.
func (*BoolLiteralRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	isBoolOp := func(t token.Token) bool {
		switch t {
		case token.LAND, token.LOR, token.EQL, token.NEQ:
			return true
		}
		return false
	}
	isExprABooleanLit := func(n ast.Node) (string, bool) {
		oper, ok := n.(*ast.Ident)
		if !ok {
			return "", false
		}
		return oper.Name, oper.Name == "true" || oper.Name == "false"
	}
	ast.Walk(walker(func(node ast.Node) bool {
		n, ok := node.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		if !isBoolOp(n.Op) {
			return true
		}
		lexeme, ok := isExprABooleanLit(n.X)
		if !ok {
			lexeme, ok = isExprABooleanLit(n.Y)
			if !ok {
				return true
			}
		}
		isConstant := (n.Op == token.LAND && lexeme == "false") || (n.Op == token.LOR && lexeme == "true")
		if isConstant {
			failures = append(failures, lint.Failure{Node: n, Confidence: 1, Category: lint.FailureCategoryLogic, Failure: "Boolean expression seems to always evaluate to " + lexeme})
		} else {
			failures = append(failures, lint.Failure{Node: n, Confidence: 1, Category: lint.FailureCategoryStyle, Failure: "omit Boolean literal in expression"})
		}
		return true
	}), file.AST)
	return failures
}

