// ConfusingResultsRule lints given function declarations.
type ConfusingResultsRule struct{}

func init() { register(&ConfusingResultsRule{}, false) }

// Name returns the rule name.
func (*ConfusingResultsRule) Name() string { return "confusing-results" }

// Apply applies the rule to given file.
func (*ConfusingResultsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	for _, decl := range file.AST.Decls {
		funcDecl, ok := decl.(*ast.FuncDecl)
		isFunctionWithMoreThanOneResult := ok && funcDecl.Type.Results != nil && len(funcDecl.Type.Results.List) > 1
		if !isFunctionWithMoreThanOneResult {
			continue
		}
		resultsAreNamed := len(funcDecl.Type.Results.List[0].Names) > 0
		if resultsAreNamed {
			continue
		}
		lastType := ""
		for _, result := range funcDecl.Type.Results.List {
			resultTypeName := gofmt(result.Type)
			if resultTypeName == lastType {
				failures = append(failures, lint.Failure{
					Node:       result,
					Confidence: 1,
					Category:   lint.FailureCategoryNaming,
					Failure:    "unnamed results of the same type may be confusing, consider using named results",
				})
				break
			}
			lastType = resultTypeName
		}
	}
	return failures
}

// ConstantLogicalExprRule warns on constant logical expressions.
type ConstantLogicalExprRule struct{}

func init() { register(&ConstantLogicalExprRule{}, false) }

// Name returns the rule name.
func (*ConstantLogicalExprRule) Name() string { return "constant-logical-expr" }

// Apply applies the rule to given file.
func (*ConstantLogicalExprRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	newFailure := func(node ast.Node, msg string) {
		failures = append(failures, lint.Failure{Confidence: 1, Node: node, Category: lint.FailureCategoryLogic, Failure: msg})
	}
	ast.Walk(walker(func(node ast.Node) bool {
		n, ok := node.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch n.Op {
		case token.LAND, token.LOR, token.EQL, token.LSS, token.GTR, token.NEQ, token.LEQ, token.GEQ:
		default:
			return true
		}
		if gofmt(n.X) != gofmt(n.Y) {
			return true
		}
		switch n.Op {
		case token.EQL, token.LEQ, token.GEQ:
			newFailure(n, "expression always evaluates to true")
			return true
		case token.LSS, token.GTR, token.NEQ:
			newFailure(n, "expression always evaluates to false")
			return true
		}
		newFailure(n, "left and right hand-side sub-expressions are the same")
		return true
	}), file.AST)
	return failures
}

// DeepExitRule lints program exit at functions other than main or init.
type DeepExitRule struct{}

func init() { register(&DeepExitRule{}, false) }

// Name returns the rule name.
func (*DeepExitRule) Name() string { return "deep-exit" }

var exitFunctions = map[string]map[string]bool{
	"os":      {"Exit": true},
	"syscall": {"Exit": true},
	"log": {
		"Fatal":   true,
		"Fatalf":  true,
		"Fatalln": true,
		"Panic":   true,
		"Panicf":  true,
		"Panicln": true,
	},
}

// Apply applies the rule to given file.
func (*DeepExitRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	isTestFile := file.IsTest()
	ast.Walk(walker(func(node ast.Node) bool {
		if fd, ok := node.(*ast.FuncDecl); ok {
			fn := fd.Name.Name
			if fn == "init" || fn == "main" || (isTestFile && fn == "TestMain") {
				return false
			}
			return true
		}
		se, ok := node.(*ast.ExprStmt)
		if !ok {
			return true
		}
		ce, ok := se.X.(*ast.CallExpr)
		if !ok {
			return true
		}
		fc, ok := ce.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		id, ok := fc.X.(*ast.Ident)
		if !ok {
			return true
		}
		fn := fc.Sel.Name
		pkg := id.Name
		if exitFunctions[pkg] != nil && exitFunctions[pkg][fn] {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Node:       ce,
				Category:   lint.FailureCategoryBadPractice,
				Failure:    fmt.Sprintf("calls to %s.%s only in main() or init() functions", pkg, fn),
			})
		}
		return true
	}), file.AST)
	return failures
}

// DuplicatedImportsRule looks for packages that are imported two or more times.
type DuplicatedImportsRule struct{}

func init() { register(&DuplicatedImportsRule{}, false) }

// Name returns the rule name.
func (*DuplicatedImportsRule) Name() string { return "duplicated-imports" }

// Apply applies the rule to given file.
func (*DuplicatedImportsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	impPaths := map[string]struct{}{}
	for _, imp := range file.AST.Imports {
		path := imp.Path.Value
		if _, ok := impPaths[path]; ok {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Failure:    fmt.Sprintf("Package %s already imported", path),
				Node:       imp,
				Category:   lint.FailureCategoryImports,
			})
			continue
		}
		impPaths[path] = struct{}{}
	}
	return failures
}

// GetReturnRule lints given else constructs.
type GetReturnRule struct{}

func init() { register(&GetReturnRule{}, false) }

// Name returns the rule name.
func (*GetReturnRule) Name() string { return "get-return" }

func isGetter(name string) bool {
	const getterPrefix = "GET"
	if !strings.HasPrefix(strings.ToUpper(name), getterPrefix) {
		return false
	}
	if len(name) == len(getterPrefix) {
		return false
	}
	c := name[len(getterPrefix)]
	return !(c >= 'a' && c <= 'z')
}

// Apply applies the rule to given file.
func (*GetReturnRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Walk(walker(func(node ast.Node) bool {
		fd, ok := node.(*ast.FuncDecl)
		if !ok {
			return true
		}
		if !isGetter(fd.Name.Name) {
			return true
		}
		if !(fd.Type.Results != nil && len(fd.Type.Results.List) > 0) {
			failures = append(failures, lint.Failure{
				Confidence: 0.8,
				Node:       fd,
				Category:   lint.FailureCategoryLogic,
				Failure:    fmt.Sprintf("function '%s' seems to be a getter but it does not return any result", fd.Name.Name),
			})
		}
		return true
	}), file.AST)
	return failures
}

// ImportShadowingRule spots identifiers that shadow an import.
type ImportShadowingRule struct{}

func init() { register(&ImportShadowingRule{}, false) }

// Name returns the rule name.
func (*ImportShadowingRule) Name() string { return "import-shadowing" }

func importName(imp *ast.ImportSpec) string {
	const pathSep = "/"
	const strDelim = `"`
	if imp.Name != nil {
		return imp.Name.Name
	}
	path := imp.Path.Value
	i := strings.LastIndex(path, pathSep)
	if i == -1 {
		return strings.Trim(path, strDelim)
	}
	return strings.Trim(path[i+1:], strDelim)
}

// Apply applies the rule to given file.
func (*ImportShadowingRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	importNames := map[string]struct{}{}
	for _, imp := range file.AST.Imports {
		importNames[importName(imp)] = struct{}{}
	}
	packageNameIdent := file.AST.Name
	alreadySeen := map[*ast.Object]struct{}{}
	skipIdents := map[*ast.Ident]struct{}{}
	ast.Walk(walker(func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.AssignStmt:
			return n.Tok == token.DEFINE
		case *ast.CallExpr, *ast.ImportSpec, *ast.KeyValueExpr, *ast.ReturnStmt, *ast.SelectorExpr, *ast.StructType:
			return false
		case *ast.FuncDecl:
			if n.Recv != nil {
				skipIdents[n.Name] = struct{}{}
			}
		case *ast.Ident:
			if n == packageNameIdent {
				return false
			}
			id := n.Name
			if id == "_" {
				return true
			}
			_, isImportName := importNames[id]
			_, seen := alreadySeen[n.Obj]
			_, skipIdent := skipIdents[n]
			if isImportName && !seen && !skipIdent {
				failures = append(failures, lint.Failure{
					Confidence: 1,
					Node:       n,
					Category:   lint.FailureCategoryNaming,
					Failure:    fmt.Sprintf("The name '%s' shadows an import name", id),
				})
				alreadySeen[n.Obj] = struct{}{}
			}
		}
		return true
	}), file.AST)
	return failures
}

// AtomicRule lints usages of the sync/atomic package's API.
type AtomicRule struct{}

func init() { register(&AtomicRule{}, false) }

// Name returns the rule name.
func (*AtomicRule) Name() string { return "atomic" }

// Apply applies the rule to given file.
func (*AtomicRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	_ = file.Pkg.TypeCheck()
	info := file.Pkg.TypesInfo()
	ast.Walk(walker(func(node ast.Node) bool {
		n, ok := node.(*ast.AssignStmt)
		if !ok {
			return true
		}
		if len(n.Lhs) != len(n.Rhs) {
			return false
		}
		if len(n.Lhs) == 1 && n.Tok == token.DEFINE {
			return false
		}
		for i, right := range n.Rhs {
			call, ok := right.(*ast.CallExpr)
			if !ok {
				continue
			}
			sel, ok := call.Fun.(*ast.SelectorExpr)
			if !ok {
				continue
			}
			pkgIdent, _ := sel.X.(*ast.Ident)
			if info != nil {
				pkgName, ok := info.Uses[pkgIdent].(*types.PkgName)
				if !ok || pkgName.Imported().Path() != "sync/atomic" {
					continue
				}
			}
			switch sel.Sel.Name {
			case "AddInt32", "AddInt64", "AddUint32", "AddUint64", "AddUintptr":
				left := n.Lhs[i]
				if len(call.Args) != 2 {
					continue
				}
				arg := call.Args[0]
				broken := false
				if uarg, ok := arg.(*ast.UnaryExpr); ok && uarg.Op == token.AND {
					broken = gofmt(left) == gofmt(uarg.X)
				} else if star, ok := left.(*ast.StarExpr); ok {
					broken = gofmt(star.X) == gofmt(arg)
				}
				if broken {
					failures = append(failures, lint.Failure{
						Confidence: 1,
						Failure:    "direct assignment to atomic value",
						Node:       n,
					})
				}
			}
		}
		return true
	}), file.AST)
	return failures
}

// WaitGroupByValueRule lints sync.WaitGroup passed by copy in functions.
type WaitGroupByValueRule struct{}

func init() { register(&WaitGroupByValueRule{}, false) }

// Name returns the rule name.
func (*WaitGroupByValueRule) Name() string { return "waitgroup-by-value" }

// Apply applies the rule to given file.
func (*WaitGroupByValueRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	isWaitGroup := func(ft ast.Expr) bool {
		se, ok := ft.(*ast.SelectorExpr)
		if !ok {
			return false
		}
		x, _ := se.X.(*ast.Ident)
		return x != nil && x.Name == "sync" && se.Sel.Name == "WaitGroup"
	}
	ast.Walk(walker(func(node ast.Node) bool {
		var funcType *ast.FuncType
		switch n := node.(type) {
		case *ast.FuncDecl:
			funcType = n.Type
		case *ast.FuncLit:
			funcType = n.Type
		default:
			return true
		}
		for _, field := range funcType.Params.List {
			if !isWaitGroup(field.Type) {
				continue
			}
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Node:       field,
				Failure:    "sync.WaitGroup passed by value, the function will get a copy of the original one",
			})
		}
		return false
	}), file.AST)
	return failures
}

// StringOfIntRule warns when logic expressions contains Boolean literals.
type StringOfIntRule struct{}

func init() { register(&StringOfIntRule{}, false) }

// Name returns the rule name.
func (*StringOfIntRule) Name() string { return "string-of-int" }

// Apply applies the rule to given file.
func (*StringOfIntRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	_ = file.Pkg.TypeCheck()
	isCallStringCast := func(e ast.Expr) bool {
		t := file.Pkg.TypeOf(e)
		if t == nil {
			return false
		}
		tb, _ := t.Underlying().(*types.Basic)
		return tb != nil && tb.Kind() == types.String
	}
	isIntExpression := func(es []ast.Expr) bool {
		if len(es) != 1 {
			return false
		}
		t := file.Pkg.TypeOf(es[0])
		if t == nil {
			return false
		}
		ut, _ := t.Underlying().(*types.Basic)
		if ut == nil || ut.Info()&types.IsInteger == 0 {
			return false
		}
		switch ut.Kind() {
		case types.Byte, types.Rune, types.UntypedRune:
			return false
		}
		return true
	}
	ast.Walk(walker(func(node ast.Node) bool {
		ce, ok := node.(*ast.CallExpr)
		if !ok {
			return true
		}
		if !isCallStringCast(ce.Fun) {
			return true
		}
		if !isIntExpression(ce.Args) {
			return true
		}
		failures = append(failures, lint.Failure{
			Confidence: 1,
			Node:       ce,
			Failure:    "dubious conversion of an integer into a string, use strconv.Itoa",
		})
		return true
	}), file.AST)
	return failures
}
