package rule

import (
	"fmt"
	"go/ast"
	"go/token"
	"regexp"
	"strings"

	"github.com/revivelint/revive/internal/lint"
)

// ModifiesParamRule warns on assignments to function parameters.
type ModifiesParamRule struct{}

func init() { register(&ModifiesParamRule{}, false) }

// Name returns the rule name.
func (*ModifiesParamRule) Name() string { return "modifies-parameter" }

type lintModifiesParamRule struct {
	params    map[string]bool
	onFailure func(lint.Failure)
}

func retrieveParamDefinitions(fl *ast.FieldList) map[string]bool {
	result := map[string]bool{}
	if fl.List == nil {
		return result
	}
	for _, p := range fl.List {
		for _, n := range p.Names {
			if n.Name == "_" {
				continue
			}
			result[n.Name] = true
		}
	}
	return result
}

func (w lintModifiesParamRule) checkParam(id *ast.Ident) {
	if w.params[id.Name] {
		w.onFailure(lint.Failure{
			Confidence: 0.5,
			Node:       id,
			Category:   lint.FailureCategoryBadPractice,
			Failure:    fmt.Sprintf("parameter '%s' seems to be modified", id),
		})
	}
}

func (w lintModifiesParamRule) Visit(node ast.Node) ast.Visitor {
	switch v := node.(type) {
	case *ast.FuncDecl:
		w.params = retrieveParamDefinitions(v.Type.Params)
	case *ast.IncDecStmt:
		if id, ok := v.X.(*ast.Ident); ok {
			w.checkParam(id)
		}
	case *ast.AssignStmt:
		for _, e := range v.Lhs {
			if id, ok := e.(*ast.Ident); ok {
				w.checkParam(id)
			}
		}
	}
	return w
}

// Apply applies the rule to given file.
func (*ModifiesParamRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	w := lintModifiesParamRule{onFailure: func(f lint.Failure) { failures = append(failures, f) }}
	ast.Walk(w, file.AST)
	return failures
}

// ModifiesValRecRule lints assignments to value method-receivers.
type ModifiesValRecRule struct{}

func init() { register(&ModifiesValRecRule{}, false) }

// Name returns the rule name.
func (*ModifiesValRecRule) Name() string { return "modifies-value-receiver" }

func getNameFromExpr(ie ast.Expr) string {
	switch e := ie.(type) {
	case *ast.Ident:
		return e.Name
	case *ast.SelectorExpr:
		return getNameFromExpr(e.X)
	}
	return ""
}

// Apply applies the rule to given file.
func (*ModifiesValRecRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	for _, decl := range file.AST.Decls {
		funcDecl, ok := decl.(*ast.FuncDecl)
		isAMethod := ok && funcDecl.Recv != nil
		if !isAMethod {
			continue
		}
		recv := funcDecl.Recv.List[0]
		if len(recv.Names) < 1 {
			continue
		}
		if _, ok := recv.Type.(*ast.StarExpr); ok {
			continue
		}
		receiverName := recv.Names[0].Name
		if receiverName == "_" {
			continue
		}
		if funcDecl.Body == nil {
			continue
		}
		if receiverIsReturned(funcDecl.Body, receiverName) {
			continue
		}
		fselect := func(n ast.Node) bool {
			switch n := n.(type) {
			case *ast.IncDecStmt:
				se, ok := n.X.(*ast.SelectorExpr)
				if !ok {
					return false
				}
				return getNameFromExpr(se.X) == receiverName
			case *ast.AssignStmt:
				for _, exp := range n.Lhs {
					switch e := exp.(type) {
					case *ast.IndexExpr:
						continue
					case *ast.StarExpr:
						continue
					case *ast.SelectorExpr:
						name := getNameFromExpr(e.X)
						if name == "" || name != receiverName {
							continue
						}
					case *ast.Ident:
						if e.Name != receiverName {
							continue
						}
					default:
						continue
					}
					return true
				}
			}
			return false
		}
		assignmentsToReceiver := pick(funcDecl.Body, fselect)
		for _, assignment := range assignmentsToReceiver {
			failures = append(failures, lint.Failure{
				Node:       assignment,
				Confidence: 1,
				Failure:    "suspicious assignment to a by-value method receiver",
			})
		}
	}
	return failures
}

func receiverIsReturned(body *ast.BlockStmt, receiverName string) bool {
	found := false
	ast.Inspect(body, func(n ast.Node) bool {
		if found {
			return false
		}
		rs, ok := n.(*ast.ReturnStmt)
		if !ok {
			return true
		}
		for _, res := range rs.Results {
			if id, ok := res.(*ast.Ident); ok && id.Name == receiverName {
				found = true
				return false
			}
		}
		return true
	})
	return found
}

// UnexportedNamingRule lints wrongly named unexported symbols.
type UnexportedNamingRule struct{}

func init() { register(&UnexportedNamingRule{}, false) }

// Name returns the rule name.
func (*UnexportedNamingRule) Name() string { return "unexported-naming" }

// Apply applies the rule to given file.
func (*UnexportedNamingRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	lintIDs := func(ids []*ast.Ident) {
		for _, id := range ids {
			if id.IsExported() {
				failures = append(failures, lint.Failure{
					Node:       id,
					Confidence: 1,
					Category:   lint.FailureCategoryNaming,
					Failure:    fmt.Sprintf("the symbol %s is local, its name should start with a lowercase letter", id.String()),
				})
			}
		}
	}
	lintFields := func(fields *ast.FieldList) {
		if fields == nil {
			return
		}
		ids := []*ast.Ident{}
		for _, field := range fields.List {
			ids = append(ids, field.Names...)
		}
		lintIDs(ids)
	}
	var v walker
	lintFunction := func(ft *ast.FuncType, body *ast.BlockStmt) {
		lintFields(ft.Params)
		lintFields(ft.Results)
		if body != nil {
			ast.Walk(v, body)
		}
	}
	v = func(node ast.Node) bool {
		switch n := node.(type) {
		case *ast.FuncDecl:
			lintFunction(n.Type, n.Body)
			return false
		case *ast.FuncLit:
			lintFunction(n.Type, n.Body)
			return false
		case *ast.AssignStmt:
			if n.Tok != token.DEFINE {
				return false
			}
			ids := []*ast.Ident{}
			for _, e := range n.Lhs {
				id, ok := e.(*ast.Ident)
				if !ok {
					continue
				}
				ids = append(ids, id)
			}
			lintIDs(ids)
		case *ast.DeclStmt:
			gd, ok := n.Decl.(*ast.GenDecl)
			if !ok {
				return false
			}
			if len(gd.Specs) < 1 {
				return false
			}
			vs, ok := gd.Specs[0].(*ast.ValueSpec)
			if !ok {
				return false
			}
			lintIDs(vs.Names)
		}
		return true
	}
	ast.Walk(v, file.AST)
	return failures
}

// UnnecessaryStmtRule warns on unnecessary statements.
type UnnecessaryStmtRule struct{}

func init() { register(&UnnecessaryStmtRule{}, false) }

// Name returns the rule name.
func (*UnnecessaryStmtRule) Name() string { return "unnecessary-stmt" }

// Apply applies the rule to given file.
func (*UnnecessaryStmtRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	newFailure := func(node ast.Node, msg string) {
		failures = append(failures, lint.Failure{Confidence: 1, Node: node, Category: lint.FailureCategoryStyle, Failure: msg})
	}
	checkSwitchBody := func(b *ast.BlockStmt) {
		cases := b.List
		if len(cases) != 1 {
			return
		}
		cc, ok := cases[0].(*ast.CaseClause)
		if !ok {
			return
		}
		if len(cc.List) > 1 {
			return
		}
		newFailure(b, "switch with only one case can be replaced by an if-then")
	}
	ast.Walk(walker(func(node ast.Node) bool {
		switch n := node.(type) {
		case *ast.FuncDecl:
			if n.Body == nil || n.Type.Results != nil {
				return true
			}
			stmts := n.Body.List
			if len(stmts) == 0 {
				return true
			}
			lastStmt := stmts[len(stmts)-1]
			rs, ok := lastStmt.(*ast.ReturnStmt)
			if !ok {
				return true
			}
			if len(rs.Results) == 0 {
				newFailure(lastStmt, "omit unnecessary return statement")
			}
		case *ast.SwitchStmt:
			checkSwitchBody(n.Body)
		case *ast.TypeSwitchStmt:
			checkSwitchBody(n.Body)
		case *ast.CaseClause:
			if n.Body == nil {
				return true
			}
			stmts := n.Body
			if len(stmts) == 0 {
				return true
			}
			lastStmt := stmts[len(stmts)-1]
			rs, ok := lastStmt.(*ast.BranchStmt)
			if !ok {
				return true
			}
			if rs.Tok == token.BREAK && rs.Label == nil {
				newFailure(lastStmt, "omit unnecessary break at the end of case clause")
			}
		}
		return true
	}), file.AST)
	return failures
}

// UnusedReceiverRule lints unused receivers in methods.
type UnusedReceiverRule struct {
	allowRegex *regexp.Regexp
	failureMsg string
}

func init() { register(&UnusedReceiverRule{}, false) }

// Name returns the rule name.
func (*UnusedReceiverRule) Name() string { return "unused-receiver" }

// Configure validates the rule configuration.
func (r *UnusedReceiverRule) Configure(args lint.Arguments) error {
	r.failureMsg = "method receiver '%s' is not referenced in method's body, consider removing or renaming it as _"
	r.allowRegex = allowBlankIdentifierRegex
	if len(args) == 0 {
		return nil
	}
	options, ok := args[0].(map[string]any)
	if !ok {
		return nil
	}
	var allowRegexParam any
	found := false
	for k, v := range options {
		if isRuleOption(k, "allowRegex") {
			allowRegexParam = v
			found = true
		}
	}
	if !found {
		return nil
	}
	allowRegexStr, ok := allowRegexParam.(string)
	if !ok {
		return fmt.Errorf("error configuring [unused-receiver] rule: allowRegex is not string but [%T]", allowRegexParam)
	}
	var err error
	r.allowRegex, err = regexp.Compile(allowRegexStr)
	if err != nil {
		return fmt.Errorf("error configuring [unused-receiver] rule: allowRegex is not valid regex [%s]: %w", allowRegexStr, err)
	}
	r.failureMsg = "method receiver '%s' is not referenced in method's body, consider removing or renaming it to match " + r.allowRegex.String()
	return nil
}

// Apply applies the rule to given file.
func (r *UnusedReceiverRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Walk(walker(func(node ast.Node) bool {
		n, ok := node.(*ast.FuncDecl)
		if !ok {
			return true
		}
		if n.Recv == nil {
			return false
		}
		rec := n.Recv.List[0]
		if len(rec.Names) < 1 {
			return false
		}
		recID := rec.Names[0]
		if recID.Name == "_" {
			return false
		}
		if r.allowRegex.FindStringIndex(recID.Name) != nil {
			return false
		}
		fselect := func(n ast.Node) bool {
			ident, isAnID := n.(*ast.Ident)
			return isAnID && ident.Obj == recID.Obj
		}
		if len(pick(n.Body, fselect)) > 0 {
			return false
		}
		failures = append(failures, lint.Failure{
			Confidence: 1,
			Node:       recID,
			Category:   lint.FailureCategoryBadPractice,
			Failure:    fmt.Sprintf(r.failureMsg, recID.Name),
		})
		return false
	}), file.AST)
	return failures
}

// UseAnyRule proposes to replace `interface{}` with its alias `any`.
type UseAnyRule struct{}

func init() { register(&UseAnyRule{}, false) }

// Name returns the rule name.
func (*UseAnyRule) Name() string { return "use-any" }

// Apply applies the rule to given file.
func (*UseAnyRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Walk(walker(func(n ast.Node) bool {
		it, ok := n.(*ast.InterfaceType)
		if !ok {
			return true
		}
		if len(it.Methods.List) != 0 {
			return true
		}
