func (*UnnecessaryStmtRule) Name() string { return "unnecessary-stmt" }

// Apply applies the rule to given file.
func (*UnnecessaryStmtRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	newFailure := func(node ast.Node, msg string) {
		failures = append(failures, lint.Failure{Confidence: 1, Node: node, Category: lint.FailureCategoryStyle, Failure: msg})
	}
	checkSwitchBody := func(b *ast.BlockStmt) {
		cases := b.List
		if len(cases) != 1 {
			return
		}
		cc, ok := cases[0].(*ast.CaseClause)
		if !ok {
			return
		}
		if len(cc.List) > 1 {
			return
		}
		newFailure(b, "switch with only one case can be replaced by an if-then")
	}
	ast.Walk(walker(func(node ast.Node) bool {
		switch n := node.(type) {
		case *ast.FuncDecl:
			if n.Body == nil || n.Type.Results != nil {
				return true
			}
			stmts := n.Body.List
			if len(stmts) == 0 {
				return true
			}
			lastStmt := stmts[len(stmts)-1]
			rs, ok := lastStmt.(*ast.ReturnStmt)
			if !ok {
				return true
			}
			if len(rs.Results) == 0 {
				newFailure(lastStmt, "omit unnecessary return statement")
			}
		case *ast.SwitchStmt:
			checkSwitchBody(n.Body)
		case *ast.TypeSwitchStmt:
			checkSwitchBody(n.Body)
		case *ast.CaseClause:
			if n.Body == nil {
				return true
			}
			stmts := n.Body
			if len(stmts) == 0 {
				return true
			}
			lastStmt := stmts[len(stmts)-1]
			rs, ok := lastStmt.(*ast.BranchStmt)
			if !ok {
				return true
			}
			if rs.Tok == token.BREAK && rs.Label == nil {
				newFailure(lastStmt, "omit unnecessary break at the end of case clause")
			}
		}
		return true
	}), file.AST)
	return failures
}

// UnusedReceiverRule lints unused receivers in methods.
type UnusedReceiverRule struct {
	allowRegex *regexp.Regexp
	failureMsg string
}

func init() { register(&UnusedReceiverRule{}, false) }

// Name returns the rule name.
func (*UnusedReceiverRule) Name() string { return "unused-receiver" }

// Configure validates the rule configuration.
func (r *UnusedReceiverRule) Configure(args lint.Arguments) error {
	r.failureMsg = "method receiver '%s' is not referenced in method's body, consider removing or renaming it as _"
	r.allowRegex = allowBlankIdentifierRegex
	if len(args) == 0 {
		return nil
	}
	options, ok := args[0].(map[string]any)
	if !ok {
		return nil
	}
	var allowRegexParam any
	found := false
	for k, v := range options {
		if isRuleOption(k, "allowRegex") {
			allowRegexParam = v
			found = true
		}
	}
	if !found {
		return nil
	}
	allowRegexStr, ok := allowRegexParam.(string)
	if !ok {
		return fmt.Errorf("error configuring [unused-receiver] rule: allowRegex is not string but [%T]", allowRegexParam)
	}
	var err error
	r.allowRegex, err = regexp.Compile(allowRegexStr)
	if err != nil {
		return fmt.Errorf("error configuring [unused-receiver] rule: allowRegex is not valid regex [%s]: %w", allowRegexStr, err)
	}
	r.failureMsg = "method receiver '%s' is not referenced in method's body, consider removing or renaming it to match " + r.allowRegex.String()
	return nil
}

// Apply applies the rule to given file.
func (r *UnusedReceiverRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Walk(walker(func(node ast.Node) bool {
		n, ok := node.(*ast.FuncDecl)
		if !ok {
			return true
		}
		if n.Recv == nil {
			return false
		}
		rec := n.Recv.List[0]
		if len(rec.Names) < 1 {
			return false
		}
		recID := rec.Names[0]
		if recID.Name == "_" {
			return false
		}
		if r.allowRegex.FindStringIndex(recID.Name) != nil {
			return false
		}
		fselect := func(n ast.Node) bool {
			ident, isAnID := n.(*ast.Ident)
			return isAnID && ident.Obj == recID.Obj
		}
		if len(pick(n.Body, fselect)) > 0 {
			return false
		}
		failures = append(failures, lint.Failure{
			Confidence: 1,
			Node:       recID,
			Category:   lint.FailureCategoryBadPractice,
			Failure:    fmt.Sprintf(r.failureMsg, recID.Name),
		})
		return false
	}), file.AST)
	return failures
}

// UseAnyRule proposes to replace `interface{}` with its alias `any`.
type UseAnyRule struct{}

func init() { register(&UseAnyRule{}, false) }

// Name returns the rule name.
func (*UseAnyRule) Name() string { return "use-any" }

// Apply applies the rule to given file.
func (*UseAnyRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Walk(walker(func(n ast.Node) bool {
		it, ok := n.(*ast.InterfaceType)
		if !ok {
			return true
		}
		if len(it.Methods.List) != 0 {
			return true
		}
		failures = append(failures, lint.Failure{
			Node:       n,
			Confidence: 1,
			Category:   lint.FailureCategoryNaming,
			Failure:    "since Go 1.18 'interface{}' can be replaced by 'any'",
		})
		return true
	}), file.AST)
	return failures
}

// UselessBreak lint rule.
type UselessBreak struct{}

func init() { register(&UselessBreak{}, false) }

// Name returns the rule name.
func (*UselessBreak) Name() string { return "useless-break" }

type lintUselessBreak struct {
	onFailure  func(lint.Failure)
	inLoopBody bool
}

func (w *lintUselessBreak) Visit(node ast.Node) ast.Visitor {
	switch v := node.(type) {
	case *ast.ForStmt:
		w.inLoopBody = true
		ast.Walk(w, v.Body)
		w.inLoopBody = false
		return nil
	case *ast.RangeStmt:
		w.inLoopBody = true
		ast.Walk(w, v.Body)
		w.inLoopBody = false
		return nil
	case *ast.CommClause:
		for _, n := range v.Body {
			w.inspectCaseStatement(n)
		}
		return nil
	case *ast.CaseClause:
		for _, n := range v.Body {
			w.inspectCaseStatement(n)
		}
		return nil
	}
	return w
}

func (w *lintUselessBreak) inspectCaseStatement(n ast.Stmt) {
	switch s := n.(type) {
	case *ast.BranchStmt:
		if s.Tok != token.BREAK {
			return
		}
		if s.Label != nil {
			return
		}
		msg := "useless break in case clause"
		if w.inLoopBody {
			msg += " (WARN: this break statement affects this switch or select statement and not the loop enclosing it)"
		}
		w.onFailure(lint.Failure{
			Confidence: 1,
			Node:       s,
			Failure:    msg,
		})
	default:
		ast.Walk(w, s)
	}
}

// Apply applies the rule to given file.
func (*UselessBreak) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	w := &lintUselessBreak{onFailure: func(f lint.Failure) { failures = append(failures, f) }}
	ast.Walk(w, file.AST)
	return failures
}

// IfReturnRule searches for redundant `if` when returning an error.
type IfReturnRule struct{}

func init() { register(&IfReturnRule{}, false) }

// Name returns the rule name.
func (*IfReturnRule) Name() string { return "if-return" }

// Apply applies the rule to given file.
func (*IfReturnRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Walk(walker(func(node ast.Node) bool {
		v, ok := node.(*ast.BlockStmt)
		if !ok {
			return true
		}
		for i := 0; i < len(v.List)-1; i++ {
			s, ok := v.List[i].(*ast.IfStmt)
			if !ok || s.Body == nil || len(s.Body.List) != 1 || s.Else != nil {
				continue
			}
			assign, ok := s.Init.(*ast.AssignStmt)
			if !ok || len(assign.Lhs) != 1 || !(assign.Tok == token.DEFINE || assign.Tok == token.ASSIGN) {
				continue
			}
			id, ok := assign.Lhs[0].(*ast.Ident)
			if !ok {
				continue
			}
			expr, ok := s.Cond.(*ast.BinaryExpr)
			if !ok || expr.Op != token.NEQ {
				continue
			}
			if lhs, ok := expr.X.(*ast.Ident); !ok || lhs.Name != id.Name {
				continue
			}
			if rhs, ok := expr.Y.(*ast.Ident); !ok || rhs.Name != "nil" {
				continue
			}
			r, ok := s.Body.List[0].(*ast.ReturnStmt)
			if !ok || len(r.Results) != 1 {
				continue
			}
			if r, ok := r.Results[0].(*ast.Ident); !ok || r.Name != id.Name {
				continue
			}
			r, ok = v.List[i+1].(*ast.ReturnStmt)
			if !ok || len(r.Results) != 1 {
				continue
			}
			if r, ok := r.Results[0].(*ast.Ident); !ok || r.Name != "nil" {
				continue
			}
			if containsComments(s.Pos(), r.Pos(), file.AST) {
				continue
			}
			failures = append(failures, lint.Failure{
				Confidence: .9,
				Node:       v.List[i],
				Failure:    "redundant if ...; err != nil check, just return error instead.",
			})
		}
		return true
	}), file.AST)
	return failures
}

func containsComments(start, end token.Pos, f *ast.File) bool {
	for _, cgroup := range f.Comments {
		comments := cgroup.List
		if comments[0].Slash >= end {
			return false
		}
		if comments[len(comments)-1].Slash < start {
			continue
		}
		for _, c := range comments {
			if start <= c.Slash && c.Slash < end && !strings.HasPrefix(c.Text, "// MATCH ") {
				return true
			}
		}
	}
	return false
}
