// ImportsBlocklistRule disallows blocklisted imports.
type ImportsBlocklistRule struct {
	blocklist []*regexp.Regexp
}

func init() { register(&ImportsBlocklistRule{}, false) }

// Name returns the rule name.
func (*ImportsBlocklistRule) Name() string { return "imports-blocklist" }

var replaceImportRegexp = regexp.MustCompile(`/?\*\*/?`)

// Configure validates the rule configuration.
func (r *ImportsBlocklistRule) Configure(arguments lint.Arguments) error {
	r.blocklist = []*regexp.Regexp{}
	for _, arg := range arguments {
		argStr, ok := arg.(string)
		if !ok {
			return fmt.Errorf("invalid argument to the imports-blocklist rule. Expecting a string, got %T", arg)
		}
		regStr, err := regexp.Compile(fmt.Sprintf(`(?m)"%s"$`, replaceImportRegexp.ReplaceAllString(argStr, `(\W|\w)*`)))
		if err != nil {
			return fmt.Errorf("invalid argument to the imports-blocklist rule. Expecting %q to be a valid regular expression, got: %w", argStr, err)
		}
		r.blocklist = append(r.blocklist, regStr)
	}
	return nil
}

// Apply applies the rule to given file.
func (r *ImportsBlocklistRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	for _, is := range file.AST.Imports {
		path := is.Path
		if path == nil {
			continue
		}
		blocked := false
		for _, regex := range r.blocklist {
			if regex.MatchString(path.Value) {
				blocked = true
				break
			}
		}
		if blocked {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Failure:    "should not use the following blocklisted import: " + path.Value,
				Node:       is,
				Category:   lint.FailureCategoryImports,
			})
		}
	}
	return failures
}

// DeferRule lints gotchas in defer statements.
type DeferRule struct {
	allow map[string]bool
}

func init() { register(&DeferRule{}, false) }

// Name returns the rule name.
func (*DeferRule) Name() string { return "defer" }

// Configure validates the rule configuration.
func (r *DeferRule) Configure(arguments lint.Arguments) error {
	list, err := r.allowFromArgs(arguments)
	if err != nil {
		return err
	}
	r.allow = list
	return nil
}

func (*DeferRule) allowFromArgs(args lint.Arguments) (map[string]bool, error) {
	if len(args) < 1 {
		allow := map[string]bool{
			"loop":              true,
			"call-chain":        true,
			"method-call":       true,
			"return":            true,
			"recover":           true,
			"immediate-recover": true,
		}
		return allow, nil
	}
	aa, ok := args[0].([]any)
	if !ok {
		return nil, fmt.Errorf("invalid argument '%v' for 'defer' rule. Expecting []string, got %T", args[0], args[0])
	}
	allow := make(map[string]bool, len(aa))
	for _, subcase := range aa {
		sc, ok := subcase.(string)
		if !ok {
			return nil, fmt.Errorf("invalid argument '%v' for 'defer' rule. Expecting string, got %T", subcase, subcase)
		}
		allow[sc] = true
	}
	return allow, nil
}

type lintDeferRule struct {
	onFailure  func(lint.Failure)
	inALoop    bool
	inADefer   bool
	inAFuncLit bool
	allow      map[string]bool
}

func (w lintDeferRule) Visit(node ast.Node) ast.Visitor {
	switch n := node.(type) {
	case *ast.ForStmt:
		w.visitSubtree(n.Body, w.inADefer, true, w.inAFuncLit)
		return nil
	case *ast.RangeStmt:
		w.visitSubtree(n.Body, w.inADefer, true, w.inAFuncLit)
		return nil
	case *ast.FuncLit:
		w.visitSubtree(n.Body, w.inADefer, false, true)
		return nil
	case *ast.ReturnStmt:
		if len(n.Results) != 0 && w.inADefer && w.inAFuncLit {
			w.newFailure("return in a defer function has no effect", n, 1.0, lint.FailureCategoryLogic, "return")
		}
	case *ast.CallExpr:
		isCallToRecover := isIdent(n.Fun, "recover")
		switch {
		case !w.inADefer && isCallToRecover:
			w.newFailure("recover must be called inside a deferred function", n, 0.8, lint.FailureCategoryLogic, "recover")
		case w.inADefer && !w.inAFuncLit && isCallToRecover:
			w.newFailure("recover must be called inside a deferred function, this is executing recover immediately", n, 1, lint.FailureCategoryLogic, "immediate-recover")
		}
		return nil
	case *ast.DeferStmt:
		if isIdent(n.Call.Fun, "recover") {
			w.newFailure("recover must be called inside a deferred function, this is executing recover immediately", n, 1, lint.FailureCategoryLogic, "immediate-recover")
		}
		w.visitSubtree(n.Call.Fun, true, false, true)
		for _, a := range n.Call.Args {
			switch a.(type) {
			case *ast.FuncLit:
				continue
			default:
				w.visitSubtree(a, true, false, false)
			}
		}
		if w.inALoop {
			w.newFailure("prefer not to defer inside loops", n, 1.0, lint.FailureCategoryBadPractice, "loop")
		}
		switch fn := n.Call.Fun.(type) {
		case *ast.CallExpr:
			w.newFailure("prefer not to defer chains of function calls", fn, 1.0, lint.FailureCategoryBadPractice, "call-chain")
		case *ast.SelectorExpr:
			if id, ok := fn.X.(*ast.Ident); ok {
				isMethodCall := id != nil && id.Obj != nil && id.Obj.Kind == ast.Typ
				if isMethodCall {
					w.newFailure("be careful when deferring calls to methods without pointer receiver", fn, 0.8, lint.FailureCategoryBadPractice, "method-call")
				}
			}
		}
		return nil
	}
	return w
}

func (w lintDeferRule) visitSubtree(n ast.Node, inADefer, inALoop, inAFuncLit bool) {
	nw := lintDeferRule{
		onFailure:  w.onFailure,
		inADefer:   inADefer,
		inALoop:    inALoop,
		inAFuncLit: inAFuncLit,
		allow:      w.allow,
	}
	ast.Walk(nw, n)
}

func (w lintDeferRule) newFailure(msg string, node ast.Node, confidence float64, cat, subcase string) {
	if !w.allow[subcase] {
		return
	}
	w.onFailure(lint.Failure{
		Confidence: confidence,
		Node:       node,
		Category:   cat,
		Failure:    msg,
	})
}

// Apply applies the rule to given file.
func (r *DeferRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	w := lintDeferRule{onFailure: func(f lint.Failure) { failures = append(failures, f) }, allow: r.allow}
	ast.Walk(w, file.AST)
	return failures
}

// RangeValAddress lints range values address.
type RangeValAddress struct{}

func init() { register(&RangeValAddress{}, false) }

// Name returns the rule name.
func (*RangeValAddress) Name() string { return "range-val-address" }

type rangeBodyVisitor struct {
	valueIsStarExpr bool
	valueID         *ast.Object
	onFailure       func(lint.Failure)
}

func (bw rangeBodyVisitor) Visit(node ast.Node) ast.Visitor {
	asgmt, ok := node.(*ast.AssignStmt)
	if !ok {
		return bw
	}
	for _, exp := range asgmt.Lhs {
		e, ok := exp.(*ast.IndexExpr)
		if !ok {
			continue
		}
		if bw.isAccessingRangeValueAddress(e.Index) {
			bw.onFailure(bw.newFailure(e.Index))
		}
	}
	for _, exp := range asgmt.Rhs {
		switch e := exp.(type) {
		case *ast.UnaryExpr:
			if bw.isAccessingRangeValueAddress(e) {
				bw.onFailure(bw.newFailure(e))
			}
		case *ast.CallExpr:
			if fun, ok := e.Fun.(*ast.Ident); ok && fun.Name == "append" {
				for _, v := range e.Args {
					if lit, ok := v.(*ast.CompositeLit); ok {
						bw.checkCompositeLit(lit)
						continue
					}
					if bw.isAccessingRangeValueAddress(v) {
						bw.onFailure(bw.newFailure(v))
					}
				}
			}
		case *ast.CompositeLit:
			bw.checkCompositeLit(e)
		}
	}
	return bw
}

func (bw rangeBodyVisitor) checkCompositeLit(comp *ast.CompositeLit) {
	for _, exp := range comp.Elts {
		e, ok := exp.(*ast.KeyValueExpr)
		if !ok {
			continue
		}
		if bw.isAccessingRangeValueAddress(e.Value) {
			bw.onFailure(bw.newFailure(e.Value))
		}
	}
}

func (bw rangeBodyVisitor) isAccessingRangeValueAddress(exp ast.Expr) bool {
	u, ok := exp.(*ast.UnaryExpr)
	if !ok {
		return false
	}
	if u.Op != token.AND {
		return false
	}
	v, ok := u.X.(*ast.Ident)
	if !ok {
		var s *ast.SelectorExpr
		s, ok = u.X.(*ast.SelectorExpr)
		if !ok {
			return false
		}
		v, ok = s.X.(*ast.Ident)
		if !ok {
			return false
		}
		if bw.valueIsStarExpr {
			return false
		}
	}
	return ok && v.Obj == bw.valueID
}

func (bw rangeBodyVisitor) newFailure(node ast.Node) lint.Failure {
	return lint.Failure{
		Node:       node,
		Confidence: 1,
		Failure:    fmt.Sprintf("suspicious assignment of '%s'. range-loop variables always have the same address", bw.valueID.Name),
	}
}

// Apply applies the rule to given file.
func (*RangeValAddress) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	if file.Pkg.IsAtLeastGoVersion(goVersion122) {
		return failures
	}
	_ = file.Pkg.TypeCheck()
	onFailure := func(f lint.Failure) { failures = append(failures, f) }
	ast.Walk(walker(func(node ast.Node) bool {
		n, ok := node.(*ast.RangeStmt)
		if !ok {
			return true
		}
		value, ok := n.Value.(*ast.Ident)
		if !ok {
			return true
		}
		valueIsStarExpr := false
		if t := file.Pkg.TypeOf(value); t != nil {
			valueIsStarExpr = strings.HasPrefix(t.String(), "*")
		}
		ast.Walk(rangeBodyVisitor{
			valueIsStarExpr: valueIsStarExpr,
			valueID:         value.Obj,
			onFailure:       onFailure,
		}, n.Body)
		return true
	}), file.AST)
	return failures
}

// RangeValInClosureRule lints range values in closures.
type RangeValInClosureRule struct{}

func init() { register(&RangeValInClosureRule{}, false) }

// Name returns the rule name.
func (*RangeValInClosureRule) Name() string { return "range-val-in-closure" }

// Apply applies the rule to given file.
func (*RangeValInClosureRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	if file.Pkg.IsAtLeastGoVersion(goVersion122) {
		return failures
	}
	ast.Walk(walker(func(node ast.Node) bool {
		var vars []*ast.Ident
		inspectVars := func(n ast.Node) {
			if v, ok := n.(*ast.Ident); ok {
				vars = append(vars, v)
			}
		}
		var body *ast.BlockStmt
		switch n := node.(type) {
		case *ast.RangeStmt:
			body = n.Body
			inspectVars(n.Key)
			inspectVars(n.Value)
		case *ast.ForStmt:
			body = n.Body
			switch s := n.Post.(type) {
			case *ast.AssignStmt:
				for _, lhs := range s.Lhs {
					inspectVars(lhs)
				}
			case *ast.IncDecStmt:
				inspectVars(s.X)
			}
		default:
			return true
		}
		if vars == nil {
			return true
		}
		if len(body.List) == 0 {
			return true
		}
		var last *ast.CallExpr
		switch s := body.List[len(body.List)-1].(type) {
		case *ast.GoStmt:
			last = s.Call
		case *ast.DeferStmt:
			last = s.Call
		default:
			return true
		}
		lit, ok := last.Fun.(*ast.FuncLit)
		if !ok {
			return true
		}
		if lit.Type == nil {
			return true
		}
		ast.Inspect(lit.Body, func(n ast.Node) bool {
			id, ok := n.(*ast.Ident)
			if !ok || id.Obj == nil {
				return true
			}
			for _, v := range vars {
				if v.Obj == id.Obj {
					failures = append(failures, lint.Failure{
						Confidence: 1,
						Failure:    fmt.Sprintf("loop variable %v captured by func literal", id.Name),
						Node:       n,
					})
				}
			}
			return true
		})
		return true
	}), file.AST)
	return failures
}
