			inspectVars(n.Value)
		case *ast.ForStmt:
			body = n.Body
			switch s := n.Post.(type) {
			case *ast.AssignStmt:
				for _, lhs := range s.Lhs {
					inspectVars(lhs)
				}
			case *ast.IncDecStmt:
				inspectVars(s.X)
			}
		default:
			return true
		}
