		case *ast.DeferStmt:
			last = s.Call
		default:
			return true
		}
		lit, ok := last.Fun.(*ast.FuncLit)
		if !ok {
			return true
		}
		if lit.Type == nil {
			return true
		}
		ast.Inspect(lit.Body, func(n ast.Node) bool {
			id, ok := n.(*ast.Ident)
			if !ok || id.Obj == nil {
				return true
			}
			for _, v := range vars {
				if v.Obj == id.Obj {
