// Apply applies the rule to given file.
func (r *LineLengthLimitRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	f := bytes.NewReader(file.Content())
	l := 1
	s := bufio.NewScanner(f)
	for s.Scan() {
		t := s.Text()
		t = strings.ReplaceAll(t, "\t", " ")
		c := utf8.RuneCountInString(t)
		if c > r.max {
			failures = append(failures, lint.Failure{
				Category: lint.FailureCategoryCodeStyle,
				Position: lint.FailurePosition{
					Start: token.Position{Filename: file.Name, Line: l, Column: 0},
					End:   token.Position{Filename: file.Name, Line: l, Column: c},
				},
				Confidence: 1,
				Failure:    fmt.Sprintf("line is %d characters, out of limit %d", c, r.max),
			})
		}
		l++
	}
	return failures
}

func funcName(fn *ast.FuncDecl) string {
	if fn.Recv != nil {
		if fn.Recv.NumFields() > 0 {
			typ := fn.Recv.List[0].Type
			return fmt.Sprintf("(%s).%s", recvString(typ), fn.Name)
		}
	}
	return fn.Name.Name
}

func recvString(recv ast.Expr) string {
	switch t := recv.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return "*" + recvString(t.X)
	}
	return "BADRECV"
}

// CyclomaticRule sets restriction for maximum cyclomatic complexity.
type CyclomaticRule struct{ maxComplexity int }

func init() { register(&CyclomaticRule{}, false) }

// Name returns the rule name.
func (*CyclomaticRule) Name() string { return "cyclomatic" }

// Configure validates the rule configuration.
func (r *CyclomaticRule) Configure(arguments lint.Arguments) error {
	if len(arguments) < 1 {
		r.maxComplexity = 10
		return nil
	}
	complexity, ok := arguments[0].(int64)
	if !ok {
		return fmt.Errorf("invalid argument for cyclomatic complexity; expected int but got %T", arguments[0])
	}
	r.maxComplexity = int(complexity)
	return nil
}

// Apply applies the rule to given file.
func (r *CyclomaticRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	for _, decl := range file.AST.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		c := 0
		ast.Inspect(fn, func(n ast.Node) bool {
			switch n := n.(type) {
			case *ast.FuncDecl, *ast.IfStmt, *ast.ForStmt, *ast.RangeStmt, *ast.CaseClause, *ast.CommClause:
				c++
			case *ast.BinaryExpr:
				if n.Op == token.LAND || n.Op == token.LOR {
					c++
				}
			}
			return true
		})
		if c > r.maxComplexity {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Category:   lint.FailureCategoryMaintenance,
				Failure:    fmt.Sprintf("function %s has cyclomatic complexity %d (> max enabled %d)", funcName(fn), c, r.maxComplexity),
				Node:       fn,
			})
		}
	}
	return failures
}

// CognitiveComplexityRule sets restriction for maximum cognitive complexity.
type CognitiveComplexityRule struct{ maxComplexity int }

func init() { register(&CognitiveComplexityRule{}, false) }

// Name returns the rule name.
func (*CognitiveComplexityRule) Name() string { return "cognitive-complexity" }

// Configure validates the rule configuration.
func (r *CognitiveComplexityRule) Configure(arguments lint.Arguments) error {
	if len(arguments) < 1 {
		r.maxComplexity = 7
		return nil
	}
	complexity, ok := arguments[0].(int64)
	if !ok {
		return fmt.Errorf("invalid argument type for cognitive-complexity, expected int64, got %T", arguments[0])
	}
	r.maxComplexity = int(complexity)
	return nil
}

// Apply applies the rule to given file.
func (r *CognitiveComplexityRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	for _, decl := range file.AST.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			continue
		}
		v := cognitiveComplexityVisitor{name: fn.Name}
		c := v.subTreeComplexity(fn.Body)
		if c > r.maxComplexity {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Category:   lint.FailureCategoryMaintenance,
				Failure:    fmt.Sprintf("function %s has cognitive complexity %d (> max enabled %d)", funcName(fn), c, r.maxComplexity),
				Node:       fn,
			})
		}
	}
	return failures
}

type cognitiveComplexityVisitor struct {
	name         *ast.Ident
	complexity   int
	nestingLevel int
}

func (v cognitiveComplexityVisitor) subTreeComplexity(n ast.Node) int {
	ast.Walk(&v, n)
	return v.complexity
}

func (v *cognitiveComplexityVisitor) Visit(n ast.Node) ast.Visitor {
	switch n := n.(type) {
	case *ast.IfStmt:
		v.walk(1, n.Cond, n.Body, n.Else)
		return nil
	case *ast.ForStmt:
		v.walk(1, n.Cond, n.Body)
		return nil
	case *ast.RangeStmt:
		v.walk(1, n.Body)
		return nil
	case *ast.SelectStmt:
		v.walk(1, n.Body)
		return nil
	case *ast.SwitchStmt:
		v.walk(1, n.Body)
		return nil
	case *ast.TypeSwitchStmt:
		v.walk(1, n.Body)
		return nil
	case *ast.FuncLit:
		v.walk(0, n.Body)
		return nil
	case *ast.BinaryExpr:
		v.complexity += binExpComplexity(n)
		return nil
	case *ast.BranchStmt:
		if n.Label != nil {
			v.complexity++
		}
	case *ast.CallExpr:
		if ident, ok := n.Fun.(*ast.Ident); ok {
			if ident.Obj == v.name.Obj && ident.Name == v.name.Name {
				v.complexity++
				return nil
			}
		}
	}
	return v
}

func (v *cognitiveComplexityVisitor) walk(complexityIncrement int, targets ...ast.Node) {
	v.complexity += complexityIncrement + v.nestingLevel
	nesting := v.nestingLevel
	v.nestingLevel++
	for _, t := range targets {
		if t == nil || isNilNode(t) {
			continue
		}
		ast.Walk(v, t)
	}
	v.nestingLevel = nesting
}

func isNilNode(n ast.Node) bool {
	switch t := n.(type) {
	case ast.Expr:
		return t == nil || fmt.Sprintf("%p", t) == "0x0"
	case ast.Stmt:
		return t == nil || fmt.Sprintf("%p", t) == "0x0"
	}
	return false
}

func binExpComplexity(n *ast.BinaryExpr) int {
	calculator := binExprComplexityCalculator{opsStack: []token.Token{}}
	astutil.Apply(n, calculator.pre, calculator.post)
	return calculator.complexity
}

type binExprComplexityCalculator struct {
	complexity    int
	opsStack      []token.Token
	subexpStarted bool
}

func (becc *binExprComplexityCalculator) pre(c *astutil.Cursor) bool {
	switch n := c.Node().(type) {
	case *ast.BinaryExpr:
		isBoolOp := n.Op == token.LAND || n.Op == token.LOR
		if !isBoolOp {
			break
		}
		ops := len(becc.opsStack)
		if ops == 0 || becc.subexpStarted || n.Op != becc.opsStack[ops-1] {
			becc.complexity++
			becc.subexpStarted = false
		}
		becc.opsStack = append(becc.opsStack, n.Op)
	case *ast.ParenExpr:
		becc.subexpStarted = true
	}
	return true
}

func (becc *binExprComplexityCalculator) post(c *astutil.Cursor) bool {
	switch n := c.Node().(type) {
	case *ast.BinaryExpr:
		isBoolOp := n.Op == token.LAND || n.Op == token.LOR
		if !isBoolOp {
			break
		}
		ops := len(becc.opsStack)
		if ops > 0 {
			becc.opsStack = becc.opsStack[:ops-1]
		}
	case *ast.ParenExpr:
		becc.subexpStarted = false
	}
	return true
}

// FunctionLength lint.
type FunctionLength struct {
	maxStmt  int
	maxLines int
}

func init() { register(&FunctionLength{}, false) }

// Name returns the rule name.
func (*FunctionLength) Name() string { return "function-length" }

// Configure validates the rule configuration.
func (r *FunctionLength) Configure(arguments lint.Arguments) error {
	if len(arguments) == 0 {
		r.maxStmt, r.maxLines = 50, 75
		return nil
	}
	const minArguments = 2
	if len(arguments) != minArguments {
		return fmt.Errorf(`invalid configuration for "function-length" rule, expected %d arguments but got %d`, minArguments, len(arguments))
	}
	maxStmt, ok := arguments[0].(int64)
	if !ok {
		return fmt.Errorf(`invalid configuration value for max statements in "function-length" rule; need int64 but got %T`, arguments[0])
	}
	if maxStmt < 0 {
		return fmt.Errorf(`the configuration value for max statements in "function-length" rule cannot be negative, got %d`, maxStmt)
	}
	maxLines, ok := arguments[1].(int64)
	if !ok {
		return fmt.Errorf(`invalid configuration value for max lines in "function-length" rule; need int64 but got %T`, arguments[1])
	}
	if maxLines < 0 {
		return fmt.Errorf(`the configuration value for max statements in "function-length" rule cannot be negative, got %d`, maxLines)
	}
	r.maxStmt, r.maxLines = int(maxStmt), int(maxLines)
	return nil
}

// Apply applies the rule to given file.
func (r *FunctionLength) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Walk(walker(func(n ast.Node) bool {
		node, ok := n.(*ast.FuncDecl)
		if !ok {
			return true
		}
		body := node.Body
		if body == nil || len(node.Body.List) == 0 {
			return false
		}
		if r.maxStmt > 0 {
			stmtCount := countStmts(node.Body.List)
			if stmtCount > r.maxStmt {
				failures = append(failures, lint.Failure{
					Confidence: 1,
					Failure:    fmt.Sprintf("maximum number of statements per function exceeded; max %d but got %d", r.maxStmt, stmtCount),
					Node:       node,
				})
			}
		}
		if r.maxLines > 0 {
			lineCount := file.ToPosition(body.End()).Line - file.ToPosition(body.Pos()).Line - 1
			if lineCount > r.maxLines {
				failures = append(failures, lint.Failure{
					Confidence: 1,
					Failure:    fmt.Sprintf("maximum number of lines per function exceeded; max %d but got %d", r.maxLines, lineCount),
					Node:       node,
				})
			}
		}
		return false
	}), file.AST)
	return failures
}

func countStmts(b []ast.Stmt) int {
	count := 0
	for _, s := range b {
		switch stmt := s.(type) {
		case *ast.BlockStmt:
			count += countStmts(stmt.List)
		case *ast.IfStmt:
			count += 1 + countStmts(stmt.Body.List)
			if stmt.Else != nil {
				if elseBody, ok := stmt.Else.(*ast.BlockStmt); ok {
					count += countStmts(elseBody.List)
				}
			}
		case *ast.ForStmt:
			count += 1 + countStmts(stmt.Body.List)
		case *ast.RangeStmt:
			count += 1 + countStmts(stmt.Body.List)
		case *ast.SwitchStmt:
			count += 1 + countStmts(stmt.Body.List)
		case *ast.TypeSwitchStmt:
			count += 1 + countStmts(stmt.Body.List)
		case *ast.SelectStmt:
			count += 1 + countStmts(stmt.Body.List)
		case *ast.CaseClause:
			count += countStmts(stmt.Body)
		case *ast.CommClause:
			count += countStmts(stmt.Body)
		default:
			count++
		}
	}
	return count
}

// MaxControlNestingRule sets restriction for maximum nesting of control structures.
type MaxControlNestingRule struct{ max int64 }

func init() { register(&MaxControlNestingRule{}, false) }

// Name returns the rule name.
func (*MaxControlNestingRule) Name() string { return "max-control-nesting" }

// Configure validates the rule configuration.
func (r *MaxControlNestingRule) Configure(arguments lint.Arguments) error {
	if len(arguments) < 1 {
		r.max = 5
		return nil
	}
	maxNesting, ok := arguments[0].(int64)
	if !ok {
		return errors.New(`invalid value passed as argument number to the "max-control-nesting" rule`)
	}
	r.max = maxNesting
	return nil
}

type lintMaxControlNesting struct {
	max             int64
	onFailure       func(lint.Failure)
	nestingLevelAcc int64
	lastCtrlStmt    ast.Node
}

func (w *lintMaxControlNesting) Visit(n ast.Node) ast.Visitor {
	if w.nestingLevelAcc > w.max {
		w.onFailure(lint.Failure{
			Failure:    fmt.Sprintf("control flow nesting exceeds %d", w.max),
			Confidence: 1,
			Node:       w.lastCtrlStmt,
			Category:   lint.FailureCategoryComplexity,
		})
		return nil
	}
	switch v := n.(type) {
	case *ast.IfStmt:
		w.lastCtrlStmt = v
		w.walkControlledBlock(v.Body)
		if v.Else != nil {
			w.walkControlledBlock(v.Else)
		}
		return nil
	case *ast.ForStmt:
		w.lastCtrlStmt = v
		w.walkControlledBlock(v.Body)
		return nil
	case *ast.CaseClause:
		w.lastCtrlStmt = v
		for _, s := range v.Body {
			w.walkControlledBlock(s)
		}
		return nil
	case *ast.CommClause:
		w.lastCtrlStmt = v
		for _, s := range v.Body {
			w.walkControlledBlock(s)
		}
		return nil
	case *ast.FuncLit:
		nw := &lintMaxControlNesting{onFailure: w.onFailure, max: w.max}
		ast.Walk(nw, v.Body)
		return nil
	case *ast.RangeStmt:
		w.lastCtrlStmt = v
		w.walkControlledBlock(v.Body)
		return nil
	}
	return w
}

func (w *lintMaxControlNesting) walkControlledBlock(b ast.Node) {
	old := w.nestingLevelAcc
	w.nestingLevelAcc++
	ast.Walk(w, b)
	w.nestingLevelAcc = old
}

// Apply applies the rule to given file.
func (r *MaxControlNestingRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	w := &lintMaxControlNesting{max: r.max, onFailure: func(f lint.Failure) { failures = append(failures, f) }}
	ast.Walk(w, file.AST)
	return failures
}

