func init() { register(&MaxPublicStructsRule{}, false) }

// Name returns the rule name.
func (*MaxPublicStructsRule) Name() string { return "max-public-structs" }

// Configure validates the rule configuration.
func (r *MaxPublicStructsRule) Configure(arguments lint.Arguments) error {
	if len(arguments) < 1 {
		r.max = 5
		return nil
	}
	maxStructs, ok := arguments[0].(int64)
	if !ok {
		return errors.New(`invalid value passed as argument number to the "max-public-structs" rule`)
	}
	r.max = maxStructs
	return nil
}

// Apply applies the rule to given file.
func (r *MaxPublicStructsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	if file.IsTest() {
		return failures
	}
	var current int64
	ast.Inspect(file.AST, func(n ast.Node) bool {
		if v, ok := n.(*ast.TypeSpec); ok {
			if _, ok := v.Type.(*ast.StructType); !ok {
				return true
			}
			name := v.Name.Name
			first := string(name[0])
			if strings.ToUpper(first) == first {
				current++
			}
		}
		return true
	})
	if current > r.max {
		failures = append(failures, lint.Failure{
			Failure:    fmt.Sprintf("you have exceeded the maximum number (%d) of public struct declarations", r.max),
			Confidence: 1,
			Node:       file.AST,
			Category:   lint.FailureCategoryStyle,
		})
	}
	return failures
