// FileLengthLimitRule lints the number of lines in a file.
type FileLengthLimitRule struct {
	max            int
	skipComments   bool
	skipBlankLines bool
}

func init() { register(&FileLengthLimitRule{}, false) }

// Name returns the rule name.
func (*FileLengthLimitRule) Name() string { return "file-length-limit" }

// Configure validates the rule configuration.
func (r *FileLengthLimitRule) Configure(arguments lint.Arguments) error {
	r.max, r.skipComments, r.skipBlankLines = 0, false, false
	if len(arguments) < 1 {
		return nil
	}
	argKV, ok := arguments[0].(map[string]any)
	if !ok {
		return fmt.Errorf(`invalid argument to the "file-length-limit" rule. Expecting a k,v map, got %T`, arguments[0])
	}
	for k, v := range argKV {
		switch {
		case isRuleOption(k, "max"):
			maxLines, ok := v.(int64)
			if !ok || maxLines < 0 {
				return fmt.Errorf(`invalid configuration value for max lines in "file-length-limit" rule; need positive int64 but got %T`, arguments[0])
			}
			r.max = int(maxLines)
		case isRuleOption(k, "skipComments"):
			skipComments, ok := v.(bool)
			if !ok {
				return fmt.Errorf(`invalid configuration value for skip comments in "file-length-limit" rule; need bool but got %T`, v)
			}
			r.skipComments = skipComments
		case isRuleOption(k, "skipBlankLines"):
			skipBlankLines, ok := v.(bool)
			if !ok {
				return fmt.Errorf(`invalid configuration value for skip blank lines in "file-length-limit" rule; need bool but got %T`, v)
			}
			r.skipBlankLines = skipBlankLines
		}
	}
	return nil
}

// Apply applies the rule to given file.
func (r *FileLengthLimitRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if r.max <= 0 {
		return nil
	}
	all := 0
	blank := 0
	scanner := bufio.NewScanner(bytes.NewReader(file.Content()))
	for scanner.Scan() {
		all++
		if len(bytes.TrimSpace(scanner.Bytes())) == 0 {
			blank++
		}
	}
	lines := all
	if r.skipComments {
		lines -= countCommentLines(file.AST.Comments)
	}
	if r.skipBlankLines {
		lines -= blank
	}
	if lines <= r.max {
		return nil
	}
	return []lint.Failure{{
		Category:   lint.FailureCategoryCodeStyle,
		Confidence: 1,
		Position: lint.FailurePosition{
			Start: token.Position{Filename: file.Name, Line: all},
		},
		Failure: fmt.Sprintf("file length is %d lines, which exceeds the limit of %d", lines, r.max),
	}}
}

func countCommentLines(comments []*ast.CommentGroup) int {
	count := 0
	for _, cg := range comments {
		for _, comment := range cg.List {
			if len(comment.Text) < 2 {
				continue
			}
			switch comment.Text[1] {
			case '/':
				count++
			case '*':
				count += strings.Count(comment.Text, "\n") + 1
			}
		}
	}
	return count
}

// BannedCharsRule checks if a file contains banned characters.
type BannedCharsRule struct{ bannedCharList []string }

func init() { register(&BannedCharsRule{}, false) }

// Name returns the rule name.
func (*BannedCharsRule) Name() string { return "banned-characters" }

// Configure validates the rule configuration.
func (r *BannedCharsRule) Configure(arguments lint.Arguments) error {
	r.bannedCharList = nil
	if len(arguments) > 0 {
		var bannedChars []string
		for _, char := range arguments {
			charStr, ok := char.(string)
			if !ok {
				return fmt.Errorf("invalid argument for the %s rule: expecting a string, got %T", r.Name(), char)
			}
			bannedChars = append(bannedChars, charStr)
		}
		r.bannedCharList = bannedChars
	}
	return nil
}

// Apply applies the rule to given file.
func (r *BannedCharsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Inspect(file.AST, func(node ast.Node) bool {
		n, ok := node.(*ast.Ident)
		if !ok {
			return true
		}
		for _, c := range r.bannedCharList {
			if strings.Contains(n.Name, c) {
				failures = append(failures, lint.Failure{
					Confidence: 1,
					Failure:    fmt.Sprintf("banned character found: %s", c),
					RuleName:   "banned-characters",
					Node:       n,
				})
			}
		}
		return true
	})
	return failures
}

var (
	multiRegexp  = regexp.MustCompile(`^/\*`)
	singleRegexp = regexp.MustCompile("^//")
)

// FileHeaderRule lints the header that each file should have.
type FileHeaderRule struct{ header string }

func init() { register(&FileHeaderRule{}, false) }

// Name returns the rule name.
func (*FileHeaderRule) Name() string { return "file-header" }

// Configure validates the rule configuration.
func (r *FileHeaderRule) Configure(arguments lint.Arguments) error {
	r.header = ""
	if len(arguments) < 1 {
		return nil
	}
	var ok bool
	r.header, ok = arguments[0].(string)
	if !ok {
		return fmt.Errorf(`invalid argument for "file-header" rule: argument should be a string, got %T`, arguments[0])
	}
	return nil
}

// Apply applies the rule to given file.
func (r *FileHeaderRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if r.header == "" {
		return nil
	}
	failure := []lint.Failure{{
		Node:       file.AST,
		Confidence: 1,
		Failure:    "the file doesn't have an appropriate header",
	}}
	if len(file.AST.Comments) == 0 {
		return failure
	}
	g := file.AST.Comments[0]
	if g == nil {
		return failure
	}
	comment := ""
	for _, c := range g.List {
		text := c.Text
		if multiRegexp.MatchString(text) {
			text = text[2 : len(text)-2]
		} else if singleRegexp.MatchString(text) {
			text = text[2:]
		}
		comment += text
	}
	regex, err := regexp.Compile(r.header)
	if err != nil {
		return []lint.Failure{lint.NewInternalFailure(err.Error())}
	}
	if !regex.MatchString(comment) {
		return failure
	}
	return nil
}

// CommentsDensityRule enforces a minimum comment / code relation.
type CommentsDensityRule struct{ minimumCommentsDensity int64 }

func init() { register(&CommentsDensityRule{}, false) }

// Name returns the rule name.
func (*CommentsDensityRule) Name() string { return "comments-density" }

// Configure validates the rule configuration.
func (r *CommentsDensityRule) Configure(arguments lint.Arguments) error {
	if len(arguments) < 1 {
		r.minimumCommentsDensity = 0
		return nil
	}
	var ok bool
	r.minimumCommentsDensity, ok = arguments[0].(int64)
	if !ok {
		return fmt.Errorf("invalid argument for %q rule: argument should be an int, got %T", r.Name(), arguments[0])
	}
	return nil
}

// Apply applies the rule to given file.
func (r *CommentsDensityRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	commentsLines := countDocLines(file.AST.Comments)
	statementsCount := countStatements(file.AST)
	density := (float32(commentsLines) / float32(statementsCount+commentsLines)) * 100
	if density < float32(r.minimumCommentsDensity) {
		return []lint.Failure{{
			Node:       file.AST,
			Confidence: 1,
			Failure: fmt.Sprintf("the file has a comment density of %2.f%% (%d comment lines for %d code lines) but expected a minimum of %d%%",
				density, commentsLines, statementsCount, r.minimumCommentsDensity),
		}}
	}
	return nil
}

func countStatements(node ast.Node) int {
	counter := 0
	ast.Inspect(node, func(n ast.Node) bool {
		switch n.(type) {
		case *ast.ExprStmt, *ast.AssignStmt, *ast.ReturnStmt, *ast.GoStmt, *ast.DeferStmt,
			*ast.BranchStmt, *ast.IfStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt,
			*ast.SelectStmt, *ast.ForStmt, *ast.RangeStmt, *ast.CaseClause, *ast.CommClause,
			*ast.DeclStmt, *ast.FuncDecl:
			counter++
		}
		return true
	})
	return counter
}

func countDocLines(comments []*ast.CommentGroup) int {
	acc := 0
	for _, c := range comments {
		lines := strings.Split(c.Text(), "\n")
		acc += len(lines) - 1
	}
	return acc
}

// NestedStructs lints nested structs.
type NestedStructs struct{}

func init() { register(&NestedStructs{}, false) }

// Name returns the rule name.
func (*NestedStructs) Name() string { return "nested-structs" }

// Apply applies the rule to given file.
func (*NestedStructs) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	fail := func(n ast.Node) {
		failures = append(failures, lint.Failure{
			Failure:    "no nested structs are allowed",
			Category:   lint.FailureCategoryStyle,
			Node:       n,
			Confidence: 1,
		})
	}
	var inner walker
	inner = func(n ast.Node) bool {
		switch s := n.(type) {
		case *ast.StructType:
			fail(s)
			return false
		case *ast.ArrayType:
			if _, ok := s.Elt.(*ast.StructType); ok {
				fail(s)
			}
			return false
		case *ast.ChanType:
			return false
		case *ast.MapType:
			return false
		}
		return true
	}
	ast.Walk(walker(func(n ast.Node) bool {
		if v, ok := n.(*ast.StructType); ok {
			ast.Walk(inner, v.Fields)
		}
		return true
	}), file.AST)
	return failures
}
