// ArgumentsLimitRule lints the number of arguments a function can receive.
type ArgumentsLimitRule struct{ max int }

func init() { register(&ArgumentsLimitRule{}, false) }

// Name returns the rule name.
func (*ArgumentsLimitRule) Name() string { return "argument-limit" }

// Configure validates the rule configuration.
func (r *ArgumentsLimitRule) Configure(arguments lint.Arguments) error {
	if len(arguments) < 1 {
		r.max = 8
		return nil
	}
	maxArguments, ok := arguments[0].(int64)
	if !ok {
		return errors.New(`invalid value passed as argument number to the "argument-limit" rule`)
	}
	r.max = int(maxArguments)
	return nil
}

// Apply applies the rule to given file.
func (r *ArgumentsLimitRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Walk(walker(func(node ast.Node) bool {
		var funcType *ast.FuncType
		switch n := node.(type) {
		case *ast.FuncDecl:
			funcType = n.Type
		case *ast.FuncLit:
			funcType = n.Type
		default:
			return true
		}
		num := 0
		for _, l := range funcType.Params.List {
			num += len(l.Names)
		}
		if num > r.max {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Failure:    fmt.Sprintf("maximum number of arguments per function exceeded; max %d but got %d", r.max, num),
				Node:       funcType,
			})
		}
		return true
	}), file.AST)
	return failures
}

