// LineLengthLimitRule lints number of characters in a line.
type LineLengthLimitRule struct{ max int }

func init() { register(&LineLengthLimitRule{}, false) }

// Name returns the rule name.
func (*LineLengthLimitRule) Name() string { return "line-length-limit" }

// Configure validates the rule configuration.
func (r *LineLengthLimitRule) Configure(arguments lint.Arguments) error {
	if len(arguments) < 1 {
		r.max = 80
		return nil
	}
	maxLength, ok := arguments[0].(int64)
	if !ok || maxLength < 0 {
		return errors.New(`invalid value passed as argument number to the "line-length-limit" rule`)
	}
	r.max = int(maxLength)
	return nil
}

// Apply applies the rule to given file.
func (r *LineLengthLimitRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	f := bytes.NewReader(file.Content())
	l := 1
	s := bufio.NewScanner(f)
	for s.Scan() {
		t := s.Text()
		t = strings.ReplaceAll(t, "\t", " ")
		c := utf8.RuneCountInString(t)
		if c > r.max {
			failures = append(failures, lint.Failure{
				Category: lint.FailureCategoryCodeStyle,
				Position: lint.FailurePosition{
					Start: token.Position{Filename: file.Name, Line: l, Column: 0},
					End:   token.Position{Filename: file.Name, Line: l, Column: c},
				},
				Confidence: 1,
				Failure:    fmt.Sprintf("line is %d characters, out of limit %d", c, r.max),
			})
		}
		l++
	}
	return failures
}

func funcName(fn *ast.FuncDecl) string {
	if fn.Recv != nil {
		if fn.Recv.NumFields() > 0 {
			typ := fn.Recv.List[0].Type
			return fmt.Sprintf("(%s).%s", recvString(typ), fn.Name)
		}
	}
	return fn.Name.Name
}

func recvString(recv ast.Expr) string {
	switch t := recv.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.StarExpr:
		return "*" + recvString(t.X)
	}
	return "BADRECV"
}

// CyclomaticRule sets restriction for maximum cyclomatic complexity.
type CyclomaticRule struct{ maxComplexity int }

func init() { register(&CyclomaticRule{}, false) }

// Name returns the rule name.
func (*CyclomaticRule) Name() string { return "cyclomatic" }

// Configure validates the rule configuration.
func (r *CyclomaticRule) Configure(arguments lint.Arguments) error {
	if len(arguments) < 1 {
		r.maxComplexity = 10
		return nil
	}
	complexity, ok := arguments[0].(int64)
	if !ok {
		return fmt.Errorf("invalid argument for cyclomatic complexity; expected int but got %T", arguments[0])
	}
	r.maxComplexity = int(complexity)
	return nil
}

// Apply applies the rule to given file.
func (r *CyclomaticRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	for _, decl := range file.AST.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		c := 0
		ast.Inspect(fn, func(n ast.Node) bool {
			switch n := n.(type) {
			case *ast.FuncDecl, *ast.IfStmt, *ast.ForStmt, *ast.RangeStmt, *ast.CaseClause, *ast.CommClause:
				c++
			case *ast.BinaryExpr:
				if n.Op == token.LAND || n.Op == token.LOR {
					c++
				}
			}
			return true
		})
		if c > r.maxComplexity {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Category:   lint.FailureCategoryMaintenance,
				Failure:    fmt.Sprintf("function %s has cyclomatic complexity %d (> max enabled %d)", funcName(fn), c, r.maxComplexity),
				Node:       fn,
			})
		}
	}
	return failures
}

// CognitiveComplexityRule sets restriction for maximum cognitive complexity.
type CognitiveComplexityRule struct{ maxComplexity int }

func init() { register(&CognitiveComplexityRule{}, false) }

// Name returns the rule name.
func (*CognitiveComplexityRule) Name() string { return "cognitive-complexity" }

// Configure validates the rule configuration.
func (r *CognitiveComplexityRule) Configure(arguments lint.Arguments) error {
	if len(arguments) < 1 {
		r.maxComplexity = 7
		return nil
	}
	complexity, ok := arguments[0].(int64)
	if !ok {
		return fmt.Errorf("invalid argument type for cognitive-complexity, expected int64, got %T", arguments[0])
	}
	r.maxComplexity = int(complexity)
	return nil
}

// Apply applies the rule to given file.
func (r *CognitiveComplexityRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	for _, decl := range file.AST.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			continue
		}
		v := cognitiveComplexityVisitor{name: fn.Name}
		c := v.subTreeComplexity(fn.Body)
		if c > r.maxComplexity {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Category:   lint.FailureCategoryMaintenance,
				Failure:    fmt.Sprintf("function %s has cognitive complexity %d (> max enabled %d)", funcName(fn), c, r.maxComplexity),
				Node:       fn,
			})
		}
	}
	return failures
}

type cognitiveComplexityVisitor struct {
	name         *ast.Ident
	complexity   int
	nestingLevel int
}

func (v cognitiveComplexityVisitor) subTreeComplexity(n ast.Node) int {
	ast.Walk(&v, n)
	return v.complexity
}

func (v *cognitiveComplexityVisitor) Visit(n ast.Node) ast.Visitor {
	switch n := n.(type) {
	case *ast.IfStmt:
		v.walk(1, n.Cond, n.Body, n.Else)
		return nil
	case *ast.ForStmt:
		v.walk(1, n.Cond, n.Body)
		return nil
	case *ast.RangeStmt:
		v.walk(1, n.Body)
		return nil
	case *ast.SelectStmt:
		v.walk(1, n.Body)
		return nil
	case *ast.SwitchStmt:
		v.walk(1, n.Body)
		return nil
	case *ast.TypeSwitchStmt:
		v.walk(1, n.Body)
		return nil
	case *ast.FuncLit:
		v.walk(0, n.Body)
		return nil
	case *ast.BinaryExpr:
		v.complexity += binExpComplexity(n)
		return nil
	case *ast.BranchStmt:
		if n.Label != nil {
			v.complexity++
		}
	case *ast.CallExpr:
		if ident, ok := n.Fun.(*ast.Ident); ok {
			if ident.Obj == v.name.Obj && ident.Name == v.name.Name {
				v.complexity++
				return nil
			}
		}
	}
	return v
}

func (v *cognitiveComplexityVisitor) walk(complexityIncrement int, targets ...ast.Node) {
	v.complexity += complexityIncrement + v.nestingLevel
	nesting := v.nestingLevel
	v.nestingLevel++
	for _, t := range targets {
		if t == nil || isNilNode(t) {
			continue
		}
		ast.Walk(v, t)
	}
	v.nestingLevel = nesting
}

func isNilNode(n ast.Node) bool {
	switch t := n.(type) {
	case ast.Expr:
		return t == nil || fmt.Sprintf("%p", t) == "0x0"
	case ast.Stmt:
		return t == nil || fmt.Sprintf("%p", t) == "0x0"
	}
	return false
}

func binExpComplexity(n *ast.BinaryExpr) int {
	calculator := binExprComplexityCalculator{opsStack: []token.Token{}}
	astutil.Apply(n, calculator.pre, calculator.post)
	return calculator.complexity
}

type binExprComplexityCalculator struct {
	complexity    int
	opsStack      []token.Token
	subexpStarted bool
}

func (becc *binExprComplexityCalculator) pre(c *astutil.Cursor) bool {
	switch n := c.Node().(type) {
	case *ast.BinaryExpr:
		isBoolOp := n.Op == token.LAND || n.Op == token.LOR
		if !isBoolOp {
			break
		}
		ops := len(becc.opsStack)
		if ops == 0 || becc.subexpStarted || n.Op != becc.opsStack[ops-1] {
			becc.complexity++
			becc.subexpStarted = false
		}
		becc.opsStack = append(becc.opsStack, n.Op)
	case *ast.ParenExpr:
		becc.subexpStarted = true
	}
	return true
}

func (becc *binExprComplexityCalculator) post(c *astutil.Cursor) bool {
	switch n := c.Node().(type) {
	case *ast.BinaryExpr:
		isBoolOp := n.Op == token.LAND || n.Op == token.LOR
		if !isBoolOp {
			break
		}
		ops := len(becc.opsStack)
		if ops > 0 {
			becc.opsStack = becc.opsStack[:ops-1]
		}
	case *ast.ParenExpr:
		becc.subexpStarted = false
	}
	return true
}

// FunctionLength lint.
type FunctionLength struct {
	maxStmt  int
	maxLines int
}

func init() { register(&FunctionLength{}, false) }

// Name returns the rule name.
func (*FunctionLength) Name() string { return "function-length" }

// Configure validates the rule configuration.
func (r *FunctionLength) Configure(arguments lint.Arguments) error {
	if len(arguments) == 0 {
		r.maxStmt, r.maxLines = 50, 75
		return nil
	}
	const minArguments = 2
	if len(arguments) != minArguments {
		return fmt.Errorf(`invalid configuration for "function-length" rule, expected %d arguments but got %d`, minArguments, len(arguments))
	}
	maxStmt, ok := arguments[0].(int64)
	if !ok {
		return fmt.Errorf(`invalid configuration value for max statements in "function-length" rule; need int64 but got %T`, arguments[0])
	}
	if maxStmt < 0 {
		return fmt.Errorf(`the configuration value for max statements in "function-length" rule cannot be negative, got %d`, maxStmt)
	}
	maxLines, ok := arguments[1].(int64)
	if !ok {
		return fmt.Errorf(`invalid configuration value for max lines in "function-length" rule; need int64 but got %T`, arguments[1])
	}
	if maxLines < 0 {
		return fmt.Errorf(`the configuration value for max statements in "function-length" rule cannot be negative, got %d`, maxLines)
	}
	r.maxStmt, r.maxLines = int(maxStmt), int(maxLines)
	return nil
}

// Apply applies the rule to given file.
func (r *FunctionLength) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Walk(walker(func(n ast.Node) bool {
		node, ok := n.(*ast.FuncDecl)
		if !ok {
			return true
		}
		body := node.Body
		if body == nil || len(node.Body.List) == 0 {
			return false
		}
		if r.maxStmt > 0 {
			stmtCount := countStmts(node.Body.List)
			if stmtCount > r.maxStmt {
				failures = append(failures, lint.Failure{
					Confidence: 1,
					Failure:    fmt.Sprintf("maximum number of statements per function exceeded; max %d but got %d", r.maxStmt, stmtCount),
					Node:       node,
				})
			}
		}
		if r.maxLines > 0 {
			lineCount := file.ToPosition(body.End()).Line - file.ToPosition(body.Pos()).Line - 1
			if lineCount > r.maxLines {
				failures = append(failures, lint.Failure{
					Confidence: 1,
					Failure:    fmt.Sprintf("maximum number of lines per function exceeded; max %d but got %d", r.maxLines, lineCount),
					Node:       node,
				})
			}
		}
		return false
	}), file.AST)
	return failures
}

func countStmts(b []ast.Stmt) int {
	count := 0
	for _, s := range b {
		switch stmt := s.(type) {
		case *ast.BlockStmt:
			count += countStmts(stmt.List)
		case *ast.IfStmt:
			count += 1 + countStmts(stmt.Body.List)
			if stmt.Else != nil {
				if elseBody, ok := stmt.Else.(*ast.BlockStmt); ok {
					count += countStmts(elseBody.List)
				}
			}
		case *ast.ForStmt:
			count += 1 + countStmts(stmt.Body.List)
		case *ast.RangeStmt:
			count += 1 + countStmts(stmt.Body.List)
		case *ast.SwitchStmt:
			count += 1 + countStmts(stmt.Body.List)
		case *ast.TypeSwitchStmt:
			count += 1 + countStmts(stmt.Body.List)
		case *ast.SelectStmt:
			count += 1 + countStmts(stmt.Body.List)
		case *ast.CaseClause:
			count += countStmts(stmt.Body)
		case *ast.CommClause:
			count += countStmts(stmt.Body)
		default:
			count++
		}
	}
	return count
}

// MaxControlNestingRule sets restriction for maximum nesting of control structures.
type MaxControlNestingRule struct{ max int64 }

func init() { register(&MaxControlNestingRule{}, false) }

// Name returns the rule name.
func (*MaxControlNestingRule) Name() string { return "max-control-nesting" }

// Configure validates the rule configuration.
func (r *MaxControlNestingRule) Configure(arguments lint.Arguments) error {
	if len(arguments) < 1 {
		r.max = 5
		return nil
	}
	maxNesting, ok := arguments[0].(int64)
	if !ok {
		return errors.New(`invalid value passed as argument number to the "max-control-nesting" rule`)
	}
	r.max = maxNesting
	return nil
}

type lintMaxControlNesting struct {
	max             int64
	onFailure       func(lint.Failure)
	nestingLevelAcc int64
	lastCtrlStmt    ast.Node
}

func (w *lintMaxControlNesting) Visit(n ast.Node) ast.Visitor {
	if w.nestingLevelAcc > w.max {
		w.onFailure(lint.Failure{
			Failure:    fmt.Sprintf("control flow nesting exceeds %d", w.max),
			Confidence: 1,
			Node:       w.lastCtrlStmt,
			Category:   lint.FailureCategoryComplexity,
		})
		return nil
	}
	switch v := n.(type) {
	case *ast.IfStmt:
		w.lastCtrlStmt = v
		w.walkControlledBlock(v.Body)
		if v.Else != nil {
			w.walkControlledBlock(v.Else)
		}
		return nil
	case *ast.ForStmt:
		w.lastCtrlStmt = v
		w.walkControlledBlock(v.Body)
		return nil
	case *ast.CaseClause:
		w.lastCtrlStmt = v
		for _, s := range v.Body {
			w.walkControlledBlock(s)
		}
		return nil
	case *ast.CommClause:
		w.lastCtrlStmt = v
		for _, s := range v.Body {
			w.walkControlledBlock(s)
		}
		return nil
	case *ast.FuncLit:
		nw := &lintMaxControlNesting{onFailure: w.onFailure, max: w.max}
		ast.Walk(nw, v.Body)
		return nil
	case *ast.RangeStmt:
		w.lastCtrlStmt = v
		w.walkControlledBlock(v.Body)
		return nil
	}
	return w
}

func (w *lintMaxControlNesting) walkControlledBlock(b ast.Node) {
	old := w.nestingLevelAcc
	w.nestingLevelAcc++
	ast.Walk(w, b)
	w.nestingLevelAcc = old
}

// Apply applies the rule to given file.
func (r *MaxControlNestingRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	w := &lintMaxControlNesting{max: r.max, onFailure: func(f lint.Failure) { failures = append(failures, f) }}
	ast.Walk(w, file.AST)
	return failures
}

// MaxPublicStructsRule lints the number of public structs in a file.
type MaxPublicStructsRule struct{ max int64 }

func init() { register(&MaxPublicStructsRule{}, false) }

// Name returns the rule name.
func (*MaxPublicStructsRule) Name() string { return "max-public-structs" }

// Configure validates the rule configuration.
func (r *MaxPublicStructsRule) Configure(arguments lint.Arguments) error {
	if len(arguments) < 1 {
		r.max = 5
		return nil
	}
	maxStructs, ok := arguments[0].(int64)
	if !ok {
		return errors.New(`invalid value passed as argument number to the "max-public-structs" rule`)
	}
	r.max = maxStructs
	return nil
}

// Apply applies the rule to given file.
func (r *MaxPublicStructsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	if file.IsTest() {
		return failures
	}
	var current int64
	ast.Inspect(file.AST, func(n ast.Node) bool {
		if v, ok := n.(*ast.TypeSpec); ok {
			if _, ok := v.Type.(*ast.StructType); !ok {
				return true
			}
			name := v.Name.Name
			first := string(name[0])
			if strings.ToUpper(first) == first {
				current++
			}
		}
		return true
	})
	if current > r.max {
		failures = append(failures, lint.Failure{
			Failure:    fmt.Sprintf("you have exceeded the maximum number (%d) of public struct declarations", r.max),
			Confidence: 1,
			Node:       file.AST,
			Category:   lint.FailureCategoryStyle,
		})
	}
	return failures
}

// FileLengthLimitRule lints the number of lines in a file.
type FileLengthLimitRule struct {
	max            int
	skipComments   bool
	skipBlankLines bool
}

func init() { register(&FileLengthLimitRule{}, false) }

// Name returns the rule name.
func (*FileLengthLimitRule) Name() string { return "file-length-limit" }

// Configure validates the rule configuration.
func (r *FileLengthLimitRule) Configure(arguments lint.Arguments) error {
	r.max, r.skipComments, r.skipBlankLines = 0, false, false
	if len(arguments) < 1 {
		return nil
	}
	argKV, ok := arguments[0].(map[string]any)
	if !ok {
		return fmt.Errorf(`invalid argument to the "file-length-limit" rule. Expecting a k,v map, got %T`, arguments[0])
	}
	for k, v := range argKV {
		switch {
		case isRuleOption(k, "max"):
			maxLines, ok := v.(int64)
			if !ok || maxLines < 0 {
				return fmt.Errorf(`invalid configuration value for max lines in "file-length-limit" rule; need positive int64 but got %T`, arguments[0])
			}
			r.max = int(maxLines)
		case isRuleOption(k, "skipComments"):
			skipComments, ok := v.(bool)
			if !ok {
				return fmt.Errorf(`invalid configuration value for skip comments in "file-length-limit" rule; need bool but got %T`, v)
			}
			r.skipComments = skipComments
		case isRuleOption(k, "skipBlankLines"):
			skipBlankLines, ok := v.(bool)
			if !ok {
				return fmt.Errorf(`invalid configuration value for skip blank lines in "file-length-limit" rule; need bool but got %T`, v)
			}
			r.skipBlankLines = skipBlankLines
		}
	}
	return nil
}

// Apply applies the rule to given file.
func (r *FileLengthLimitRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if r.max <= 0 {
		return nil
	}
	all := 0
	blank := 0
	scanner := bufio.NewScanner(bytes.NewReader(file.Content()))
	for scanner.Scan() {
		all++
		if len(bytes.TrimSpace(scanner.Bytes())) == 0 {
			blank++
		}
	}
	lines := all
	if r.skipComments {
		lines -= countCommentLines(file.AST.Comments)
	}
	if r.skipBlankLines {
		lines -= blank
	}
	if lines <= r.max {
		return nil
	}
	return []lint.Failure{{
		Category:   lint.FailureCategoryCodeStyle,
		Confidence: 1,
		Position: lint.FailurePosition{
			Start: token.Position{Filename: file.Name, Line: all},
		},
		Failure: fmt.Sprintf("file length is %d lines, which exceeds the limit of %d", lines, r.max),
	}}
}

func countCommentLines(comments []*ast.CommentGroup) int {
	count := 0
	for _, cg := range comments {
		for _, comment := range cg.List {
			if len(comment.Text) < 2 {
				continue
			}
			switch comment.Text[1] {
			case '/':
				count++
			case '*':
				count += strings.Count(comment.Text, "\n") + 1
			}
		}
	}
	return count
}

// BannedCharsRule checks if a file contains banned characters.
type BannedCharsRule struct{ bannedCharList []string }

func init() { register(&BannedCharsRule{}, false) }

// Name returns the rule name.
func (*BannedCharsRule) Name() string { return "banned-characters" }

// Configure validates the rule configuration.
func (r *BannedCharsRule) Configure(arguments lint.Arguments) error {
	r.bannedCharList = nil
	if len(arguments) > 0 {
		var bannedChars []string
		for _, char := range arguments {
			charStr, ok := char.(string)
			if !ok {
				return fmt.Errorf("invalid argument for the %s rule: expecting a string, got %T", r.Name(), char)
			}
			bannedChars = append(bannedChars, charStr)
		}
		r.bannedCharList = bannedChars
	}
	return nil
}

// Apply applies the rule to given file.
func (r *BannedCharsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Inspect(file.AST, func(node ast.Node) bool {
		n, ok := node.(*ast.Ident)
		if !ok {
			return true
		}
		for _, c := range r.bannedCharList {
			if strings.Contains(n.Name, c) {
				failures = append(failures, lint.Failure{
					Confidence: 1,
					Failure:    fmt.Sprintf("banned character found: %s", c),
					RuleName:   "banned-characters",
					Node:       n,
				})
			}
		}
		return true
	})
	return failures
}

var (
	multiRegexp  = regexp.MustCompile(`^/\*`)
	singleRegexp = regexp.MustCompile("^//")
)

// FileHeaderRule lints the header that each file should have.
type FileHeaderRule struct{ header string }

func init() { register(&FileHeaderRule{}, false) }

// Name returns the rule name.
func (*FileHeaderRule) Name() string { return "file-header" }

// Configure validates the rule configuration.
func (r *FileHeaderRule) Configure(arguments lint.Arguments) error {
	r.header = ""
	if len(arguments) < 1 {
		return nil
	}
	var ok bool
	r.header, ok = arguments[0].(string)
	if !ok {
		return fmt.Errorf(`invalid argument for "file-header" rule: argument should be a string, got %T`, arguments[0])
	}
	return nil
}

// Apply applies the rule to given file.
func (r *FileHeaderRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if r.header == "" {
		return nil
	}
	failure := []lint.Failure{{
		Node:       file.AST,
		Confidence: 1,
		Failure:    "the file doesn't have an appropriate header",
	}}
	if len(file.AST.Comments) == 0 {
		return failure
	}
	g := file.AST.Comments[0]
	if g == nil {
		return failure
	}
	comment := ""
	for _, c := range g.List {
		text := c.Text
		if multiRegexp.MatchString(text) {
			text = text[2 : len(text)-2]
		} else if singleRegexp.MatchString(text) {
			text = text[2:]
		}
		comment += text
	}
	regex, err := regexp.Compile(r.header)
	if err != nil {
		return []lint.Failure{lint.NewInternalFailure(err.Error())}
	}
	if !regex.MatchString(comment) {
		return failure
	}
	return nil
}

// CommentsDensityRule enforces a minimum comment / code relation.
type CommentsDensityRule struct{ minimumCommentsDensity int64 }

func init() { register(&CommentsDensityRule{}, false) }

// Name returns the rule name.
func (*CommentsDensityRule) Name() string { return "comments-density" }

// Configure validates the rule configuration.
func (r *CommentsDensityRule) Configure(arguments lint.Arguments) error {
	if len(arguments) < 1 {
		r.minimumCommentsDensity = 0
		return nil
	}
	var ok bool
	r.minimumCommentsDensity, ok = arguments[0].(int64)
	if !ok {
		return fmt.Errorf("invalid argument for %q rule: argument should be an int, got %T", r.Name(), arguments[0])
	}
	return nil
}

// Apply applies the rule to given file.
func (r *CommentsDensityRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	commentsLines := countDocLines(file.AST.Comments)
	statementsCount := countStatements(file.AST)
	density := (float32(commentsLines) / float32(statementsCount+commentsLines)) * 100
	if density < float32(r.minimumCommentsDensity) {
		return []lint.Failure{{
			Node:       file.AST,
			Confidence: 1,
			Failure: fmt.Sprintf("the file has a comment density of %2.f%% (%d comment lines for %d code lines) but expected a minimum of %d%%",
				density, commentsLines, statementsCount, r.minimumCommentsDensity),
		}}
	}
	return nil
}

func countStatements(node ast.Node) int {
	counter := 0
	ast.Inspect(node, func(n ast.Node) bool {
		switch n.(type) {
		case *ast.ExprStmt, *ast.AssignStmt, *ast.ReturnStmt, *ast.GoStmt, *ast.DeferStmt,
			*ast.BranchStmt, *ast.IfStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt,
			*ast.SelectStmt, *ast.ForStmt, *ast.RangeStmt, *ast.CaseClause, *ast.CommClause,
			*ast.DeclStmt, *ast.FuncDecl:
			counter++
		}
		return true
	})
	return counter
}

func countDocLines(comments []*ast.CommentGroup) int {
	acc := 0
	for _, c := range comments {
		lines := strings.Split(c.Text(), "\n")
		acc += len(lines) - 1
	}
	return acc
}

// NestedStructs lints nested structs.
type NestedStructs struct{}

func init() { register(&NestedStructs{}, false) }

// Name returns the rule name.
func (*NestedStructs) Name() string { return "nested-structs" }

// Apply applies the rule to given file.
func (*NestedStructs) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	fail := func(n ast.Node) {
		failures = append(failures, lint.Failure{
			Failure:    "no nested structs are allowed",
			Category:   lint.FailureCategoryStyle,
			Node:       n,
			Confidence: 1,
		})
	}
	var inner walker
	inner = func(n ast.Node) bool {
		switch s := n.(type) {
		case *ast.StructType:
			fail(s)
			return false
		case *ast.ArrayType:
			if _, ok := s.Elt.(*ast.StructType); ok {
				fail(s)
			}
			return false
		case *ast.ChanType:
			return false
		case *ast.MapType:
			return false
		}
		return true
	}
	ast.Walk(walker(func(n ast.Node) bool {
		if v, ok := n.(*ast.StructType); ok {
			ast.Walk(inner, v.Fields)
		}
		return true
	}), file.AST)
	return failures
}
