const (
	kindFLOAT  = "FLOAT"
	kindINT    = "INT"
	kindSTRING = "STRING"
)

type addConstAllowList map[string]map[string]bool

func newAddConstAllowList() addConstAllowList {
	return map[string]map[string]bool{kindINT: {}, kindFLOAT: {}, kindSTRING: {}}
}

func (wl addConstAllowList) add(kind, list string) {
	for _, e := range strings.Split(list, ",") {
		wl[kind][e] = true
	}
}

// AddConstantRule lints unused params in functions.
type AddConstantRule struct {
	allowList       addConstAllowList
	ignoreFunctions []*regexp.Regexp
	strLitLimit     int
}

func init() { register(&AddConstantRule{}, false) }

// Name returns the rule name.
func (*AddConstantRule) Name() string { return "add-constant" }

// Configure validates the rule configuration.
func (r *AddConstantRule) Configure(arguments lint.Arguments) error {
	r.strLitLimit = 2
	r.allowList = newAddConstAllowList()
	r.ignoreFunctions = nil
	if len(arguments) == 0 {
		return nil
	}
	args, ok := arguments[0].(map[string]any)
	if !ok {
		return fmt.Errorf("invalid argument to the add-constant rule, expecting a k,v map. Got %T", arguments[0])
	}
	for k, v := range args {
		kind := ""
		switch {
		case isRuleOption(k, "allowFloats"):
			kind = kindFLOAT
			fallthrough
		case isRuleOption(k, "allowInts"):
			if kind == "" {
				kind = kindINT
			}
			fallthrough
		case isRuleOption(k, "allowStrs"):
			if kind == "" {
				kind = kindSTRING
			}
			list, ok := v.(string)
			if !ok {
				return fmt.Errorf("invalid argument to the add-constant rule, string expected. Got '%v' (%T)", v, v)
			}
			r.allowList.add(kind, list)
		case isRuleOption(k, "maxLitCount"):
			sl, ok := v.(string)
			if !ok {
				return fmt.Errorf("invalid argument to the add-constant rule, expecting string representation of an integer. Got '%v' (%T)", v, v)
			}
			limit, err := strconv.Atoi(sl)
			if err != nil {
				return fmt.Errorf("invalid argument to the add-constant rule, expecting string representation of an integer. Got '%v'", v)
			}
			r.strLitLimit = limit
		case isRuleOption(k, "ignoreFuncs"):
			excludes, ok := v.(string)
			if !ok {
				return fmt.Errorf("invalid argument to the ignoreFuncs parameter of add-constant rule, string expected. Got '%v' (%T)", v, v)
			}
			for _, exclude := range strings.Split(excludes, ",") {
				exclude = strings.Trim(exclude, " ")
				if exclude == "" {
					return errors.New("invalid argument to the ignoreFuncs parameter of add-constant rule, expected regular expression must not be empty")
				}
				exp, err := regexp.Compile(exclude)
				if err != nil {
					return fmt.Errorf("invalid argument to the ignoreFuncs parameter of add-constant rule: regexp %q does not compile: %w", exclude, err)
				}
				r.ignoreFunctions = append(r.ignoreFunctions, exp)
			}
		}
	}
	return nil
}

type lintAddConstantRule struct {
	onFailure       func(lint.Failure)
	strLits         map[string]int
	strLitLimit     int
	allowList       addConstAllowList
	ignoreFunctions []*regexp.Regexp
	structTags      map[*ast.BasicLit]struct{}
}

// Apply applies the rule to given file.
func (r *AddConstantRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	w := &lintAddConstantRule{
		onFailure:       func(f lint.Failure) { failures = append(failures, f) },
		strLits:         make(map[string]int),
		strLitLimit:     r.strLitLimit,
		allowList:       r.allowList,
		ignoreFunctions: r.ignoreFunctions,
		structTags:      make(map[*ast.BasicLit]struct{}),
	}
	ast.Walk(w, file.AST)
	return failures
}

func (w *lintAddConstantRule) Visit(node ast.Node) ast.Visitor {
	if node == nil {
		return nil
	}
	switch n := node.(type) {
	case *ast.CallExpr:
		w.checkFunc(n)
		return nil
	case *ast.GenDecl:
		return nil
	case *ast.BasicLit:
		if _, ok := w.structTags[n]; !ok {
			w.checkLit(n)
		}
	case *ast.StructType:
		if n.Fields != nil {
			for _, field := range n.Fields.List {
				if field.Tag != nil {
					w.structTags[field.Tag] = struct{}{}
				}
			}
		}
	}
	return w
}

func (w *lintAddConstantRule) checkFunc(expr *ast.CallExpr) {
	fName := addConstGetFuncName(expr)
	for _, arg := range expr.Args {
		switch t := arg.(type) {
		case *ast.CallExpr:
			w.checkFunc(t)
		case *ast.BasicLit:
			if w.isIgnoredFunc(fName) {
				continue
			}
			w.checkLit(t)
		}
	}
}

func addConstGetFuncName(expr *ast.CallExpr) string {
	switch f := expr.Fun.(type) {
	case *ast.SelectorExpr:
		switch prefix := f.X.(type) {
		case *ast.Ident:
			return prefix.Name + "." + f.Sel.Name
		case *ast.CallExpr:
			if f.Sel != nil {
				return "." + f.Sel.Name
			}
		}
	case *ast.Ident:
		return f.Name
	}
	return ""
}

func (w *lintAddConstantRule) checkLit(n *ast.BasicLit) {
	switch kind := n.Kind.String(); kind {
	case kindFLOAT, kindINT:
		w.checkNumLit(kind, n)
	case kindSTRING:
		w.checkStrLit(n)
	}
}

func (w *lintAddConstantRule) isIgnoredFunc(fName string) bool {
	for _, pattern := range w.ignoreFunctions {
		if pattern.MatchString(fName) {
			return true
		}
	}
	return false
}

func (w *lintAddConstantRule) checkStrLit(n *ast.BasicLit) {
	if w.allowList[kindSTRING][n.Value] {
		return
	}
	count := w.strLits[n.Value]
	if count >= 0 {
		w.strLits[n.Value] = count + 1
		if w.strLits[n.Value] > w.strLitLimit {
			w.onFailure(lint.Failure{
				Confidence: 1,
				Node:       n,
				Category:   lint.FailureCategoryStyle,
				Failure:    fmt.Sprintf("string literal %s appears, at least, %d times, create a named constant for it", n.Value, w.strLits[n.Value]),
			})
			w.strLits[n.Value] = -1
		}
	}
}

func (w *lintAddConstantRule) checkNumLit(kind string, n *ast.BasicLit) {
	if w.allowList[kind][n.Value] {
		return
	}
	w.onFailure(lint.Failure{
		Confidence: 1,
		Node:       n,
		Category:   lint.FailureCategoryStyle,
		Failure:    fmt.Sprintf("avoid magic numbers like '%s', create a named constant for it", n.Value),
	})
}

// CommentSpacingsRule check the whether there is a space between the comment symbol(//) and the start of the comment text.
type CommentSpacingsRule struct {
	allowList []string
}

func init() { register(&CommentSpacingsRule{}, false) }

// Name returns the rule name.
func (*CommentSpacingsRule) Name() string { return "comment-spacings" }

// Configure validates the rule configuration.
func (r *CommentSpacingsRule) Configure(arguments lint.Arguments) error {
	r.allowList = []string{}
	for _, arg := range arguments {
		allow, ok := arg.(string)
		if !ok {
			return fmt.Errorf("invalid argument %v for %s; expected string but got %T", arg, r.Name(), arg)
		}
		r.allowList = append(r.allowList, `//`+allow)
	}
	return nil
}

var directiveCommentRE = regexp.MustCompile("^//(line |extern |export |[a-z0-9]+:[a-z0-9])")

func isDirectiveCommentLine(line string) bool {
	return directiveCommentRE.MatchString(line)
}

// Apply applies the rule to given file.
func (r *CommentSpacingsRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	for _, cg := range file.AST.Comments {
		for _, comment := range cg.List {
			commentLine := comment.Text
			if len(commentLine) < 3 {
				continue
			}
			isMultiLineComment := commentLine[1] == '*'
			isOK := commentLine[2] == '\n'
			if isMultiLineComment && isOK {
				continue
			}
			isOK = (commentLine[2] == ' ') || (commentLine[2] == '\t')
			if isOK {
				continue
			}
			if r.isAllowed(commentLine) {
				continue
			}
			failures = append(failures, lint.Failure{
				Node:       comment,
				Confidence: 1,
				Category:   lint.FailureCategoryStyle,
				Failure:    "no space between comment delimiter and comment text",
			})
		}
	}
	return failures
}

func (r *CommentSpacingsRule) isAllowed(line string) bool {
	for _, allow := range r.allowList {
		if strings.HasPrefix(line, allow) {
			return true
		}
	}
	return isDirectiveCommentLine(line)
}

type confusingRefMethod struct {
	fileName string
	id       *ast.Ident
}

type confusingPkgMethods struct {
	methods map[string]map[string]*confusingRefMethod
}

// ConfusingNamingRule lints method names that differ only by capitalization.
type ConfusingNamingRule struct {
	mu   sync.Mutex
	pkgs map[*lint.Package]*confusingPkgMethods
}

func init() { register(&ConfusingNamingRule{}, false) }

// Name returns the rule name.
func (*ConfusingNamingRule) Name() string { return "confusing-naming" }

const defaultStructName = "_"

func getStructName(r *ast.FieldList) string {
	result := defaultStructName
	if r == nil || len(r.List) < 1 {
		return result
	}
	t := r.List[0].Type
	switch v := t.(type) {
	case *ast.StarExpr:
		switch x := v.X.(type) {
		case *ast.IndexExpr:
			if id, ok := x.X.(*ast.Ident); ok {
				return id.Name
			}
			return defaultStructName
		case *ast.Ident:
			return x.Name
		}
		return defaultStructName
	case *ast.IndexExpr:
		if id, ok := v.X.(*ast.Ident); ok {
			return id.Name
		}
		return defaultStructName
	case *ast.Ident:
		return v.Name
	}
	return defaultStructName
}

// Apply applies the rule to given file.
func (r *ConfusingNamingRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	r.mu.Lock()
	if r.pkgs == nil {
		r.pkgs = map[*lint.Package]*confusingPkgMethods{}
	}
	pkgm, ok := r.pkgs[file.Pkg]
	if !ok {
		pkgm = &confusingPkgMethods{methods: map[string]map[string]*confusingRefMethod{}}
		r.pkgs[file.Pkg] = pkgm
	}
	r.mu.Unlock()
	onFailure := func(f lint.Failure) { failures = append(failures, f) }

	checkMethodName := func(holder string, id *ast.Ident) {
		if id.Name == "init" && holder == defaultStructName {
			return
		}
		name := strings.ToUpper(id.Name)
		if pkgm.methods[holder] != nil {
			if refMethod := pkgm.methods[holder][name]; refMethod != nil {
				kind := "method"
				if holder == defaultStructName {
					kind = "function"
				}
				fileName := refMethod.fileName
				if file.Name == refMethod.fileName {
					fileName = "the same source file"
				}
				onFailure(lint.Failure{
					Failure:    fmt.Sprintf("Method '%s' differs only by capitalization to %s '%s' in %s", id.Name, kind, refMethod.id.Name, fileName),
					Confidence: 1,
					Node:       id,
					Category:   lint.FailureCategoryNaming,
				})
				return
			}
		} else {
			pkgm.methods[holder] = make(map[string]*confusingRefMethod, 1)
		}
		pkgm.methods[holder][name] = &confusingRefMethod{fileName: file.Name, id: id}
	}
	checkStructFields := func(fields *ast.FieldList, structName string) {
		bl := make(map[string]bool, len(fields.List))
		for _, f := range fields.List {
			for _, id := range f.Names {
				normName := strings.ToUpper(id.Name)
				if bl[normName] {
					onFailure(lint.Failure{
						Failure:    fmt.Sprintf("Field '%s' differs only by capitalization to other field in the struct type %s", id.Name, structName),
						Confidence: 1,
						Node:       id,
						Category:   lint.FailureCategoryNaming,
					})
				} else {
					bl[normName] = true
				}
			}
		}
	}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.FuncDecl:
			if ast.IsExported(v.Name.Name) || !isCgoExported(v) {
				checkMethodName(getStructName(v.Recv), v.Name)
			}
		case *ast.TypeSpec:
			if s, ok := v.Type.(*ast.StructType); ok {
				checkStructFields(s.Fields, v.Name.Name)
			}
		}
		return true
	})
	return failures
}

// EmptyLinesRule lints empty lines in blocks.
type EmptyLinesRule struct{}

func init() { register(&EmptyLinesRule{}, false) }

// Name returns the rule name.
func (*EmptyLinesRule) Name() string { return "empty-lines" }

// Apply applies the rule to given file.
func (*EmptyLinesRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	cmap := map[int]struct{}{}
	for _, comments := range file.CommentMap() {
		for _, comment := range comments {
			start := file.ToPosition(comment.Pos())
			end := file.ToPosition(comment.End())
			for i := start.Line; i <= end.Line; i++ {
				cmap[i] = struct{}{}
			}
		}
	}
	ast.Inspect(file.AST, func(node ast.Node) bool {
		block, ok := node.(*ast.BlockStmt)
		if !ok || len(block.List) == 0 {
			return true
		}
		blockStart := file.ToPosition(block.Lbrace)
		firstStmt := file.ToPosition(block.List[0].Pos())
		firstBlockLineIsStmt := firstStmt.Line-(blockStart.Line+1) <= 0
		_, firstBlockLineIsComment := cmap[blockStart.Line+1]
		if !firstBlockLineIsStmt && !firstBlockLineIsComment {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Node:       block,
				Category:   lint.FailureCategoryStyle,
				Failure:    "extra empty line at the start of a block",
			})
		}
		blockEnd := file.ToPosition(block.Rbrace)
		lastStmt := file.ToPosition(block.List[len(block.List)-1].End())
		lastBlockLineIsStmt := (blockEnd.Line-1)-lastStmt.Line <= 0
		_, lastBlockLineIsComment := cmap[blockEnd.Line-1]
		if !lastBlockLineIsStmt && !lastBlockLineIsComment {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Node:       block,
				Category:   lint.FailureCategoryStyle,
				Failure:    "extra empty line at the end of a block",
			})
		}
		return true
	})
	return failures
}

// FlagParamRule warns on boolean parameters that create a control coupling.
type FlagParamRule struct{}

func init() { register(&FlagParamRule{}, false) }

// Name returns the rule name.
func (*FlagParamRule) Name() string { return "flag-parameter" }

// Apply applies the rule to given file.
func (*FlagParamRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Walk(walker(func(node ast.Node) bool {
		fd, ok := node.(*ast.FuncDecl)
		if !ok {
			return true
		}
		if fd.Body == nil {
			return false
		}
		for _, p := range fd.Type.Params.List {
			id, ok := p.Type.(*ast.Ident)
			if !ok || id.Name != "bool" {
				continue
			}
			ids := p.Names
			ast.Walk(walker(func(node ast.Node) bool {
				ifStmt, ok := node.(*ast.IfStmt)
				if !ok {
					return true
				}
				uses := pick(ifStmt.Cond, func(n ast.Node) bool {
					ident, ok := n.(*ast.Ident)
					if !ok {
						return false
					}
					for _, id := range ids {
						if ident.Name == id.Name {
							return true
						}
					}
					return false
				})
				if len(uses) < 1 {
					return true
				}
				failures = append(failures, lint.Failure{
					Confidence: 1,
					Node:       fd.Type.Params,
					Category:   lint.FailureCategoryBadPractice,
					Failure:    fmt.Sprintf("parameter '%s' seems to be a control flag, avoid control coupling", uses[0]),
				})
				return false
			}), fd.Body)
		}
		return true
	}), file.AST)
	return failures
}

