}

// Apply applies the rule to given file.
func (*DataRaceRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	isGo122 := file.Pkg.IsAtLeastGoVersion(goVersion122)
	var failures []lint.Failure
	for _, decl := range file.AST.Decls {
		funcDecl, ok := decl.(*ast.FuncDecl)
		if !ok || funcDecl.Body == nil {
			continue
		}
		returnIDs := map[*ast.Object]struct{}{}
		if funcDecl.Type.Results != nil {
			for _, f := range funcDecl.Type.Results.List {
				for _, id := range f.Names {
					returnIDs[id.Obj] = struct{}{}
				}
			}
		}
		fl := &lintFunctionForDataRaces{
			onFailure: func(f lint.Failure) { failures = append(failures, f) },
			returnIDs: returnIDs,
			rangeIDs:  map[*ast.Object]struct{}{},
			go122for:  isGo122,
		}
		ast.Walk(fl, funcDecl.Body)
	}
	return failures
}

