package rule

import (
	"errors"
	"fmt"
	"go/ast"
	"slices"
	"strconv"
	"strings"

	"github.com/revivelint/revive/internal/lint"
)

type structTag struct {
	Key     string
	Name    string
	Options []string
}

var (
	errTagSyntax = errors.New("bad syntax for struct tag")
)

// parseStructTags parses a struct tag in the reflect.StructTag format.
func parseStructTags(tag string) ([]*structTag, error) {
	var tags []*structTag
	for tag != "" {
		i := 0
		for i < len(tag) && tag[i] == ' ' {
			i++
		}
		tag = tag[i:]
		if tag == "" {
			break
		}
		i = 0
		for i < len(tag) && tag[i] > ' ' && tag[i] != ':' && tag[i] != '"' && tag[i] != 0x7f {
			i++
		}
		if i == 0 {
			return nil, errTagSyntax
		}
		if i+1 >= len(tag) || tag[i] != ':' {
			return nil, errTagSyntax
		}
		if tag[i+1] != '"' {
			return nil, errTagSyntax
		}
		key := tag[:i]
		tag = tag[i+1:]
		i = 1
		for i < len(tag) && tag[i] != '"' {
			if tag[i] == '\\' {
				i++
			}
			i++
		}
		if i >= len(tag) {
			return nil, errTagSyntax
		}
		qvalue := tag[:i+1]
		tag = tag[i+1:]
		if tag != "" && tag[0] != ' ' {
			return nil, errTagSyntax
		}
		value, err := strconv.Unquote(qvalue)
		if err != nil {
			return nil, errTagSyntax
		}
		res := strings.Split(value, ",")
		name := res[0]
		options := res[1:]
		if len(options) == 0 {
			options = nil
		}
		tags = append(tags, &structTag{Key: key, Name: name, Options: options})
	}
	return tags, nil
}

type tagKey string

const (
	keyASN1         tagKey = "asn1"
	keyBSON         tagKey = "bson"
	keyCbor         tagKey = "cbor"
	keyCodec        tagKey = "codec"
	keyDatastore    tagKey = "datastore"
	keyDefault      tagKey = "default"
	keyJSON         tagKey = "json"
	keyMapstructure tagKey = "mapstructure"
	keyProperties   tagKey = "properties"
	keyProtobuf     tagKey = "protobuf"
	keyRequired     tagKey = "required"
	keySpanner      tagKey = "spanner"
	keyTOML         tagKey = "toml"
	keyURL          tagKey = "url"
	keyValidate     tagKey = "validate"
	keyXML          tagKey = "xml"
	keyYAML         tagKey = "yaml"
)

const (
	msgDuplicatedOption    = "duplicated option %q"
	msgDuplicatedTagName   = "duplicated tag name %q"
	msgDuplicatedTagNumber = "duplicated tag number %v"
	msgUnknownOption       = "unknown option %q"
	msgTypeMismatch        = "type mismatch between field type and default value type"
)

type tagChecker func(checkCtx *checkContext, tag *structTag, fieldType ast.Expr) (message string, succeeded bool)

var tagCheckers = map[tagKey]tagChecker{
	keyASN1:         checkASN1Tag,
	keyBSON:         checkBSONTag,
	keyCbor:         checkCborTag,
	keyCodec:        checkCodecTag,
	keyDatastore:    checkDatastoreTag,
	keyDefault:      checkDefaultTag,
	keyJSON:         checkJSONTag,
	keyMapstructure: checkMapstructureTag,
	keyProperties:   checkPropertiesTag,
	keyProtobuf:     checkProtobufTag,
	keyRequired:     checkRequiredTag,
	keySpanner:      checkSpannerTag,
	keyTOML:         checkTOMLTag,
	keyURL:          checkURLTag,
	keyValidate:     checkValidateTag,
	keyXML:          checkXMLTag,
	keyYAML:         checkYAMLTag,
}

type checkContext struct {
	userDefined    map[tagKey][]string
	usedTagNbr     map[int]bool
	usedTagName    map[string]bool
	usedCborName   map[string]bool
	isAtLeastGo124 bool
}

func (checkCtx checkContext) isUserDefined(key tagKey, opt string) bool {
	if checkCtx.userDefined == nil {
		return false
	}
	return slices.Contains(checkCtx.userDefined[key], opt)
}

// StructTagRule lints struct tags.
type StructTagRule struct {
	userDefined map[tagKey][]string
}

func init() { register(&StructTagRule{}, false) }

// Name returns the rule name.
func (*StructTagRule) Name() string { return "struct-tag" }

// Configure validates the rule configuration.
func (r *StructTagRule) Configure(arguments lint.Arguments) error {
	r.userDefined = nil
	if len(arguments) == 0 {
		return nil
	}
	r.userDefined = make(map[tagKey][]string, len(arguments))
	for _, arg := range arguments {
		item, ok := arg.(string)
		if !ok {
			return fmt.Errorf("invalid argument to the %s rule. Expecting a string, got %v (of type %T)", r.Name(), arg, arg)
		}
		parts := strings.Split(item, ",")
		if len(parts) < 2 {
			return fmt.Errorf("invalid argument to the %s rule. Expecting a string of the form key[,option]+, got %s", r.Name(), item)
		}
		key := tagKey(strings.TrimSpace(parts[0]))
		for i := 1; i < len(parts); i++ {
			option := strings.TrimSpace(parts[i])
			r.userDefined[key] = append(r.userDefined[key], option)
		}
	}
	return nil
}

// Apply applies the rule to given file.
func (r *StructTagRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	addFailure := func(n ast.Node, msg string) {
		failures = append(failures, lint.Failure{
			Node:       n,
			Failure:    msg,
			Confidence: 1,
		})
	}
	isAtLeastGo124 := file.Pkg.IsAtLeastGoVersion(goVersion124)
	ast.Inspect(file.AST, func(node ast.Node) bool {
		n, ok := node.(*ast.StructType)
		if !ok {
			return true
		}
		if n.Fields == nil || n.Fields.NumFields() < 1 {
			return false
		}
		checkCtx := &checkContext{
			userDefined:    r.userDefined,
			usedTagNbr:     map[int]bool{},
			usedTagName:    map[string]bool{},
			usedCborName:   map[string]bool{},
			isAtLeastGo124: isAtLeastGo124,
		}
		for _, f := range n.Fields.List {
			if f.Tag == nil {
				continue
			}
			if len(f.Names) > 0 && !f.Names[0].IsExported() {
				addFailure(f, "tag on not-exported field "+f.Names[0].Name)
			}
			tags, err := parseStructTags(strings.Trim(f.Tag.Value, "`"))
			if err != nil {
				addFailure(f.Tag, "malformed tag")
				continue
			}
			for _, tag := range tags {
				if msg, ok := checkTagNameIfNeed(checkCtx, tag); !ok {
					addFailure(f.Tag, msg+" in "+tag.Key+" tag")
				}
				checker, ok := tagCheckers[tagKey(tag.Key)]
				if !ok {
					continue
				}
				if msg, ok := checker(checkCtx, tag, f.Type); !ok {
					addFailure(f.Tag, msg+" in "+tag.Key+" tag")
				}
			}
		}
		return true
	})
	return failures
}

func checkTagNameIfNeed(checkCtx *checkContext, tag *structTag) (string, bool) {
	isUnnamedTag := tag.Name == "" || tag.Name == "-"
	if isUnnamedTag {
		return "", true
	}
	switch tagKey(tag.Key) {
	case keyBSON, keyCodec, keyJSON, keyProtobuf, keySpanner, keyXML, keyYAML:
	default:
		return "", true
	}
	tagName := tag.Name
	if tagKey(tag.Key) == keyProtobuf {
		tagName = ""
		for _, option := range tag.Options {
			if n, found := strings.CutPrefix(option, "name="); found {
				tagName = n
				break
			}
		}
	}
	if tagName == "" {
		return "", true
	}
	mapKey := tag.Key + ":" + tagName
	if checkCtx.usedTagName[mapKey] {
		return fmt.Sprintf(msgDuplicatedTagName, tagName), false
	}
	checkCtx.usedTagName[mapKey] = true
	return "", true
}

func checkASN1Tag(checkCtx *checkContext, tag *structTag, fieldType ast.Expr) (string, bool) {
	checkList := append(append([]string{}, tag.Options...), tag.Name)
	for _, opt := range checkList {
		switch opt {
		case "application", "explicit", "generalized", "ia5", "omitempty", "optional", "set", "utf8":
		default:
			if strings.HasPrefix(opt, "tag:") {
				tagNumber := strings.TrimPrefix(opt, "tag:")
				number, err := strconv.Atoi(tagNumber)
				if err != nil {
					return fmt.Sprintf("tag must be a number but is %q", tagNumber), false
				}
				if checkCtx.usedTagNbr[number] {
					return fmt.Sprintf(msgDuplicatedTagNumber, number), false
				}
				checkCtx.usedTagNbr[number] = true
				continue
			}
			if strings.HasPrefix(opt, "default") {
				_, val, _ := strings.Cut(opt, ":")
				if !typeValueMatch(fieldType, val) {
					return msgTypeMismatch, false
				}
				continue
			}
			if checkCtx.isUserDefined(keyASN1, opt) {
				continue
			}
			return fmt.Sprintf(msgUnknownOption, opt), false
		}
	}
	return "", true
}

func checkSimpleOptions(checkCtx *checkContext, key tagKey, tag *structTag, allowed ...string) (string, bool) {
	for _, opt := range tag.Options {
		if slices.Contains(allowed, opt) {
			continue
		}
		if checkCtx.isUserDefined(key, opt) {
			continue
		}
		return fmt.Sprintf(msgUnknownOption, opt), false
	}
	return "", true
}

func checkBSONTag(checkCtx *checkContext, tag *structTag, _ ast.Expr) (string, bool) {
	return checkSimpleOptions(checkCtx, keyBSON, tag, "inline", "minsize", "omitempty")
}

func checkCborTag(checkCtx *checkContext, tag *structTag, _ ast.Expr) (string, bool) {
	for _, opt := range tag.Options {
		switch opt {
		case "omitempty", "omitzero":
		case "toarray":
			if tag.Name != "" {
				return `tag name for option "toarray" should be empty`, false
			}
		case "keyasint":
			if _, err := strconv.Atoi(tag.Name); err != nil {
				return `tag name for option "keyasint" should be an integer`, false
			}
		default:
			if checkCtx.isUserDefined(keyCbor, opt) {
				continue
			}
			return fmt.Sprintf(msgUnknownOption, opt), false
		}
	}
	if tag.Name != "" {
		if checkCtx.usedCborName[tag.Name] {
			return fmt.Sprintf("duplicated tag name %s", tag.Name), false
		}
		checkCtx.usedCborName[tag.Name] = true
	}
	return "", true
}

func checkCodecTag(checkCtx *checkContext, tag *structTag, _ ast.Expr) (string, bool) {
	return checkSimpleOptions(checkCtx, keyCodec, tag, "omitempty", "toarray", "int", "uint", "float")
}

func checkDatastoreTag(checkCtx *checkContext, tag *structTag, _ ast.Expr) (string, bool) {
	return checkSimpleOptions(checkCtx, keyDatastore, tag, "flatten", "noindex", "omitempty")
}

func checkDefaultTag(_ *checkContext, tag *structTag, fieldType ast.Expr) (string, bool) {
	if !typeValueMatch(fieldType, tag.Name) {
		return msgTypeMismatch, false
	}
	return "", true
}

func checkJSONTag(checkCtx *checkContext, tag *structTag, _ ast.Expr) (string, bool) {
	for _, opt := range tag.Options {
		switch opt {
		case "omitempty", "string":
		case "":
			if tag.Name != "-" {
				return "option can not be empty", false
			}
		case "omitzero":
			if checkCtx.isAtLeastGo124 {
				continue
			}
			if checkCtx.isUserDefined(keyJSON, opt) {
				continue
			}
			return `prior Go 1.24, option "omitzero" is unsupported`, false
		default:
			if checkCtx.isUserDefined(keyJSON, opt) {
				continue
			}
			return fmt.Sprintf(msgUnknownOption, opt), false
		}
	}
	return "", true
}

func checkMapstructureTag(checkCtx *checkContext, tag *structTag, _ ast.Expr) (string, bool) {
	return checkSimpleOptions(checkCtx, keyMapstructure, tag, "omitempty", "squash")
}

func checkPropertiesTag(_ *checkContext, tag *structTag, fieldType ast.Expr) (string, bool) {
	if len(tag.Options) == 0 {
		return "", true
	}
	seenOptions := map[string]bool{}
	for _, opt := range tag.Options {
		msg, ok := fmt.Sprintf("unknown or malformed option %q", opt), false
		if key, value, found := strings.Cut(opt, "="); found {
			msg, ok = checkCompoundPropertiesOption(key, value, fieldType, seenOptions)
		}
		if !ok {
			return msg, false
		}
	}
	return "", true
}

func checkCompoundPropertiesOption(key, value string, fieldType ast.Expr, seenOptions map[string]bool) (string, bool) {
	if seenOptions[key] {
		return fmt.Sprintf(msgDuplicatedOption, key), false
	}
	seenOptions[key] = true
	if strings.TrimSpace(value) == "" {
		return fmt.Sprintf("option %q not of the form %s=value", key, key), false
	}
	switch key {
	case "default":
		if !typeValueMatch(fieldType, value) {
			return msgTypeMismatch, false
		}
	case "layout":
		if gofmt(fieldType) != "time.Time" {
			return "layout option is only applicable to fields of type time.Time", false
		}
	}
	return "", true
}

func checkProtobufTag(checkCtx *checkContext, tag *structTag, _ ast.Expr) (string, bool) {
	switch tag.Name {
	case "bytes", "fixed32", "fixed64", "group", "varint", "zigzag32", "zigzag64":
	default:
		return fmt.Sprintf("invalid tag name %q", tag.Name), false
	}
	seenOptions := map[string]bool{}
	for _, opt := range tag.Options {
		if number, err := strconv.Atoi(opt); err == nil {
			if checkCtx.usedTagNbr[number] {
				return fmt.Sprintf(msgDuplicatedTagNumber, number), false
			}
			checkCtx.usedTagNbr[number] = true
			continue
		}
		switch {
		case opt == "opt" || opt == "proto3" || opt == "rep" || opt == "req":
		case strings.Contains(opt, "="):
			o := strings.Split(opt, "=")[0]
			if seenOptions[o] {
				return fmt.Sprintf(msgDuplicatedOption, o), false
			}
			seenOptions[o] = true
			switch o {
			case "name", "json":
			default:
				if !checkCtx.isUserDefined(keyProtobuf, o) {
					return fmt.Sprintf(msgUnknownOption, o), false
				}
			}
		default:
			if checkCtx.isUserDefined(keyProtobuf, opt) {
				continue
			}
			return fmt.Sprintf(msgUnknownOption, opt), false
		}
	}
	if !seenOptions["name"] {
		return `mandatory option "name" not found`, false
	}
	return "", true
}

func checkRequiredTag(_ *checkContext, tag *structTag, _ ast.Expr) (string, bool) {
	switch tag.Name {
	case "true", "false":
		return "", true
	}
	return `required should be "true" or "false"`, false
}

func checkSpannerTag(checkCtx *checkContext, tag *structTag, _ ast.Expr) (string, bool) {
	return checkSimpleOptions(checkCtx, keySpanner, tag)
}

func checkTOMLTag(checkCtx *checkContext, tag *structTag, _ ast.Expr) (string, bool) {
	return checkSimpleOptions(checkCtx, keyTOML, tag, "omitempty")
}

func checkURLTag(checkCtx *checkContext, tag *structTag, _ ast.Expr) (string, bool) {
	delimiter := ""
	for _, opt := range tag.Options {
