func isMapTypeExpr(v ast.Expr) bool {
	switch t := v.(type) {
	case *ast.MapType:
		return true
	case *ast.Ident:
		if t.Obj == nil {
			return false
		}
		typeSpec, ok := t.Obj.Decl.(*ast.TypeSpec)
		if !ok {
			return false
		}
		return isMapTypeExpr(typeSpec.Type)
	}
	return false
}

// EnforceMapStyleRule implements a rule to enforce `make(map[type]type)` over `map[type]type{}`.
type EnforceMapStyleRule struct{ style string }

func init() { register(&EnforceMapStyleRule{}, false) }

// Name returns the rule name.
func (*EnforceMapStyleRule) Name() string { return "enforce-map-style" }

// Configure validates the rule configuration.
func (r *EnforceMapStyleRule) Configure(arguments lint.Arguments) error {
	r.style = "any"
	if len(arguments) < 1 {
		return nil
	}
	s, ok := arguments[0].(string)
	if !ok {
		return fmt.Errorf("invalid argument '%v' for 'enforce-map-style' rule. Expecting string, got %T", arguments[0], arguments[0])
	}
	switch s {
	case "any", "":
		r.style = "any"
	case "make", "literal":
		r.style = s
	default:
		return fmt.Errorf("invalid argument to the enforce-map-style rule: invalid map style: %s (expecting one of [any make literal])", s)
	}
	return nil
}

// Apply applies the rule to given file.
func (r *EnforceMapStyleRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if r.style == "any" {
		return nil
	}
	var failures []lint.Failure
	ast.Inspect(file.AST, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.CompositeLit:
			if r.style != "make" {
				return true
			}
			if !isMapTypeExpr(v.Type) {
				return true
			}
			if len(v.Elts) > 0 {
				return true
			}
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Node:       v,
				Category:   lint.FailureCategoryStyle,
				Failure:    "use make(map[type]type) instead of map[type]type{}",
			})
		case *ast.CallExpr:
			if r.style != "literal" {
				return false
			}
			ident, ok := v.Fun.(*ast.Ident)
			if !ok || ident.Name != "make" {
				return true
			}
			if len(v.Args) != 1 {
				return true
			}
			if !isMapTypeExpr(v.Args[0]) {
				return true
			}
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Node:       v.Args[0],
				Category:   lint.FailureCategoryStyle,
				Failure:    "use map[type]type{} instead of make(map[type]type)",
			})
		}
		return true
	})
	return failures
}

func isSliceTypeExpr(v ast.Expr) bool {
	switch t := v.(type) {
	case *ast.ArrayType:
		return t.Len == nil
	case *ast.Ident:
		if t.Obj == nil {
			return false
		}
		typeSpec, ok := t.Obj.Decl.(*ast.TypeSpec)
		if !ok {
			return false
		}
		return isSliceTypeExpr(typeSpec.Type)
	}
	return false
}

// EnforceSliceStyleRule implements a rule to enforce `make([]type)` over `[]type{}`.
type EnforceSliceStyleRule struct{ style string }

func init() { register(&EnforceSliceStyleRule{}, false) }

// Name returns the rule name.
func (*EnforceSliceStyleRule) Name() string { return "enforce-slice-style" }

// Configure validates the rule configuration.
func (r *EnforceSliceStyleRule) Configure(arguments lint.Arguments) error {
	r.style = "any"
	if len(arguments) < 1 {
		return nil
	}
	s, ok := arguments[0].(string)
	if !ok {
		return fmt.Errorf("invalid argument '%v' for 'enforce-slice-style' rule. Expecting string, got %T", arguments[0], arguments[0])
	}
	switch s {
	case "any", "":
		r.style = "any"
	case "make", "literal", "nil":
		r.style = s
	default:
		return fmt.Errorf("invalid argument to the enforce-slice-style rule: invalid slice style: %s (expecting one of [any make literal nil])", s)
	}
	return nil
}

// Apply applies the rule to given file.
func (r *EnforceSliceStyleRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if r.style == "any" {
		return nil
	}
	var failures []lint.Failure
	ast.Inspect(file.AST, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.CompositeLit:
			switch r.style {
			case "make", "nil":
			default:
				return true
			}
			if !isSliceTypeExpr(v.Type) {
				return true
			}
			if len(v.Elts) > 0 {
				return true
			}
			msg := "use make([]type) instead of []type{} (or declare nil slice)"
			if r.style == "nil" {
				msg = "use nil slice declaration (e.g. var args []type) instead of []type{}"
			}
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Node:       v,
				Category:   lint.FailureCategoryStyle,
				Failure:    msg,
			})
		case *ast.CallExpr:
			switch r.style {
			case "literal", "nil":
			default:
				return false
			}
			ident, ok := v.Fun.(*ast.Ident)
			if !ok || ident.Name != "make" {
				return true
			}
			if len(v.Args) < 2 {
				return true
			}
			if !isSliceTypeExpr(v.Args[0]) {
				return true
			}
			arg, ok := v.Args[1].(*ast.BasicLit)
			if !ok {
				return true
			}
			if arg.Value != "0" {
				return true
			}
			if len(v.Args) > 2 {
				arg, ok := v.Args[2].(*ast.BasicLit)
				if !ok {
					return true
				}
				if arg.Value != "0" {
					return true
				}
			}
			msg := "use []type{} instead of make([]type, 0) (or declare nil slice)"
			if r.style == "nil" {
				msg = "use nil slice declaration (e.g. var args []type) instead of make([]type, 0)"
			}
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Node:       v.Args[0],
				Category:   lint.FailureCategoryStyle,
				Failure:    msg,
			})
		}
		return true
	})
	return failures
}

func repeatedArgTypeStyleFromString(s string) (string, error) {
	switch s {
	case "any", "":
		return "any", nil
	case "short", "full":
		return s, nil
	}
	return "any", fmt.Errorf("invalid repeated arg type style: %s (expecting one of [any short full])", s)
}

// EnforceRepeatedArgTypeStyleRule implements a rule to enforce repeated argument type style.
type EnforceRepeatedArgTypeStyleRule struct {
	funcArgStyle    string
	funcRetValStyle string
}

func init() { register(&EnforceRepeatedArgTypeStyleRule{}, false) }

// Name returns the rule name.
func (*EnforceRepeatedArgTypeStyleRule) Name() string { return "enforce-repeated-arg-type-style" }

// Configure validates the rule configuration.
func (r *EnforceRepeatedArgTypeStyleRule) Configure(arguments lint.Arguments) error {
	r.funcArgStyle = "any"
	r.funcRetValStyle = "any"
	if len(arguments) == 0 {
		return nil
	}
	switch funcArgStyle := arguments[0].(type) {
	case string:
		argstyle, err := repeatedArgTypeStyleFromString(funcArgStyle)
		if err != nil {
			return err
		}
		r.funcArgStyle = argstyle
		r.funcRetValStyle = argstyle
	case map[string]any:
		for k, v := range funcArgStyle {
			switch {
			case isRuleOption(k, "funcArgStyle"):
				val, ok := v.(string)
				if !ok {
					return fmt.Errorf("invalid map value type for 'enforce-repeated-arg-type-style' rule. Expecting string, got %T", v)
				}
				valstyle, err := repeatedArgTypeStyleFromString(val)
				if err != nil {
					return err
				}
				r.funcArgStyle = valstyle
			case isRuleOption(k, "funcRetValStyle"):
				val, ok := v.(string)
				if !ok {
					return fmt.Errorf("invalid map value '%v' for 'enforce-repeated-arg-type-style' rule. Expecting string, got %T", v, v)
				}
				argstyle, err := repeatedArgTypeStyleFromString(val)
				if err != nil {
					return err
				}
				r.funcRetValStyle = argstyle
			default:
				return fmt.Errorf("invalid map key for 'enforce-repeated-arg-type-style' rule. Expecting 'funcArgStyle' or 'funcRetValStyle', got %v", k)
			}
		}
	default:
		return fmt.Errorf("invalid argument '%v' for 'import-alias-naming' rule. Expecting string or map[string]string, got %T", arguments[0], arguments[0])
	}
	return nil
}

func gofmtOrEmpty(e ast.Expr) string {
	if e == nil {
		return ""
	}
	return gofmt(e)
}

// Apply applies the rule to given file.
func (r *EnforceRepeatedArgTypeStyleRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if r.funcArgStyle == "any" && r.funcRetValStyle == "any" {
		return nil
	}
	var failures []lint.Failure
	ast.Inspect(file.AST, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok {
			return true
		}
		switch r.funcArgStyle {
		case "full":
			if fn.Type.Params != nil {
				for _, field := range fn.Type.Params.List {
					if len(field.Names) > 1 {
						failures = append(failures, lint.Failure{Confidence: 1, Node: field, Category: lint.FailureCategoryStyle, Failure: "argument types should not be omitted"})
					}
				}
			}
		case "short":
			if fn.Type.Params != nil {
				var prevType ast.Expr
				for _, field := range fn.Type.Params.List {
					prevTypeStr := gofmtOrEmpty(prevType)
					currentTypeStr := gofmt(field.Type)
					if currentTypeStr == prevTypeStr {
						failures = append(failures, lint.Failure{Confidence: 1, Node: prevType, Category: lint.FailureCategoryStyle, Failure: fmt.Sprintf("repeated argument type %q can be omitted", prevTypeStr)})
					}
					prevType = field.Type
				}
			}
		}
		switch r.funcRetValStyle {
		case "full":
			if fn.Type.Results != nil {
				for _, field := range fn.Type.Results.List {
					if len(field.Names) > 1 {
						failures = append(failures, lint.Failure{Confidence: 1, Node: field, Category: lint.FailureCategoryStyle, Failure: "return types should not be omitted"})
					}
				}
			}
		case "short":
			if fn.Type.Results != nil {
				var prevType ast.Expr
				for _, field := range fn.Type.Results.List {
					prevTypeStr := gofmtOrEmpty(prevType)
					currentTypeStr := gofmt(field.Type)
					if currentTypeStr == prevTypeStr {
						failures = append(failures, lint.Failure{Confidence: 1, Node: prevType, Category: lint.FailureCategoryStyle, Failure: fmt.Sprintf("repeated return type %q can be omitted", prevTypeStr)})
					}
					prevType = field.Type
				}
			}
		}
		return true
	})
	return failures
}

var defaultImportAliasNamingAllowRegexp = regexp.MustCompile("^[a-z][a-z0-9]{0,}$")

// ImportAliasNamingRule lints import alias naming.
type ImportAliasNamingRule struct {
	allowRegexp *regexp.Regexp
	denyRegexp  *regexp.Regexp
}

func init() { register(&ImportAliasNamingRule{}, false) }

// Name returns the rule name.
func (*ImportAliasNamingRule) Name() string { return "import-alias-naming" }

func (r *ImportAliasNamingRule) setAllowRule(value any) error {
	namingRule, ok := value.(string)
	if !ok {
		return fmt.Errorf("invalid argument '%v' for import-alias-naming allowRegexp rule. Expecting string, got %T", value, value)
	}
	re, err := regexp.Compile(namingRule)
	if err != nil {
		return fmt.Errorf("invalid argument to the import-alias-naming allowRegexp rule. Expecting %q to be a valid regular expression, got: %w", namingRule, err)
	}
	r.allowRegexp = re
	return nil
}

func (r *ImportAliasNamingRule) setDenyRule(value any) error {
	namingRule, ok := value.(string)
	if !ok {
		return fmt.Errorf("invalid argument '%v' for import-alias-naming denyRegexp rule. Expecting string, got %T", value, value)
	}
	re, err := regexp.Compile(namingRule)
	if err != nil {
		return fmt.Errorf("invalid argument to the import-alias-naming denyRegexp rule. Expecting %q to be a valid regular expression, got: %w", namingRule, err)
	}
	r.denyRegexp = re
	return nil
}

// Configure validates the rule configuration.
func (r *ImportAliasNamingRule) Configure(arguments lint.Arguments) error {
	r.allowRegexp, r.denyRegexp = nil, nil
	if len(arguments) == 0 {
		r.allowRegexp = defaultImportAliasNamingAllowRegexp
		return nil
	}
	switch namingRule := arguments[0].(type) {
	case string:
		if err := r.setAllowRule(namingRule); err != nil {
			return err
		}
	case map[string]any:
		for k, v := range namingRule {
			switch {
			case isRuleOption(k, "allowRegex"):
				if err := r.setAllowRule(v); err != nil {
					return err
				}
			case isRuleOption(k, "denyRegex"):
				if err := r.setDenyRule(v); err != nil {
					return err
				}
			default:
				return fmt.Errorf("invalid map key for 'import-alias-naming' rule. Expecting 'allowRegex' or 'denyRegex', got %v", k)
			}
		}
	default:
		return fmt.Errorf("invalid argument '%v' for 'import-alias-naming' rule. Expecting string or map[string]string, got %T", arguments[0], arguments[0])
	}
	if r.allowRegexp == nil && r.denyRegexp == nil {
		r.allowRegexp = defaultImportAliasNamingAllowRegexp
	}
	return nil
}

// Apply applies the rule to given file.
func (r *ImportAliasNamingRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	for _, is := range file.AST.Imports {
		if is.Path == nil {
			continue
		}
		alias := is.Name
		if alias == nil || alias.Name == "_" || alias.Name == "." {
			continue
		}
		if r.allowRegexp != nil && !r.allowRegexp.MatchString(alias.Name) {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Failure:    fmt.Sprintf("import name (%s) must match the regular expression: %s", alias.Name, r.allowRegexp.String()),
				Node:       alias,
				Category:   lint.FailureCategoryImports,
			})
		}
		if r.denyRegexp != nil && r.denyRegexp.MatchString(alias.Name) {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Failure:    fmt.Sprintf("import name (%s) must NOT match the regular expression: %s", alias.Name, r.denyRegexp.String()),
				Node:       alias,
				Category:   lint.FailureCategoryImports,
			})
		}
	}
	return failures
}

// OptimizeOperandsOrderRule checks inefficient conditional expressions.
type OptimizeOperandsOrderRule struct{}

func init() { register(&OptimizeOperandsOrderRule{}, false) }

// Name returns the rule name.
func (*OptimizeOperandsOrderRule) Name() string { return "optimize-operands-order" }

// Apply applies the rule to given file.
func (*OptimizeOperandsOrderRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	isCaller := func(n ast.Node) bool {
		ce, ok := n.(*ast.CallExpr)
		if !ok {
			return false
		}
		ident, isIdent := ce.Fun.(*ast.Ident)
		if !isIdent {
			return true
		}
		return ident.Name != "len" || ident.Obj != nil
	}
	ast.Inspect(file.AST, func(node ast.Node) bool {
		binExpr, ok := node.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch binExpr.Op {
		case token.LAND, token.LOR:
		default:
			return true
		}
		if len(pick(binExpr.X, isCaller)) < 1 {
			return true
		}
		if len(pick(binExpr.Y, isCaller)) > 0 {
			return true
		}
		newExpr := ast.BinaryExpr{X: binExpr.Y, Y: binExpr.X, Op: binExpr.Op}
		failures = append(failures, lint.Failure{
			Failure:    fmt.Sprintf("for better performance '%v' might be rewritten as '%v'", gofmt(binExpr), gofmt(&newExpr)),
			Node:       node,
			Category:   lint.FailureCategoryOptimization,
			Confidence: 0.3,
		})
		return true
	})
	return failures
}

// RedundantImportAlias warns on import aliases matching the imported package name.
type RedundantImportAlias struct{}

func init() { register(&RedundantImportAlias{}, false) }

// Name returns the rule name.
func (*RedundantImportAlias) Name() string { return "redundant-import-alias" }

// Apply applies the rule to given file.
func (*RedundantImportAlias) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	for _, imp := range file.AST.Imports {
		if imp.Name == nil {
			continue
		}
		path := imp.Path.Value
		name := strings.Trim(path, `"`)
		if i := strings.LastIndex(path, "/"); i != -1 {
			name = strings.Trim(path[i+1:], `"`)
		}
		if name == imp.Name.Name {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Failure:    fmt.Sprintf("Import alias \"%s\" is redundant", imp.Name.Name),
				Node:       imp,
				Category:   lint.FailureCategoryImports,
			})
		}
	}
	return failures
}

// RedundantBuildTagRule lints the presence of redundant build tags.
type RedundantBuildTagRule struct{}

func init() { register(&RedundantBuildTagRule{}, false) }

// Name returns the rule name.
func (*RedundantBuildTagRule) Name() string { return "redundant-build-tag" }

// Apply applies the rule to given file.
func (*RedundantBuildTagRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	for _, group := range file.AST.Comments {
		hasGoBuild := false
		for _, comment := range group.List {
			if strings.HasPrefix(comment.Text, "//go:build ") {
				hasGoBuild = true
				continue
			}
			if hasGoBuild && strings.HasPrefix(comment.Text, "// +build ") {
				return []lint.Failure{{
					Category:   lint.FailureCategoryStyle,
					Confidence: 1,
					Node:       comment,
					Failure:    `The build tag "// +build" is redundant since Go 1.17 and can be removed`,
				}}
			}
		}
	}
	return []lint.Failure{}
}

// TimeEqualRule shows where "==" and "!=" used for equality check time.Time
type TimeEqualRule struct{}

func init() { register(&TimeEqualRule{}, false) }

// Name returns the rule name.
func (*TimeEqualRule) Name() string { return "time-equal" }

// Apply applies the rule to given file.
func (*TimeEqualRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	_ = file.Pkg.TypeCheck()
	ast.Inspect(file.AST, func(node ast.Node) bool {
		expr, ok := node.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch expr.Op {
		case token.EQL, token.NEQ:
		default:
			return true
		}
		typeOfX := file.Pkg.TypeOf(expr.X)
		typeOfY := file.Pkg.TypeOf(expr.Y)
		if !(isNamedType(typeOfX, "time", "Time") && isNamedType(typeOfY, "time", "Time")) {
			return true
		}
		negateStr := ""
		if token.NEQ == expr.Op {
			negateStr = "!"
		}
		failures = append(failures, lint.Failure{
			Category:   lint.FailureCategoryTime,
			Confidence: 1,
			Node:       node,
			Failure:    fmt.Sprintf("use %s%s.Equal(%s) instead of %q operator", negateStr, gofmt(expr.X), gofmt(expr.Y), expr.Op),
		})
		return true
	})
	return failures
}

// UncheckedTypeAssertionRule lints missing or ignored `ok`-value in dynamic type casts.
type UncheckedTypeAssertionRule struct {
	acceptIgnoredAssertionResult bool
}

func init() { register(&UncheckedTypeAssertionRule{}, false) }

// Name returns the rule name.
func (*UncheckedTypeAssertionRule) Name() string { return "unchecked-type-assertion" }

// Configure validates the rule configuration.
func (r *UncheckedTypeAssertionRule) Configure(arguments lint.Arguments) error {
	r.acceptIgnoredAssertionResult = false
	if len(arguments) == 0 {
		return nil
	}
	args, ok := arguments[0].(map[string]any)
	if !ok {
		return errors.New("unable to get arguments. Expected object of key-value-pairs")
	}
	for k, v := range args {
		switch {
		case isRuleOption(k, "acceptIgnoredAssertionResult"):
			r.acceptIgnoredAssertionResult, ok = v.(bool)
			if !ok {
				return fmt.Errorf("unable to parse argument '%s'. Expected boolean", k)
			}
		default:
			return fmt.Errorf("unknown argument: %s", k)
		}
	}
	return nil
}

// Apply applies the rule to given file.
func (r *UncheckedTypeAssertionRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	addFailure := func(n *ast.TypeAssertExpr, why string) {
		failures = append(failures, lint.Failure{
			Category:   lint.FailureCategoryBadPractice,
			Confidence: 1,
			Node:       n,
			Failure:    fmt.Sprintf("type cast result is unchecked in %v - %s", gofmt(n), why),
		})
	}
	const (
		msgPanic   = "type assertion will panic if not matched"
		msgIgnored = "type assertion result ignored"
	)
	requireNoTypeAssert := func(expr ast.Expr) {
		e, ok := expr.(*ast.TypeAssertExpr)
		if ok && e.Type != nil {
			addFailure(e, msgPanic)
		}
	}
	requireBinaryExpressionWithoutTypeAssertion := func(expr ast.Expr) {
		if b, ok := expr.(*ast.BinaryExpr); ok {
			requireNoTypeAssert(b.X)
			requireNoTypeAssert(b.Y)
		}
	}
	ast.Inspect(file.AST, func(node ast.Node) bool {
		switch n := node.(type) {
		case *ast.RangeStmt:
			requireNoTypeAssert(n.X)
		case *ast.SwitchStmt:
			requireNoTypeAssert(n.Tag)
			requireBinaryExpressionWithoutTypeAssertion(n.Tag)
		case *ast.ReturnStmt:
			for _, res := range n.Results {
				requireNoTypeAssert(res)
			}
		case *ast.AssignStmt:
			if len(n.Rhs) == 0 {
				return true
			}
			e, ok := n.Rhs[0].(*ast.TypeAssertExpr)
			if !ok || e == nil {
				return true
			}
			if e.Type == nil {
				return true
			}
			if len(n.Lhs) == 1 {
				addFailure(e, msgPanic)
			}
			if !r.acceptIgnoredAssertionResult && len(n.Lhs) == 2 && isIdent(n.Lhs[1], "_") {
				addFailure(e, msgIgnored)
			}
		case *ast.IfStmt:
			if c, ok := n.Cond.(*ast.BinaryExpr); ok {
				requireNoTypeAssert(c.X)
				requireNoTypeAssert(c.Y)
			}
		case *ast.CaseClause:
			for _, expr := range n.List {
				requireNoTypeAssert(expr)
				requireBinaryExpressionWithoutTypeAssertion(expr)
			}
		case *ast.SendStmt:
			requireNoTypeAssert(n.Value)
		}
		return true
	})
	return failures
}

// UnconditionalRecursionRule lints given else constructs.
type UnconditionalRecursionRule struct{}

func init() { register(&UnconditionalRecursionRule{}, false) }

// Name returns the rule name.
func (*UnconditionalRecursionRule) Name() string { return "unconditional-recursion" }

type urFuncDesc struct {
	receiverID *ast.Ident
	id         *ast.Ident
}

func (fd *urFuncDesc) equal(other *urFuncDesc) bool {
	receiversAreEqual := (fd.receiverID == nil && other.receiverID == nil) || fd.receiverID != nil && other.receiverID != nil && fd.receiverID.Name == other.receiverID.Name
	idsAreEqual := (fd.id == nil && other.id == nil) || fd.id.Name == other.id.Name
	return receiversAreEqual && idsAreEqual
}

type urFuncStatus struct {
	funcDesc            *urFuncDesc
	seenConditionalExit bool
}

type lintUnconditionalRecursionRule struct {
	onFailure     func(lint.Failure)
	currentFunc   *urFuncStatus
	inGoStatement bool
}

func (w *lintUnconditionalRecursionRule) Visit(node ast.Node) ast.Visitor {
	switch n := node.(type) {
	case *ast.IfStmt:
		w.updateFuncStatus(n.Body)
		if n.Else != nil {
			w.updateFuncStatus(n.Else)
		}
		return nil
	case *ast.SelectStmt:
		w.updateFuncStatus(n.Body)
		return nil
	case *ast.RangeStmt:
		w.updateFuncStatus(n.Body)
		return nil
	case *ast.TypeSwitchStmt:
		w.updateFuncStatus(n.Body)
		return nil
	case *ast.SwitchStmt:
		w.updateFuncStatus(n.Body)
		return nil
	case *ast.GoStmt:
		w.inGoStatement = true
		ast.Walk(w, n.Call)
		w.inGoStatement = false
		return nil
	case *ast.ForStmt:
		if n.Cond != nil {
			return nil
		}
		return w
	case *ast.FuncLit:
		return nil
	case *ast.CallExpr:
		var funcID *ast.Ident
		var selector *ast.Ident
		switch c := n.Fun.(type) {
		case *ast.Ident:
			funcID = c
		case *ast.SelectorExpr:
			var ok bool
			selector, ok = c.X.(*ast.Ident)
			if !ok {
				return nil
			}
			funcID = c.Sel
		default:
			return w
		}
		if w.currentFunc != nil &&
			!w.currentFunc.seenConditionalExit &&
			w.currentFunc.funcDesc.equal(&urFuncDesc{selector, funcID}) {
			w.onFailure(lint.Failure{
				Category:   lint.FailureCategoryLogic,
				Confidence: 0.8,
				Node:       n,
				Failure:    "unconditional recursive call",
			})
		}
	}
	return w
}

func (w *lintUnconditionalRecursionRule) updateFuncStatus(node ast.Node) {
	if node == nil || w.currentFunc == nil || w.currentFunc.seenConditionalExit {
		return
	}
	w.currentFunc.seenConditionalExit = hasControlExit(node)
}

func hasControlExit(node ast.Node) bool {
	isExit := func(node ast.Node) bool {
		switch n := node.(type) {
		case *ast.ReturnStmt:
			return true
		case *ast.CallExpr:
			if isIdent(n.Fun, "panic") {
				return true
			}
			se, ok := n.Fun.(*ast.SelectorExpr)
			if !ok {
				return false
			}
			id, ok := se.X.(*ast.Ident)
			if !ok {
				return false
			}
			if exitFunctions[id.Name] != nil && exitFunctions[id.Name][se.Sel.Name] {
				return true
			}
		}
		return false
	}
	return len(pick(node, isExit)) != 0
}

// Apply applies the rule to given file.
func (*UnconditionalRecursionRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	onFailure := func(f lint.Failure) { failures = append(failures, f) }
	for _, decl := range file.AST.Decls {
		n, ok := decl.(*ast.FuncDecl)
		if !ok || n.Body == nil {
			continue
		}
		var rec *ast.Ident
		switch {
		case n.Recv == nil:
			rec = nil
		case n.Recv.NumFields() < 1 || len(n.Recv.List[0].Names) < 1:
			rec = &ast.Ident{Name: "_"}
		default:
			rec = n.Recv.List[0].Names[0]
		}
		w := &lintUnconditionalRecursionRule{
			onFailure:   onFailure,
			currentFunc: &urFuncStatus{&urFuncDesc{rec, n.Name}, false},
		}
		ast.Walk(w, n.Body)
	}
	return failures
}

// UnhandledErrorRule warns on unhandled errors returned by function calls.
type UnhandledErrorRule struct {
	ignoreList []*regexp.Regexp
}

func init() { register(&UnhandledErrorRule{}, false) }

// Name returns the rule name.
func (*UnhandledErrorRule) Name() string { return "unhandled-error" }

// Configure validates the rule configuration.
func (r *UnhandledErrorRule) Configure(arguments lint.Arguments) error {
	r.ignoreList = nil
	for _, arg := range arguments {
		argStr, ok := arg.(string)
		if !ok {
			return fmt.Errorf("invalid argument to the unhandled-error rule. Expecting a string, got %T", arg)
		}
		argStr = strings.Trim(argStr, " ")
		if argStr == "" {
			return errors.New("invalid argument to the unhandled-error rule, expected regular expression must not be empty")
		}
		exp, err := regexp.Compile(argStr)
		if err != nil {
			return fmt.Errorf("invalid argument to the unhandled-error rule: regexp %q does not compile: %w", argStr, err)
		}
		r.ignoreList = append(r.ignoreList, exp)
	}
	return nil
}

// Apply applies the rule to given file.
func (r *UnhandledErrorRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	_ = file.Pkg.TypeCheck()
	isTypeError := func(t *types.Named) bool {
		return t.Obj().Id() == "_.error"
	}
	funcName := func(call *ast.CallExpr) string {
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if ok {
			if info := file.Pkg.TypesInfo(); info != nil {
				if fn, ok := info.ObjectOf(sel.Sel).(*types.Func); ok {
					name := fn.FullName()
					name = strings.ReplaceAll(name, "(", "")
					name = strings.ReplaceAll(name, ")", "")
					name = strings.ReplaceAll(name, "*", "")
					return name
				}
			}
		}
		return gofmt(call.Fun)
	}
	addFailure := func(n *ast.CallExpr) {
		name := funcName(n)
		for _, pattern := range r.ignoreList {
			if len(pattern.FindString(name)) == len(name) {
				return
			}
		}
		failures = append(failures, lint.Failure{
			Category:   lint.FailureCategoryBadPractice,
			Confidence: 1,
			Node:       n,
			Failure:    fmt.Sprintf("Unhandled error in call to function %v", name),
		})
	}
	ast.Walk(walker(func(node ast.Node) bool {
		n, ok := node.(*ast.ExprStmt)
		if !ok {
			return true
		}
		fCall, ok := n.X.(*ast.CallExpr)
		if !ok {
			return false
		}
		funcType := file.Pkg.TypeOf(fCall)
		if funcType == nil {
			return false
		}
		switch t := funcType.(type) {
		case *types.Named:
			if !isTypeError(t) {
				return false
			}
			addFailure(fCall)
		default:
			retTypes, ok := funcType.Underlying().(*types.Tuple)
			if !ok {
				return false
			}
			for i := 0; i < retTypes.Len(); i++ {
				if nt, ok := retTypes.At(i).Type().(*types.Named); ok && isTypeError(nt) {
					addFailure(fCall)
					break
				}
			}
		}
		return true
	}), file.AST)
	return failures
}

// UseErrorsNewRule spots calls to fmt.Errorf that can be replaced by errors.New.
type UseErrorsNewRule struct{}

func init() { register(&UseErrorsNewRule{}, false) }

// Name returns the rule name.
func (*UseErrorsNewRule) Name() string { return "use-errors-new" }

// Apply applies the rule to given file.
func (*UseErrorsNewRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Inspect(file.AST, func(n ast.Node) bool {
		funcCall, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		if !isPkgDot(funcCall.Fun, "fmt", "Errorf") {
			return true
		}
		if len(funcCall.Args) > 1 {
			return true
		}
		failures = append(failures, lint.Failure{
			Category:   lint.FailureCategoryErrors,
			Node:       n,
			Confidence: 1,
			Failure:    "replace fmt.Errorf by errors.New",
		})
		return true
	})
	return failures
}
