package rule

import (
	"fmt"
	"go/ast"
	"go/token"

	"github.com/revivelint/revive/internal/lint"
)

// IdenticalBranchesRule warns on constant logical expressions.
type IdenticalBranchesRule struct{}

func init() { register(&IdenticalBranchesRule{}, false) }

// Name returns the rule name.
func (*IdenticalBranchesRule) Name() string { return "identical-branches" }

// Apply applies the rule to given file.
func (*IdenticalBranchesRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Inspect(file.AST, func(node ast.Node) bool {
		n, ok := node.(*ast.IfStmt)
		if !ok {
			return true
		}
		if n.Else == nil {
			return true
		}
		elseBranch, ok := n.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		if len(n.Body.List) == len(elseBranch.List) && gofmt(n.Body) == gofmt(elseBranch) {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Node:       n,
				Category:   lint.FailureCategoryLogic,
				Failure:    "both branches of the if are identical",
			})
		}
		return true
	})
	return failures
}

func containsCall(n ast.Node) bool {
	found := false
	ast.Inspect(n, func(n ast.Node) bool {
		if _, ok := n.(*ast.CallExpr); ok {
			found = true
		}
		return !found
	})
	return found
}

// collectIfElseIfChains walks the AST and calls fn for each root of an if...else if chain.
func walkIfChains(root ast.Node, fn func(ifStmt *ast.IfStmt)) {
	elseIfs := map[*ast.IfStmt]bool{}
	ast.Inspect(root, func(node ast.Node) bool {
		ifStmt, ok := node.(*ast.IfStmt)
		if !ok {
			return true
		}
		if elseIf, ok := ifStmt.Else.(*ast.IfStmt); ok {
			elseIfs[elseIf] = true
		}
		if elseIfs[ifStmt] {
			return true
		}
		if _, ok := ifStmt.Else.(*ast.IfStmt); !ok {
			return true
		}
		fn(ifStmt)
		return true
	})
}

// IdenticalIfElseIfBranchesRule warns on if...else if chains with identical branches.
type IdenticalIfElseIfBranchesRule struct{}

func init() { register(&IdenticalIfElseIfBranchesRule{}, false) }

// Name returns the rule name.
func (*IdenticalIfElseIfBranchesRule) Name() string { return "identical-ifelseif-branches" }

// Apply applies the rule to given file.
func (*IdenticalIfElseIfBranchesRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	walkIfChains(file.AST, func(root *ast.IfStmt) {
		var branches []*ast.BlockStmt
		hasCall := false
		cur := root
		for {
			branches = append(branches, cur.Body)
			if containsCall(cur.Cond) {
				hasCall = true
			}
			switch e := cur.Else.(type) {
			case *ast.IfStmt:
				cur = e
				continue
			case *ast.BlockStmt:
				branches = append(branches, e)
			}
			break
		}
		confidence := 1.0
		if hasCall {
			confidence = 0.8
		}
		seen := map[string]int{}
		for _, b := range branches {
			line := file.ToPosition(b.Pos()).Line
			h := gofmt(b)
			if prev, ok := seen[h]; ok {
				failures = append(failures, lint.Failure{
					Confidence: confidence,
					Node:       root.Body,
					Category:   lint.FailureCategoryLogic,
					Failure:    fmt.Sprintf("\"if...else if\" chain with identical branches (lines %d and %d)", prev, line),
				})
			}
