// collectIfElseIfChains walks the AST and calls fn for each root of an if...else if chain.
func walkIfChains(root ast.Node, fn func(ifStmt *ast.IfStmt)) {
	elseIfs := map[*ast.IfStmt]bool{}
	ast.Inspect(root, func(node ast.Node) bool {
		ifStmt, ok := node.(*ast.IfStmt)
		if !ok {
			return true
		}
		if elseIf, ok := ifStmt.Else.(*ast.IfStmt); ok {
			elseIfs[elseIf] = true
		}
		if elseIfs[ifStmt] {
			return true
		}
		if _, ok := ifStmt.Else.(*ast.IfStmt); !ok {
			return true
		}
		fn(ifStmt)
		return true
	})
}

