package rule

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"

	"github.com/revivelint/revive/internal/lint"
)

func typeCheckFailure(file *lint.File, err error) []lint.Failure {
	return []lint.Failure{lint.NewInternalFailure(fmt.Sprintf("Unable to type check file %q: %v", file.Name, err))}
}

// InefficientMapLookupRule spots iterative searches for a key in a map.
type InefficientMapLookupRule struct{}

func init() { register(&InefficientMapLookupRule{}, false) }

// Name returns the rule name.
func (*InefficientMapLookupRule) Name() string { return "inefficient-map-lookup" }

// Apply applies the rule to given file.
func (*InefficientMapLookupRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if err := file.Pkg.TypeCheck(); err != nil {
		return typeCheckFailure(file, err)
	}
	var failures []lint.Failure
	ast.Inspect(file.AST, func(node ast.Node) bool {
		rs, ok := node.(*ast.RangeStmt)
		if !ok {
			return true
		}
		if _, ok := file.Pkg.TypeOf(rs.X).(*types.Map); !ok {
			return true
		}
		key, ok := rs.Key.(*ast.Ident)
		if !ok {
			return true
		}
		if rs.Value != nil && !isIdent(rs.Value, "_") {
			return true
		}
		if len(rs.Body.List) == 0 {
			return true
		}
		ifStmt, ok := rs.Body.List[0].(*ast.IfStmt)
		if !ok {
			return true
		}
		cond, ok := ifStmt.Cond.(*ast.BinaryExpr)
		if !ok || !isIdent(cond.X, key.Name) {
			return true
		}
		match := false
		switch cond.Op {
		case token.EQL:
			match = len(rs.Body.List) == 1
		case token.NEQ:
			if len(ifStmt.Body.List) == 1 {
				if br, ok := ifStmt.Body.List[0].(*ast.BranchStmt); ok && br.Tok == token.CONTINUE {
					match = true
				}
			}
		}
		if match {
			failures = append(failures, lint.Failure{
				Category:   lint.FailureCategoryStyle,
				Confidence: 1,
				Node:       rs,
				Failure:    "inefficient lookup of map key",
			})
		}
		return true
	})
	return failures
}

