// EnforceSwitchStyleRule implements a rule to enforce default clauses use and/or position.
type EnforceSwitchStyleRule struct {
	allowNoDefault      bool
	allowDefaultNotLast bool
}

func init() { register(&EnforceSwitchStyleRule{}, false) }

// Name returns the rule name.
func (*EnforceSwitchStyleRule) Name() string { return "enforce-switch-style" }

// Configure validates the rule configuration.
func (r *EnforceSwitchStyleRule) Configure(arguments lint.Arguments) error {
	r.allowNoDefault, r.allowDefaultNotLast = false, false
	for _, arg := range arguments {
		argStr, ok := arg.(string)
		if !ok {
			return fmt.Errorf("invalid argument for rule %s; expected string but got %T", r.Name(), arg)
		}
		switch {
		case isRuleOption(argStr, "allowNoDefault"):
			r.allowNoDefault = true
		case isRuleOption(argStr, "allowDefaultNotLast"):
			r.allowDefaultNotLast = true
		default:
			return fmt.Errorf(`invalid argument %q for rule %s; expected "allowNoDefault" or "allowDefaultNotLast"`, argStr, r.Name())
		}
	}
	return nil
}

// Apply applies the rule to given file.
func (r *EnforceSwitchStyleRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Inspect(file.AST, func(n ast.Node) bool {
		var body *ast.BlockStmt
		switch n := n.(type) {
		case *ast.SwitchStmt:
			body = n.Body
		case *ast.TypeSwitchStmt:
			body = n.Body
		default:
			return true
		}
		if len(body.List) == 0 {
			return true
		}
		defaultIdx := -1
		for i, s := range body.List {
			if cc, ok := s.(*ast.CaseClause); ok && cc.List == nil {
				defaultIdx = i
				break
			}
		}
		if defaultIdx < 0 {
			if !r.allowNoDefault {
				failures = append(failures, lint.Failure{
					Confidence: 1,
					Node:       n,
					Category:   lint.FailureCategoryStyle,
					Failure:    "switch must have a default case clause",
				})
			}
			return true
		}
		if !r.allowDefaultNotLast && defaultIdx != len(body.List)-1 {
			failures = append(failures, lint.Failure{
				Confidence: 1,
				Node:       body.List[defaultIdx],
				Category:   lint.FailureCategoryStyle,
				Failure:    "default case clause must be the last one",
			})
		}
		return true
	})
	return failures
}

// UselessFallthroughRule warns on useless fallthroughs in switch case clauses.
type UselessFallthroughRule struct{}

func init() { register(&UselessFallthroughRule{}, false) }

// Name returns the rule name.
func (*UselessFallthroughRule) Name() string { return "useless-fallthrough" }

// Apply applies the rule to given file.
func (*UselessFallthroughRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	commentsMap := file.CommentMap()
	ast.Inspect(file.AST, func(node ast.Node) bool {
		switchStmt, ok := node.(*ast.SwitchStmt)
		if !ok {
			return true
		}
		if switchStmt.Tag == nil {
			return true
		}
		casesCount := len(switchStmt.Body.List)
		for i := 0; i < casesCount-1; i++ {
			caseClause, ok := switchStmt.Body.List[i].(*ast.CaseClause)
			if !ok {
				continue
			}
			if len(caseClause.Body) != 1 {
				continue
			}
			branchStmt, ok := caseClause.Body[0].(*ast.BranchStmt)
			if !ok || branchStmt.Tok != token.FALLTHROUGH {
				continue
			}
			nextCaseClause, ok := switchStmt.Body.List[i+1].(*ast.CaseClause)
			if !ok || nextCaseClause.List == nil {
				continue
			}
			confidence := 1.0
			if commentsMap[branchStmt] != nil {
				confidence = 0.5
			}
			failures = append(failures, lint.Failure{
				Confidence: confidence,
				Node:       branchStmt,
				Category:   lint.FailureCategoryStyle,
				Failure:    `this "fallthrough" can be removed by consolidating this case clause with the next one`,
			})
		}
		return true
	})
	return failures
}

