func (*UnnecessaryFormatRule) Name() string { return "unnecessary-format" }

// Apply applies the rule to given file.
func (*UnnecessaryFormatRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Inspect(file.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		x, ok := sel.X.(*ast.Ident)
		if !ok {
			return true
		}
		name := x.Name + "." + sel.Sel.Name
		spec, ok := formattingFuncs[name]
		if !ok {
			if !testingFormattingMethods[sel.Sel.Name] {
				return true
			}
			spec = formattingSpec{0, x.Name + "." + strings.TrimSuffix(sel.Sel.Name, "f")}
		}
		if len(call.Args) <= spec.formatArgPosition {
			return true
		}
		lit, ok := call.Args[spec.formatArgPosition].(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return true
		}
		if strings.Contains(lit.Value, "%") {
			return true
		}
		failures = append(failures, lint.Failure{
			Category:   lint.FailureCategoryOptimization,
			Confidence: 0.8,
			Node:       call.Fun,
			Failure:    fmt.Sprintf("unnecessary use of formatting function \"%s\", you can replace it with \"%s\"", name, spec.alternative),
		})
		return true
	})
	return failures
}

// UseFmtPrintRule lints calls to print and println.
type UseFmtPrintRule struct{}

func init() { register(&UseFmtPrintRule{}, false) }

// Name returns the rule name.
func (*UseFmtPrintRule) Name() string { return "use-fmt-print" }

// Apply applies the rule to given file.
func (*UseFmtPrintRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Inspect(file.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		id, ok := call.Fun.(*ast.Ident)
		if !ok {
			return true
		}
		var alt string
		switch id.Name {
		case "print":
			alt = "fmt.Fprint"
		case "println":
			alt = "fmt.Fprintln"
		default:
			return true
		}
		args := make([]string, len(call.Args))
		for i, a := range call.Args {
			args[i] = gofmt(a)
		}
		failures = append(failures, lint.Failure{
			Category:   lint.FailureCategoryBadPractice,
			Confidence: 1,
			Node:       call,
			Failure:    fmt.Sprintf("avoid using built-in function %q, replace it by \"%s(os.Stderr, %s)\"", id.Name, alt, strings.Join(args, ", ")),
		})
		return true
	})
	return failures
}

// UnsecureURLSchemeRule checks if a file contains string literals with unsecure URL schemes.
type UnsecureURLSchemeRule struct{}

func init() { register(&UnsecureURLSchemeRule{}, false) }

// Name returns the rule name.
func (*UnsecureURLSchemeRule) Name() string { return "unsecure-url-scheme" }

// Apply applies the rule to given file.
func (*UnsecureURLSchemeRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Inspect(file.AST, func(n ast.Node) bool {
		lit, ok := n.(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING || len(lit.Value) < 2 {
			return true
		}
		content := lit.Value[1 : len(lit.Value)-1]
		var scheme, secure string
		switch {
		case strings.HasPrefix(content, "http://"):
			scheme, secure = "http", "https"
		case strings.HasPrefix(content, "ws://"):
			scheme, secure = "ws", "wss"
		default:
			return true
		}
		if len(content) == len(scheme)+len("://") {
			return true
		}
		if strings.Contains(content, "localhost") || strings.Contains(content, "127.0.0.1") || strings.Contains(content, "0.0.0.0") {
			return true
		}
		failures = append(failures, lint.Failure{
			Confidence: 1,
			Node:       lit,
			Failure:    fmt.Sprintf("prefer secure protocol %s over %s in %s", secure, scheme, lit.Value),
		})
		return true
	})
	return failures
}

// UnnecessaryIfRule warns on if...else statements that can be replaced by simpler expressions.
type UnnecessaryIfRule struct{}

func init() { register(&UnnecessaryIfRule{}, false) }

// Name returns the rule name.
func (*UnnecessaryIfRule) Name() string { return "unnecessary-if" }

func boolLitValue(e ast.Expr) (bool, bool) {
	id, ok := e.(*ast.Ident)
	if !ok {
		return false, false
	}
	switch id.Name {
	case "true":
		return true, true
	case "false":
		return false, true
	}
	return false, false
}

var negatedComparisonOps = map[token.Token]token.Token{
	token.EQL: token.NEQ,
	token.NEQ: token.EQL,
	token.LSS: token.GEQ,
	token.GEQ: token.LSS,
	token.GTR: token.LEQ,
	token.LEQ: token.GTR,
}

func negateCondition(cond ast.Expr) string {
	if b, ok := cond.(*ast.BinaryExpr); ok {
		if op, ok := negatedComparisonOps[b.Op]; ok {
			return gofmt(&ast.BinaryExpr{X: b.X, Op: op, Y: b.Y})
		}
	}
	return "!(" + gofmt(cond) + ")"
}

// Apply applies the rule to given file.
func (*UnnecessaryIfRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	ast.Inspect(file.AST, func(n ast.Node) bool {
		ifStmt, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		if ifStmt.Init != nil {
			return true
		}
		elseBlock, ok := ifStmt.Else.(*ast.BlockStmt)
		if !ok {
			return true
		}
		if len(ifStmt.Body.List) != 1 || len(elseBlock.List) != 1 {
			return true
		}
		var thenValue bool
		var prefix string
		switch thenStmt := ifStmt.Body.List[0].(type) {
		case *ast.ReturnStmt:
			elseStmt, ok := elseBlock.List[0].(*ast.ReturnStmt)
			if !ok || len(thenStmt.Results) != 1 || len(elseStmt.Results) != 1 {
				return true
			}
			v, ok := boolLitValue(thenStmt.Results[0])
			if !ok {
				return true
			}
			if _, ok := boolLitValue(elseStmt.Results[0]); !ok {
				return true
			}
			thenValue = v
			prefix = "return "
		case *ast.AssignStmt:
			elseStmt, ok := elseBlock.List[0].(*ast.AssignStmt)
			if !ok || thenStmt.Tok != token.ASSIGN || elseStmt.Tok != token.ASSIGN {
				return true
			}
			if len(thenStmt.Lhs) != 1 || len(thenStmt.Rhs) != 1 || len(elseStmt.Lhs) != 1 || len(elseStmt.Rhs) != 1 {
				return true
			}
			lhs := gofmt(thenStmt.Lhs[0])
			if lhs != gofmt(elseStmt.Lhs[0]) {
				return true
			}
			v, ok := boolLitValue(thenStmt.Rhs[0])
			if !ok {
				return true
			}
			if _, ok := boolLitValue(elseStmt.Rhs[0]); !ok {
				return true
			}
			thenValue = v
			prefix = lhs + " = "
		default:
			return true
		}
		cond := gofmt(ifStmt.Cond)
		if !thenValue {
			cond = negateCondition(ifStmt.Cond)
		}
		failures = append(failures, lint.Failure{
			Confidence: 1,
			Node:       ifStmt,
			Category:   lint.FailureCategoryLogic,
			Failure:    "replace this conditional by: " + prefix + cond,
		})
		return true
	})
	return failures
}

// TimeDateRule lints the way time.Date is used.
type TimeDateRule struct{}

func init() { register(&TimeDateRule{}, false) }

// Name returns the rule name.
func (*TimeDateRule) Name() string { return "time-date" }

var timeDateArgNames = []string{"year", "month", "day", "hour", "minute", "second", "nanosecond", "timezone"}

var monthNames = []string{"", "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"}

func daysIn(month int, year int64) int {
	switch month {
	case 2:
		if (year%4 == 0 && year%100 != 0) || year%400 == 0 {
			return 29
		}
		return 28
	case 4, 6, 9, 11:
		return 30
	}
	return 31
}

// Apply applies the rule to given file.
func (*TimeDateRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	var failures []lint.Failure
	add := func(n ast.Node, conf float64, msg string) {
		failures = append(failures, lint.Failure{
			Category:   lint.FailureCategoryTime,
			Confidence: conf,
			Node:       n,
			Failure:    msg,
		})
	}
	ast.Inspect(file.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		if !isPkgDot(call.Fun, "time", "Date") || len(call.Args) != 8 {
			return true
		}
		if isIdent(call.Args[7], "nil") {
			add(call.Args[7], 1, "time.Date timezone argument cannot be nil, it would panic on runtime")
		}
		values := make([]int64, 7)
		clean := make([]bool, 7)
		for i := 0; i < 7; i++ {
			arg := call.Args[i]
			name := timeDateArgNames[i]
			switch a := arg.(type) {
			case *ast.UnaryExpr:
				lit, ok := a.X.(*ast.BasicLit)
				if !ok {
					continue
				}
				switch a.Op {
				case token.SUB:
					if i != 0 {
						add(arg, 0.5, fmt.Sprintf("time.Date %s argument is negative: -%s", name, lit.Value))
					}
				case token.ADD:
					add(arg, 0.8, fmt.Sprintf("time.Date %s argument contains a useless plus sign: +%s", name, lit.Value))
				}
				continue
			case *ast.BasicLit:
				s := a.Value
				switch a.Kind {
				case token.INT:
					v, err := strconv.ParseInt(s, 0, 64)
					if err != nil {
						continue
					}
					notation := ""
					conf := 0.8
					lower := strings.ToLower(s)
					switch {
					case strings.HasPrefix(lower, "0x"):
						notation = "hexadecimal notation"
					case strings.HasPrefix(lower, "0b"):
						notation = "binary notation"
					case strings.HasPrefix(lower, "0o"):
						notation = "octal notation"
					case len(s) > 1 && s[0] == '0':
						if d, err := strconv.ParseInt(s, 10, 64); err == nil && d == v {
							notation = "octal notation with leading zero"
							conf = 0.5
						} else {
							notation = "octal notation"
						}
					case strings.Contains(s, "_"):
						notation = "alternative notation"
					}
					if notation != "" {
						add(arg, conf, fmt.Sprintf("use decimal digits for time.Date %s argument: %s found: use %d instead of %s", name, notation, v, s))
						continue
					}
					values[i] = v
					clean[i] = true
				case token.FLOAT:
					f, err := strconv.ParseFloat(strings.ReplaceAll(s, "_", ""), 64)
					if err != nil {
						continue
					}
					notation := "float literal"
					if strings.ContainsAny(s, "eE") && !strings.HasPrefix(strings.ToLower(s), "0x") {
						notation = "exponential notation"
					}
					add(arg, 0.8, fmt.Sprintf("use decimal digits for time.Date %s argument: %s found: use %d instead of %s", name, notation, int64(f), s))
					continue
				default:
					continue
				}
			default:
				continue
			}
			v := values[i]
			switch i {
			case 1:
				if v == 0 {
					add(arg, 1, "time.Date month argument should not be zero")
				} else if v < 1 || v > 12 {
					add(arg, 0.8, fmt.Sprintf("time.Date month argument should be between 1 and 12: %d", v))
				}
			case 2:
				if v == 0 {
					add(arg, 1, "time.Date day argument should not be zero")
					continue
				}
				if clean[1] && values[1] >= 1 && values[1] <= 12 {
					month := int(values[1])
					var year int64
					if clean[0] {
						year = values[0]
					}
					max := daysIn(month, year)
					if v > int64(max) {
						monthName := monthNames[month]
						if month == 2 {
							monthName = fmt.Sprintf("%s %d", monthName, year)
						}
						add(arg, 0.8, fmt.Sprintf("time.Date day argument is %d, but %s has only %d days", v, monthName, max))
					}
					continue
				}
				if v < 1 || v > 31 {
					add(arg, 0.8, fmt.Sprintf("time.Date day argument should be between 1 and 31: %d", v))
				}
			case 3:
				if v > 23 {
					add(arg, 0.8, fmt.Sprintf("time.Date hour argument should be between 0 and 23: %d", v))
				}
			case 4:
				if v > 59 {
					add(arg, 0.8, fmt.Sprintf("time.Date minute argument should be between 0 and 59: %d", v))
				}
			case 5:
				if v > 60 {
					add(arg, 0.8, fmt.Sprintf("time.Date second argument should be between 0 and 60: %d", v))
				}
			case 6:
				if v > 999999999 {
					add(arg, 0.8, fmt.Sprintf("time.Date nanosecond argument should be between 0 and 999999999: %d", v))
				}
			}
		}
		return true
	})
	return failures
}
