package rule

import (
	"fmt"
	"go/ast"

	"github.com/revivelint/revive/internal/lint"
)

func isWgCall(e ast.Expr, method string) bool {
	call, ok := e.(*ast.CallExpr)
	if !ok {
		return false
	}
	return isPkgDot(call.Fun, "wg", method)
}

// UseWaitGroupGoRule spots Go idioms that might be rewritten using WaitGroup.Go.
type UseWaitGroupGoRule struct{}

func init() { register(&UseWaitGroupGoRule{}, false) }

// Name returns the rule name.
func (*UseWaitGroupGoRule) Name() string { return "use-waitgroup-go" }

func containsWgDone(body *ast.BlockStmt) bool {
	found := false
	ast.Inspect(body, func(n ast.Node) bool {
		if found {
			return false
		}
		if _, ok := n.(*ast.FuncLit); ok {
			return false
		}
		if e, ok := n.(ast.Expr); ok && isWgCall(e, "Done") {
			found = true
			return false
		}
		return true
	})
	return found
}

// Apply applies the rule to given file.
func (*UseWaitGroupGoRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if !file.Pkg.IsAtLeastGoVersion(goVersion125) {
		return nil
	}
	var failures []lint.Failure
	ast.Inspect(file.AST, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok {
			return true
		}
		stmts := block.List
		for i := 0; i < len(stmts); i++ {
			es, ok := stmts[i].(*ast.ExprStmt)
			if !ok || !isWgCall(es.X, "Add") {
				continue
			}
			for j := i + 1; j < len(stmts); j++ {
				goStmt, ok := stmts[j].(*ast.GoStmt)
				if !ok {
					continue
				}
				if lit, ok := goStmt.Call.Fun.(*ast.FuncLit); ok && containsWgDone(lit.Body) {
					failures = append(failures, lint.Failure{
						Confidence: 1,
						Node:       stmts[i],
						Category:   lint.FailureCategoryStyle,
						Failure:    "replace wg.Add()...go {...wg.Done()...} with wg.Go(...)",
					})
				}
				i = j
				break
			}
		}
		return true
	})
	return failures
}

// ForbiddenCallInWgGoRule spots calls to panic inside wg.Go.
type ForbiddenCallInWgGoRule struct{}

