	"SliceIsSorted":     "slices.IsSortedFunc",
	"IsSorted":          "slices.IsSortedFunc",
}

// Apply applies the rule to given file.
func (*UseSlicesSortRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if !file.Pkg.IsAtLeastGoVersion(goVersion121) {
		return nil
	}
	var failures []lint.Failure
	ast.Inspect(file.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok || !isIdent(sel.X, "sort") {
			return true
		}
		alt, ok := sortToSlices[sel.Sel.Name]
		if !ok {
