func (*RedundantTestMainExitRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if !file.IsTest() || !file.Pkg.IsAtLeastGoVersion(goVersion115) {
		return nil
	}
	var failures []lint.Failure
	for _, decl := range file.AST.Decls {
