var defaultFilenameFormat = regexp.MustCompile(`^[_A-Za-z0-9][_A-Za-z0-9-]*\.go$`)

// FilenameFormatRule lints source filenames according to a set of regular expressions given as arguments.
type FilenameFormatRule struct {
	format *regexp.Regexp
}

func init() { register(&FilenameFormatRule{}, false) }

// Name returns the rule name.
func (*FilenameFormatRule) Name() string { return "filename-format" }

// Configure validates the rule configuration.
func (r *FilenameFormatRule) Configure(arguments lint.Arguments) error {
	r.format = defaultFilenameFormat
	if len(arguments) == 0 {
		return nil
	}
	arg := arguments[0]
	str, ok := arg.(string)
	if !ok {
		return fmt.Errorf("rule %q expects a string argument, got %v of type %T", r.Name(), arg, arg)
	}
	format, err := regexp.Compile(str)
	if err != nil {
		return fmt.Errorf("rule %q expects a valid regexp argument, got error for %s: %w", r.Name(), str, err)
	}
	r.format = format
	return nil
}

// Apply applies the rule to given file.
func (r *FilenameFormatRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	filename := filepath.Base(file.Name)
	if r.format.MatchString(filename) {
		return nil
	}
	failureMsg := fmt.Sprintf("Filename %s is not of the format %s.", filename, r.format.String())
	for _, c := range filename {
		if c > unicode.MaxASCII {
			failureMsg += fmt.Sprintf(" Non ASCII character %c (%U) found.", c, c)
			break
		}
	}
	return []lint.Failure{{
		Confidence: 1,
		Failure:    failureMsg,
		RuleName:   r.Name(),
		Node:       file.AST.Name,
	}}
}

// PackageDirectoryMismatchRule detects when package name doesn't match directory name.
type PackageDirectoryMismatchRule struct {
	ignoredDirs []string
}

func init() { register(&PackageDirectoryMismatchRule{}, false) }

// Name returns the rule name.
func (*PackageDirectoryMismatchRule) Name() string { return "package-directory-mismatch" }

// Configure validates the rule configuration.
func (r *PackageDirectoryMismatchRule) Configure(arguments lint.Arguments) error {
	r.ignoredDirs = nil
	if len(arguments) == 0 {
		return nil
	}
	args, ok := arguments[0].(map[string]any)
	if !ok {
		return fmt.Errorf("invalid argument type: expected map[string]any, got %T", arguments[0])
	}
	for k, v := range args {
		if !isRuleOption(k, "ignoreDirectories") {
			return fmt.Errorf("unknown argument %s for %s rule", k, r.Name())
		}
		list, ok := v.([]any)
		if !ok {
			return fmt.Errorf("invalid value %v for argument %s of rule %s, expected []string got %T", v, k, r.Name(), v)
		}
		for _, e := range list {
			s, ok := e.(string)
			if !ok {
				return fmt.Errorf("invalid value in %s argument of rule %s: expected string, got %T", k, r.Name(), e)
			}
			r.ignoredDirs = append(r.ignoredDirs, s)
		}
	}
	return nil
}

var versionDirRE = regexp.MustCompile(`^[vV]\d+$`)

func normalizePkgDirName(s string) string {
	return strings.NewReplacer("-", "", "_", "", ".", "").Replace(s)
}

func pkgMatchesDir(pkg, dir string) bool {
	np := normalizePkgDirName(pkg)
	nd := normalizePkgDirName(dir)
	return np == nd || strings.TrimPrefix(nd, "go") == np
}

// Apply applies the rule to given file.
func (r *PackageDirectoryMismatchRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	pkgName := file.AST.Name.Name
	if pkgName == "main" {
		return nil
	}
	absDir, err := filepath.Abs(filepath.Dir(file.Name))
	if err != nil {
		return nil
	}
	for _, d := range r.ignoredDirs {
		if strings.Contains(absDir, d) {
			return nil
		}
	}
	checkName := pkgName
	if file.IsTest() {
		checkName = strings.TrimSuffix(checkName, "_test")
	}
	dirName := filepath.Base(absDir)
	if pkgMatchesDir(checkName, dirName) {
		return nil
	}
	if versionDirRE.MatchString(dirName) && pkgMatchesDir(checkName, filepath.Base(filepath.Dir(absDir))) {
		return nil
	}
	return []lint.Failure{{
		Failure:    fmt.Sprintf("package name %q does not match directory name %q", pkgName, dirName),
		Confidence: 1,
		Node:       file.AST.Name,
		Category:   lint.FailureCategoryNaming,
	}}
}

// StringFormatRule lints strings and/or comments according to a set of regular expressions given as Arguments.
