func stringFormatCallName(call *ast.CallExpr) (string, bool) {
	if ident, ok := call.Fun.(*ast.Ident); ok {
		return ident.Name, true
	}
	if selector, ok := call.Fun.(*ast.SelectorExpr); ok {
		if scope, ok := selector.X.(*ast.Ident); ok {
			return scope.Name + "." + selector.Sel.Name, true
		}
		if recv, ok := selector.X.(*ast.SelectorExpr); ok {
			return recv.Sel.Name + "." + selector.Sel.Name, true
		}
	}
