}

func (r *stringFormatSubrule) apply(call *ast.CallExpr, scope *stringFormatSubruleScope) (lint.Failure, bool) {
	if len(call.Args) <= scope.argument {
		return lint.Failure{}, false
	}
	arg := call.Args[scope.argument]
	var lit *ast.BasicLit
	if scope.field != "" {
		composite, ok := arg.(*ast.CompositeLit)
		if !ok {
			return lint.Failure{}, false
		}
