// UseSlicesSortRule spots calls to sort.* that can be replaced by slices.Sort*.
type UseSlicesSortRule struct{}

func init() { register(&UseSlicesSortRule{}, false) }

// Name returns the rule name.
func (*UseSlicesSortRule) Name() string { return "use-slices-sort" }

var sortToSlices = map[string]string{
	"Ints":              "slices.Sort",
	"Strings":           "slices.Sort",
	"Float64s":          "slices.Sort",
	"Slice":             "slices.SortFunc",
	"SliceStable":       "slices.SortStableFunc",
	"Sort":              "slices.SortFunc",
	"Stable":            "slices.SortStableFunc",
	"IntsAreSorted":     "slices.IsSorted",
	"StringsAreSorted":  "slices.IsSorted",
	"Float64sAreSorted": "slices.IsSorted",
	"SliceIsSorted":     "slices.IsSortedFunc",
	"IsSorted":          "slices.IsSortedFunc",
}

// Apply applies the rule to given file.
func (*UseSlicesSortRule) Apply(file *lint.File, _ lint.Arguments) []lint.Failure {
	if !file.Pkg.IsAtLeastGoVersion(goVersion121) {
		return nil
	}
	var failures []lint.Failure
	ast.Inspect(file.AST, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok || !isIdent(sel.X, "sort") {
			return true
		}
		alt, ok := sortToSlices[sel.Sel.Name]
		if !ok {
			return true
		}
		failures = append(failures, lint.Failure{
			Category:   lint.FailureCategoryMaintenance,
			Confidence: 1,
			Node:       call,
			Failure:    fmt.Sprintf("replace sort.%s by %s", sel.Sel.Name, alt),
		})
		return true
	})
	return failures
}

// RedundantTestMainExitRule spots redundant os.Exit calls in TestMain.
